LastDecoyAnimationName = nil

function GetRandomDecoyAnimationName()
    local count = #DECOY_ANIMATION_NAMES
    if count == 0 then
        return "FUNNY"
    end
    if count == 1 then
        LastDecoyAnimationName = DECOY_ANIMATION_NAMES[1]
        return LastDecoyAnimationName
    end
    local index
    repeat
        index = math.random(1, count)
    until DECOY_ANIMATION_NAMES[index] ~= LastDecoyAnimationName
    LastDecoyAnimationName = DECOY_ANIMATION_NAMES[index]
    return LastDecoyAnimationName
end
