MUSIC_FOLDER = "Music"
MUSIC_PREFIX = "ewv5_"
function ensureMusicFolder()
    if not makefolder then return false end
    if isfolder then
        if not isfolder(MUSIC_FOLDER) then
            pcall(function() makefolder(MUSIC_FOLDER) end)
        end
    else
        pcall(function() makefolder(MUSIC_FOLDER) end)
    end
    return isfolder and isfolder(MUSIC_FOLDER) or true
end
ensureMusicFolder()
function musicFileName(audioName)
    return MUSIC_FOLDER .. "/" .. MUSIC_PREFIX .. tostring(audioName) .. ".mp3"
end
