function RegisterProtectionIndices()
    for i, e in ipairs(ReanimationEmotes) do
        e._ProtectionIndex = i
    end
end

local BOUNCE_CHOPPY_FPS = 10

local BOUNCE_CHOPPY_ANIM_SPEED = 0.1993

local function StartBounceStopMotion(token, track)
    if not token or not track then return end

    local stepTime = 1 / BOUNCE_CHOPPY_FPS
    token.bounceStopMotion = true

    pcall(function()
        track:AdjustSpeed(0)
    end)

    task.spawn(function()
        local lastClock = os.clock()

        while not token.cancelled and ActiveToken == token and track.IsPlaying do
            task.wait(stepTime)

            if token.cancelled or ActiveToken ~= token or not track.IsPlaying then
                break
            end

            local now = os.clock()
            local elapsed = now - lastClock
            lastClock = now

            elapsed = math.clamp(elapsed, 0, stepTime * 2)

            local currentPosition = track.TimePosition
            local newTime = currentPosition + (elapsed * BOUNCE_CHOPPY_ANIM_SPEED)
            local length = track.Length

            if length > 0 and newTime >= length then
                if track.Looped then
                    local wrapped = newTime % length
                    pcall(function()
                        track.TimePosition = wrapped
                    end)
                else
                    pcall(function()
                        track:Stop(0)
                    end)
                    break
                end
            else
                pcall(function()
                    track.TimePosition = newTime
                end)
            end
        end
    end)
end


local RETRO_CHOPPY_FPS = BOUNCE_CHOPPY_FPS
local function StartRetroChoppyMotion(token, track, normalSpeed)
    if not token or not track then return end
    if not RetroModeEnabled then return end
    if track:GetAttribute("EWV5_RetroChoppy") == true then return end

    token.retroChoppyTracks = token.retroChoppyTracks or {}
    local retroSpeed = tonumber(normalSpeed) or 1
    pcall(function()
        local liveSpeed = math.abs(tonumber(track.Speed) or 0)
        if liveSpeed > 0 then
            retroSpeed = liveSpeed
        end
    end)
    token.retroChoppyTracks[track] = retroSpeed

    pcall(function()
        track:SetAttribute("EWV5_RetroChoppy", true)
        track:AdjustSpeed(0)
    end)

    task.spawn(function()
        local stepTime = 1 / RETRO_CHOPPY_FPS
        local lastClock = os.clock()

        while not token.cancelled
            and ActiveToken == token
            and track.IsPlaying
            and token.retroChoppyTracks
            and token.retroChoppyTracks[track] ~= nil
            and RetroModeEnabled do

            task.wait(stepTime)

            if token.cancelled or ActiveToken ~= token or not track.IsPlaying then
                break
            end

            local now = os.clock()
            local elapsed = math.clamp(now - lastClock, 0, stepTime * 2)
            lastClock = now

            local currentPosition = track.TimePosition
            local newTime = currentPosition + (elapsed * retroSpeed)
            local length = track.Length

            if length > 0 and newTime >= length then
                if track.Looped then
                    pcall(function()
                        track.TimePosition = newTime % length
                    end)
                else
                    pcall(function()
                        track:Stop(0)
                    end)
                    break
                end
            else
                pcall(function()
                    track.TimePosition = newTime
                end)
            end
        end

        local savedSpeed = token.retroChoppyTracks and token.retroChoppyTracks[track]
        if token.retroChoppyTracks then
            token.retroChoppyTracks[track] = nil
        end

        if savedSpeed ~= nil and not token.cancelled and ActiveToken == token and track.IsPlaying then
            pcall(function()
                track:SetAttribute("EWV5_RetroChoppy", false)
                track:AdjustSpeed(savedSpeed)
            end)
        end
    end)
end

local function StopRetroChoppyMotion(token, track)
    if not token or not track or not token.retroChoppyTracks then return end
    local savedSpeed = token.retroChoppyTracks[track]
    token.retroChoppyTracks[track] = nil

    if savedSpeed ~= nil and track.IsPlaying then
        pcall(function()
            track:SetAttribute("EWV5_RetroChoppy", false)
            track:AdjustSpeed(savedSpeed)
        end)
    end
end

local function ApplyRetroModeToActiveEmote()
    local token = ActiveToken
    if not token or token.cancelled then return end

    if RetroModeEnabled then
        local baseSpeed = token.emote and (token.emote.AnimationSpeed or 1) or 1
        for _, track in ipairs(token.tracks or {}) do
            if track and track.IsPlaying and track ~= token.bounceTrack then
                StartRetroChoppyMotion(token, track, baseSpeed)
            end
        end
    else
        for track in pairs(token.retroChoppyTracks or {}) do
            StopRetroChoppyMotion(token, track)
        end
    end
end

local function StartRetroTrackWatcher(token)
    if not token then return end

    local connection
    connection = RunService.RenderStepped:Connect(function()
        if token.cancelled or ActiveToken ~= token then
            if connection then
                pcall(function() connection:Disconnect() end)
            end
            return
        end

        if not RetroModeEnabled then return end

        local normalSpeed = token.emote and (token.emote.AnimationSpeed or 1) or 1
        for _, track in ipairs(token.tracks or {}) do
            if track and track.IsPlaying and track ~= token.bounceTrack then
                StartRetroChoppyMotion(token, track, normalSpeed)
            end
        end
    end)

    table.insert(token.connections, connection)
end

