local function StopOwnedProtectionTracks(hum, keepTrack)
    if not hum or not hum.Parent then return end
    local animator = hum:FindFirstChildOfClass("Animator")
    if not animator then return end
    for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
        local isOwned = false
        pcall(function() isOwned = tr:GetAttribute("EWV5_LoggerProtection") == true end)
        if isOwned and tr ~= keepTrack then
            pcall(function() tr:Stop(0) end)
        end
    end
end

local function StopAuxProtection(key)
    local token = AuxProtectionTokens[key]
    if not token then return end
    token.cancelled = true
    AuxProtectionTokens[key] = nil
    if token.tracks then
        for i, tr in ipairs(token.tracks) do
            pcall(function() tr:Stop(0) end)
            pcall(function() tr:Destroy() end)
            token.tracks[i] = nil
        end
    end
    if token.track then
        pcall(function() token.track:Stop(0) end)
        pcall(function() token.track:Destroy() end)
        token.track = nil
    end
    StopOwnedProtectionTracks(token.hum)
end

local function StopAllAuxProtection()
    for key in pairs(AuxProtectionTokens) do
        StopAuxProtection(key)
    end
end

function StopRandomAnimationNoise()
    RandomAnimationNoiseGeneration += 1
    if RandomAnimationNoiseToken then
        RandomAnimationNoiseToken.cancelled = true
        RandomAnimationNoiseToken = nil
    end
    for i, tr in pairs(RandomAnimationNoiseTracks) do
        pcall(function() tr:Stop(0) end)
        pcall(function() tr:Destroy() end)
        RandomAnimationNoiseTracks[i] = nil
    end
    RandomAnimationNoiseTrack = nil
end

local function GetRandomCoverEntry()
    local pool = LOGGER_PROTECTION_MASSIVE_IDS
    if type(pool) ~= "table" or #pool == 0 then
        return nil
    end
    local entry = pool[math.random(1, #pool)]
    if type(entry) == "table" then
        return entry
    end
    local id = tonumber(entry)
    if id then
        return {Id = id, Version = tostring(id)}
    end
    return nil
end

local function BuildGuidCoverAnimationId(numericId)
    numericId = tonumber(numericId)
    if not numericId then return nil end
    return "http" .. HttpService:GenerateGUID() .. "=" .. tostring(numericId)
end

local function BuildVersionCoverAnimationId(entry)
    if type(entry) ~= "table" then return nil end
    local numericId = tonumber(entry.Id)
    local version = tostring(entry.Version or "")
    if not numericId or version == "" then return nil end
    return "http://www.roblox.com/asset/?version=" .. version .. "&id=" .. tostring(numericId)
end

function StartRandomAnimationNoise(token)
    if AnimationIdMode ~= "GUID_COVER" and AnimationIdMode ~= "VERSION_COVER" then
        return
    end
    if not token or token.cancelled then return end
    local hum = token.humanoid
    if not hum or not hum.Parent then return end

    StopRandomAnimationNoise()

    local generation = RandomAnimationNoiseGeneration
    local noiseToken = {cancelled = false, generation = generation, token = token}
    RandomAnimationNoiseToken = noiseToken

    task.spawn(function()
        local first = true
        while not noiseToken.cancelled and not token.cancelled and ActiveToken == token and RandomAnimationNoiseGeneration == generation do
            if not first then
                task.wait(RANDOM_GUID_NOISE_INTERVAL)
            end
            first = false

            if noiseToken.cancelled or token.cancelled or ActiveToken ~= token or RandomAnimationNoiseGeneration ~= generation then
                break
            end

            local entry = GetRandomCoverEntry()
            if entry then
                local useVersionCover = AnimationIdMode == "VERSION_COVER"
                local numericId = tonumber(entry.Id)
                local animationId = useVersionCover and BuildVersionCoverAnimationId(entry) or BuildGuidCoverAnimationId(numericId)
                local coverName = useVersionCover and "Version Cover" or "GUID Cover"
                if animationId then
                    local anim = Instance.new("Animation")
                    anim.Name = coverName
                    anim.AnimationId = animationId

                    local track
                    local ok = pcall(function()
                        track = hum:LoadAnimation(anim)
                    end)
                    anim:Destroy()

                    if ok and track then
                        track.Name = coverName
                        track.Priority = RANDOM_GUID_NOISE_PRIORITY
                        track.Looped = false
                        pcall(function()
                            track:SetAttribute("EWV5_RandomGuidNoise", true)
                            track:SetAttribute("EWV5_CoverName", coverName)
                        end)
                        table.insert(RandomAnimationNoiseTracks, track)
                        RandomAnimationNoiseTrack = track

                        pcall(function()
                            track.Stopped:Connect(function()
                                for index, activeTrack in ipairs(RandomAnimationNoiseTracks) do
                                    if activeTrack == track then
                                        table.remove(RandomAnimationNoiseTracks, index)
                                        break
                                    end
                                end
                                if RandomAnimationNoiseTrack == track then
                                    RandomAnimationNoiseTrack = RandomAnimationNoiseTracks[#RandomAnimationNoiseTracks]
                                end
                                pcall(function() track:Destroy() end)
                            end)
                        end)

                        pcall(function()
                            track:Play(0, 1, 1)
                        end)
                    end
                end
            end
        end

        if RandomAnimationNoiseToken == noiseToken then
            RandomAnimationNoiseToken = nil
        end
    end)
end

