function getSectionPageCount(sectionIndex)
    local section = AnimationSections[sectionIndex]
    return math.max(1, math.ceil(#section.Emotes / MAX_PER_PAGE))
end
function getPageEmotes(page)
    local section = AnimationSections[CurrentSection]
    local source = section and section.Emotes or {}
    local startIdx = (page - 1) * MAX_PER_PAGE + 1
    local endIdx = math.min(startIdx + MAX_PER_PAGE - 1, #source)
    local result = {}
    for i = startIdx, endIdx do
        table.insert(result, source[i])
    end
    return result
end
function getSectionNotificationText(sectionIndex)
    local section = AnimationSections[sectionIndex]
    return section and section.Name or "Animations"
end
