        if e.Url and not ScriptCache[e.Name] then
            local ok, code = pcall(function()
                return game:HttpGet(e.Url)
            end)
            if ok and type(code) == "string" and #code > 0 then
                ScriptCache[e.Name] = code
            end
        end
        if e.AudioUrl and e.AudioName then
            cacheAudioForEmote(e, false)
        end
        preloadDone += 1
        setPreloadStatus(("Loading everything... %d/%d"):format(preloadDone, preloadTotal))
    end))
end
for _, job in ipairs(preloadJobs) do
    pcall(function()
        task.wait(job)
    end)
end
