local function RestoreDirectHeadCamera(token)
    if not token then return end
    if token.cameraConnection then
        pcall(function() token.cameraConnection:Disconnect() end)
        token.cameraConnection = nil
    end
    local hum = token.humanoid
    if hum and hum.Parent then
        pcall(function() hum.CameraOffset = token.oldCameraOffset or Vector3.zero end)
    end
end

local CINEMATIC_HEAD_FOLLOW_SPEED = 28

function StartDirectHeadCamera(token, hum, hrp, head)
    if not token or token.cancelled or not hum or not hrp or not head then return end
    token.oldCameraOffset = hum.CameraOffset
    token.cameraOffsetCurrent = token.oldCameraOffset or Vector3.zero
    RestoreDirectHeadCamera(token)
    token.cameraConnection = RunService.RenderStepped:Connect(function(dt)
        if token.cancelled or ActiveToken ~= token or not IsEmoting or not token.directAnimation then return end
        if not hum.Parent or not hrp.Parent or not head.Parent then return end
        local ok, targetOffset = pcall(function()
            return (hrp.CFrame + Vector3.new(0, 1.5, 0)):ToObjectSpace(head.CFrame).Position
        end)
        if not ok then return end
        local alpha = 1 - math.exp(-CINEMATIC_HEAD_FOLLOW_SPEED * math.clamp(dt, 0, 0.1))
        token.cameraOffsetCurrent = (token.cameraOffsetCurrent or hum.CameraOffset):Lerp(targetOffset, alpha)
        pcall(function() hum.CameraOffset = token.cameraOffsetCurrent end)
    end)
    table.insert(token.connections, token.cameraConnection)
end
