function seqColor(a, b)
    return ColorSequence.new({
        ColorSequenceKeypoint.new(0, a),
        ColorSequenceKeypoint.new(1, b),
    })
end

function randUnit()
    local v = Vector3.new(
        math.random(-100, 100),
        math.random(-100, 100),
        math.random(-100, 100)
    )
    if v.Magnitude < 0.01 then
        return Vector3.new(0, 1, 0)
    end
    return v.Unit
end

function getTorsoPart(hrp)
    local char = hrp and hrp.Parent
    if not char then return hrp end
    return char:FindFirstChild("UpperTorso")
        or char:FindFirstChild("Torso")
        or hrp
end

function getTorsoCFrame(hrp)
    local torso = getTorsoPart(hrp)
    return torso and torso.CFrame or hrp.CFrame
end

local FLOOR_EFFECT_GROUND_CACHE = setmetatable({}, {__mode = "k"})

local function getFloorRaycastIgnoreList(ownCharacter)
    local ignore = {}
    if ownCharacter then
        ignore[#ignore + 1] = ownCharacter
    end
    for _, player in ipairs(Players:GetPlayers()) do
        local character = player.Character
        if character and character ~= ownCharacter then
            ignore[#ignore + 1] = character
        end
    end
    return ignore
end

function getFloorCFrame(hrp, yOffset)
    local character = hrp and hrp.Parent
    if not hrp or not character then
        return CFrame.new()
    end

    local pos = hrp.Position
    local state = FLOOR_EFFECT_GROUND_CACHE[character]
    if not state then
        state = {
            y = nil,
            x = nil,
            z = nil,
        }
        FLOOR_EFFECT_GROUND_CACHE[character] = state
    end

    local dx = state.x and (pos.X - state.x) or math.huge
    local dz = state.z and (pos.Z - state.z) or math.huge
    local movedEnough = (dx * dx + dz * dz) > (0.65 * 0.65)
    local needsInitialSample = state.y == nil

    if needsInitialSample or movedEnough then
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = getFloorRaycastIgnoreList(character)
        params.IgnoreWater = true

        local result = workspace:Raycast(
            pos + Vector3.new(0, 4.0, 0),
            Vector3.new(0, -20.0, 0),
            params
        )

        local valid = false
        if result and result.Instance and result.Normal.Y >= 0.60 then
            local hitY = result.Position.Y
            local maxFloorY = pos.Y - 0.45
            if hitY <= maxFloorY then
                if state.y == nil or math.abs(hitY - state.y) <= 6.0 then
                    state.y = hitY
                    valid = true
                end
            end
        end

        if state.y == nil and not valid then
            state.y = pos.Y - 3.0
        end

        state.x = pos.X
        state.z = pos.Z
    end

    return CFrame.new(pos.X, state.y + (yOffset or 0.08), pos.Z)
end

function addFxPart(folder, size, color, transparency)
    local p = Instance.new("Part")
    p.Name = "FXPart"
    p.Size = size
    p.Transparency = transparency or 1
    p.Anchored = true
    p.CanCollide = false
    p.CanTouch = false
    p.CanQuery = false
    p.CastShadow = false
    p.Massless = true
    p.Material = Enum.Material.Neon
    p.Color = color
    p.Parent = folder
    return p
end

function addEmitter(parent, props)
    local pe = Instance.new("ParticleEmitter")
    for k, v in pairs(props) do
        pcall(function() pe[k] = v end)
    end
    pe.Parent = parent
    return pe
end

function burstEmitter(pe, count)
    if pe and pe.Parent then
        if HideEffectsEnabled then
            pcall(function()
                pe:Clear()
            end)
            return
        end
        pcall(function() pe:Emit(count or 8) end)
    end
end

function addPulsingDisk(folder, color, baseRadius, thickness, y, transparency)
    baseRadius = baseRadius * 0.78
    local disk = addFxPart(folder, Vector3.new(thickness or 0.14, baseRadius * 2, baseRadius * 2), color, transparency or 0.16)
    disk.Name = "PulsingDisk"
    disk.Shape = Enum.PartType.Cylinder
    disk.Material = Enum.Material.Neon
    disk:SetAttribute("BaseRadius", baseRadius)
    disk:SetAttribute("BaseThickness", thickness or 0.14)
    disk:SetAttribute("BaseTransparency", transparency or 0.16)
    disk:SetAttribute("DiskY", y or 0.07)
    return disk
end

function updatePulsingDisk(disk, floorCF, t, pulse, speed, expand)
    local baseRadius = disk:GetAttribute("BaseRadius") or 4
    local baseThickness = disk:GetAttribute("BaseThickness") or 0.14
    local phase = t * (speed or 1.8)
    local wave = (math.sin(phase) + 1) * 0.5
    local radius = baseRadius + pulse * (expand or 0.95) + wave * 0.22
    disk.CFrame = floorCF * CFrame.Angles(0, t * (speed or 1.8), math.rad(90))
    disk.Size = Vector3.new(baseThickness + pulse * 0.08, radius * 2, radius * 2)
    local baseTransparency = disk:GetAttribute("BaseTransparency") or 0.16
    disk.Transparency = math.clamp(baseTransparency - pulse * 0.08, 0.035, 0.4)
end

function addLimbTrail(folder, limb, colors, lifetime, width0, width1)
    if not limb or not limb:IsA("BasePart") then return nil end
    local top = Instance.new("Attachment")
    top.Name = "TrailTop"
    top.Position = Vector3.new(0, limb.Size.Y * 0.48, 0)
    top.Parent = limb

    local bottom = Instance.new("Attachment")
    bottom.Name = "TrailBottom"
    bottom.Position = Vector3.new(0, -limb.Size.Y * 0.48, 0)
    bottom.Parent = limb

    local trail = Instance.new("Trail")
    trail.Name = "EmoteLimbTrail"
    trail.Attachment0 = top
    trail.Attachment1 = bottom
    trail.Lifetime = lifetime or 0.32
    trail.MinLength = 0.02
    trail.FaceCamera = true
    trail.LightEmission = 1
    trail.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.05),
        NumberSequenceKeypoint.new(0.65, 0.22),
        NumberSequenceKeypoint.new(1, 1),
    })
    trail.WidthScale = NumberSequence.new({
        NumberSequenceKeypoint.new(0, width0 or 0.9),
        NumberSequenceKeypoint.new(0.55, width1 or 0.5),
        NumberSequenceKeypoint.new(1, 0),
    })
    trail.Color = seqColor(colors[1], colors[2])
    trail.Parent = folder
    trail.Destroying:Connect(function()
        pcall(function() top:Destroy() end)
        pcall(function() bottom:Destroy() end)
    end)
    return trail
end

function pulsePart(part, baseSize, pulse)
    local s = math.clamp(0.82 + pulse * 0.55, 0.5, 1.55)
    part.Size = baseSize * s
end

function makeBeamPart(folder, color, thickness, length)
    local p = addFxPart(folder, Vector3.new(thickness, thickness, length), color, 0.22)
    p.Material = Enum.Material.Neon
    return p
end

local function AddClientPostEffect(token, className, name)
    if not token or not Lighting then return nil end
    token.customLightingEffects = token.customLightingEffects or {}

    local effect = Instance.new(className)
    effect.Name = name
    effect:SetAttribute("EWV5_ClientPostEffect", true)
    effect.Parent = Lighting
    token.customLightingEffects[#token.customLightingEffects + 1] = effect
    return effect
end

local function createBeatBeam(folder, name, color, position, length, width, brightness)
    local part = addFxPart(folder, Vector3.new(width, width, length), color, 0.18)
    part.Name = name
    part.Material = Enum.Material.Neon
    part.CFrame = CFrame.new(position) * CFrame.Angles(math.rad(90), 0, 0)

    local light = Instance.new("SpotLight")
    light.Name = name .. "Light"
    light.Color = color
    light.Brightness = brightness or 5
    light.Range = length * 1.35
    light.Angle = 18
    light.Shadows = true
    light.Face = Enum.NormalId.Bottom
    light.Parent = part

    return part, light
end

local function styleAnimePart(part)
    if not part or not part:IsA("BasePart") then return end
    if part.Name == "HumanoidRootPart" then return end
    pcall(function()
        part.Material = Enum.Material.SmoothPlastic
        part.Reflectance = 0
    end)
end

