function addRing(folder, color, radius, thickness, y)
    local ring = addFxPart(folder, Vector3.new(0.25, 0.25, 0.25), color, 0.22)
    ring.Shape = Enum.PartType.Cylinder
    ring.Material = Enum.Material.Neon
    ring.Size = Vector3.new(thickness, radius * 2, radius * 2)
    ring.CFrame = CFrame.new(0, y, 0) * CFrame.Angles(0, 0, math.rad(90))
    return ring, radius
end

function addFloatingOrb(folder, color, size, offset)
    local p = Instance.new("Part")
    p.Shape = Enum.PartType.Ball
    p.Size = Vector3.new(size, size, size)
    p.Material = Enum.Material.Neon
    p.Color = color
    p.Transparency = 0.08
    p.Anchored = true
    p.CanCollide = false
    p.CanTouch = false
    p.CanQuery = false
    p.CastShadow = false
    p.Parent = folder
    p:SetAttribute("BaseSize", size)
    p:SetAttribute("OffsetX", offset.X)
    p:SetAttribute("OffsetY", offset.Y)
    p:SetAttribute("OffsetZ", offset.Z)
    return p
end

function startScenarioFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)

    local rings = {}
    for i = 1, 4 do
        rings[i] = addPulsingDisk(folder, c[(i % 3) + 1], 2.55 + i * 0.42, 0.14, 0.08 + i * 0.018, 0.10 + i * 0.025)
    end

    local trailParts = {}
    local char = hrp.Parent
    for _, name in ipairs({"Left Arm", "Right Arm"}) do
        local limb = char and char:FindFirstChild(name)
        if limb then trailParts[#trailParts + 1] = addLimbTrail(folder, limb, c, 0.34, 1.0, 0.55) end
    end

    local streaks = {}
    for i = 1, 7 do
        local streak = addFxPart(folder, Vector3.new(0.09, 0.09, 3.2 + i * 0.4), c[(i % 3) + 1], 0.18)
        streaks[i] = streak
    end

    local trail = addEmitter(core, {
        Texture = "rbxassetid://6893912008", Rate = 10, Speed = NumberRange.new(1, 4),
        Lifetime = NumberRange.new(0.28, 0.62), SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1, Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.22), NumberSequenceKeypoint.new(0.45, 0.62), NumberSequenceKeypoint.new(1, 0),
        }), Transparency = NumberSequence.new(0.25), Color = seqColor(c[1], c[2]),
    })

    return function(t, pulse)
        local torsoCF = getTorsoCFrame(hrp)
        core.CFrame = torsoCF
        light.Color = c[1 + (math.floor(t * 3) % 3)]
        light.Brightness = 0.8 + pulse * 5
        light.Range = 10 + pulse * 8

        local floorCF = getFloorCFrame(hrp, 0.06)
        for i, ring in ipairs(rings) do
            updatePulsingDisk(ring, floorCF, t + i * 0.22, pulse, 1.5 + i * 0.2, 1.8 + i * 0.25)
        end

        for i, streak in ipairs(streaks) do
            local a = t * (1.8 + i * 0.08) + i
            local r = 2.1 + pulse * 0.9
            streak.CFrame = torsoCF * CFrame.new(math.cos(a) * r, math.sin(t * 2 + i) * 1.35, math.sin(a) * r) * CFrame.Angles(a, a * 0.7, t)
            local z = 1.9 + pulse * 1.8
            streak.Size = Vector3.new(0.08 + pulse * 0.04, 0.08 + pulse * 0.04, z)
            streak.Transparency = 0.12 + (1 - pulse) * 0.22
        end

        trail.Rate = 7 + math.floor(pulse * 22)
        if pulse > 0.72 then burstEmitter(spark, 4 + math.floor(pulse * 5)) end
    end
end

