function startChronoFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)

    local white = Color3.fromRGB(235, 255, 255)
    local cyan = Color3.fromRGB(45, 245, 255)
    local blue = Color3.fromRGB(90, 135, 255)
    local gold = Color3.fromRGB(255, 210, 80)

    pcall(function()
        light.Color = cyan
        light.Brightness = 0
        light.Range = 18
    end)

    local floorRings = {}
    for i = 1, 5 do
        local ring = addFxPart(folder, Vector3.new(0.07 + i * 0.012, 3.2, 3.2), i % 2 == 0 and blue or cyan, 0.34)
        ring.Shape = Enum.PartType.Cylinder
        ring.Material = Enum.Material.Neon
        floorRings[i] = ring
    end

    local clockHandA = addFxPart(folder, Vector3.new(0.055, 0.055, 2.7), white, 0.16)
    local clockHandB = addFxPart(folder, Vector3.new(0.045, 0.045, 1.85), gold, 0.08)

    local hourMarkers = {}
    for i = 1, 12 do
        local marker = addFxPart(folder, Vector3.new(0.055, 0.055, 0.44), white, 0.22)
        hourMarkers[i] = marker
    end

    local afterimages = {}
    local afterimageColors = {cyan, blue, gold}
    for i = 1, 8 do
        local ghost = addFxPart(folder, Vector3.new(0.08, 0.08, 1.8), afterimageColors[(i - 1) % 3 + 1], 0.58)
        afterimages[i] = ghost
    end

    local timeStreak = addEmitter(core, {
        Texture = "rbxassetid://6893912008",
        Rate = 7,
        Speed = NumberRange.new(5, 11),
        Lifetime = NumberRange.new(0.16, 0.38),
        Rotation = NumberRange.new(0, 360),
        RotSpeed = NumberRange.new(-360, 360),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.08),
            NumberSequenceKeypoint.new(0.32, 0.46),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.06),
            NumberSequenceKeypoint.new(0.7, 0.28),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = seqColor(cyan, blue),
    })

    local rewindBurst = addEmitter(core, {
        Texture = "rbxassetid://243660364",
        Rate = 0,
        Speed = NumberRange.new(7, 16),
        Lifetime = NumberRange.new(0.18, 0.42),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.08),
            NumberSequenceKeypoint.new(0.22, 0.65),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.04),
            NumberSequenceKeypoint.new(0.65, 0.26),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = seqColor(white, gold),
    })

    local lastBurst = -math.huge

    return function(t, pulse)
        if not hrp.Parent or not folder.Parent then return end

        local rootCF = hrp.CFrame
        local floorCF = getFloorCFrame(hrp, 0.06)
        local torsoCF = getTorsoCFrame(hrp)
        local beat = math.clamp(pulse * 1.35, 0, 1)

        core.CFrame = rootCF
        light.Color = (math.floor(t * 3) % 2 == 0) and cyan or blue
        light.Brightness = 0.8 + beat * 8
        light.Range = 14 + beat * 12

        for i, ring in ipairs(floorRings) do
            local phase = t * (i % 2 == 0 and -1.35 or 1.65) + i * 0.48
            local radius = 1.65 + i * 0.55 + beat * (0.9 + i * 0.22)
            ring.CFrame = floorCF * CFrame.Angles(0, phase, math.rad(90))
            ring.Size = Vector3.new(0.06 + beat * 0.07, radius * 2, radius * 2)
            ring.Transparency = math.clamp(0.42 - beat * 0.30, 0.08, 0.52)
        end

        local clockCF = floorCF * CFrame.Angles(0, 0, math.rad(90))
        local spin = -t * 0.75

        clockHandA.CFrame = clockCF * CFrame.new(0, 0, 0) * CFrame.Angles(0, spin, 0)
        clockHandA.Size = Vector3.new(0.055, 0.055, 2.25 + beat * 0.55)

        clockHandB.CFrame = clockCF * CFrame.new(0, 0, 0) * CFrame.Angles(0, -spin * 1.65, 0)
        clockHandB.Size = Vector3.new(0.045, 0.045, 1.40 + beat * 0.45)

        for i, marker in ipairs(hourMarkers) do
            local a = ((i - 1) / 12) * math.pi * 2
            local r = 1.78 + beat * 0.35
            marker.CFrame = floorCF
                * CFrame.new(math.cos(a) * r, 0, math.sin(a) * r)
                * CFrame.Angles(0, a, math.rad(90))
            local len = (i % 3 == 0) and 0.58 or 0.36
            marker.Size = Vector3.new(0.055, 0.055, len + beat * 0.10)
            marker.Transparency = 0.24 + (1 - beat) * 0.25
        end

        for i, ghost in ipairs(afterimages) do
            local offset = (i - 4.5) * 0.21
            local fade = math.clamp(0.83 - math.abs(i - 4.5) * 0.10 - beat * 0.24, 0.30, 0.90)
            ghost.CFrame = torsoCF
                * CFrame.new(offset + math.sin(t * 9 + i) * 0.04, 0.15, 0.10)
                * CFrame.Angles(0, math.rad(90), math.sin(t * 5 + i) * 0.18)
            ghost.Transparency = fade
            ghost.Size = Vector3.new(0.055 + beat * 0.03, 0.055 + beat * 0.03, 1.1 + beat * 1.6)
        end

        timeStreak.Rate = 5 + math.floor(beat * 26)

        if beat > 0.82 and t - lastBurst > 0.18 then
            lastBurst = t
            burstEmitter(rewindBurst, 8 + math.floor(beat * 10))
            burstEmitter(spark, 4 + math.floor(beat * 4))
        end
    end
end
function startSpringtrapFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)

    local decayGreen = Color3.fromRGB(110, 255, 80)
    local acidGreen = Color3.fromRGB(55, 220, 105)
    local sickYellow = Color3.fromRGB(215, 255, 70)
    local shadowGreen = Color3.fromRGB(35, 105, 55)

    pcall(function()
        light.Color = decayGreen
        light.Brightness = 0
        light.Range = 14
    end)

    local stompRings = {}
    for i = 1, 4 do
        local ring = addFxPart(folder, Vector3.new(0.08, 2.0, 2.0), i % 2 == 0 and acidGreen or decayGreen, 0.28)
        ring.Shape = Enum.PartType.Cylinder
        ring.Material = Enum.Material.Neon
        stompRings[i] = ring
    end

    local jaggedRays = {}
    for i = 1, 10 do
        local ray = addFxPart(folder, Vector3.new(0.07, 0.07, 1.1), i % 3 == 0 and sickYellow or acidGreen, 0.34)
        ray.Material = Enum.Material.Neon
        jaggedRays[i] = ray
    end

    local glitchBars = {}
    for i = 1, 6 do
        local bar = addFxPart(folder, Vector3.new(0.08, 0.08, 1.6 + (i % 3) * 0.42), shadowGreen, 0.45)
        glitchBars[i] = bar
    end

    local eyes = {}
    local head = hrp.Parent and hrp.Parent:FindFirstChild("Head")
    if head then
        for _, x in ipairs({-0.17, 0.17}) do
            local eye = addFxPart(folder, Vector3.new(0.12, 0.19, 0.17), sickYellow, 0.04)
            eyes[#eyes + 1] = {part = eye, x = x}
        end
    end

    local footParts = {}
    local character = hrp.Parent
    for _, footName in ipairs({"LeftFoot", "RightFoot", "Left Leg", "Right Leg"}) do
        local foot = character and character:FindFirstChild(footName)
        if foot and foot:IsA("BasePart") then
            footParts[#footParts + 1] = {part = foot, previousBottom = nil, wasNearFloor = false}
        end
    end

    local function createFootSmoke(position, strength)
        if not folder.Parent then return end

        local contact = addFxPart(folder, Vector3.new(0.12, 0.12, 0.12), Color3.fromRGB(115, 125, 105), 1)
        contact.CFrame = CFrame.new(position + Vector3.new(0, 0.06, 0))

        local smoke = addEmitter(contact, {
            Texture = "rbxassetid://296874871",
            Rate = 0,
            Speed = NumberRange.new(2.2, 5.2) * (0.82 + strength * 0.38),
            Lifetime = NumberRange.new(0.30, 0.72),
            Rotation = NumberRange.new(0, 360),
            RotSpeed = NumberRange.new(-160, 160),
            SpreadAngle = Vector2.new(360, 360),
            Acceleration = Vector3.new(0, 1.8, 0),
            LightEmission = 0,
            LightInfluence = 1,
            Size = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.42 + strength * 0.16),
                NumberSequenceKeypoint.new(0.35, 1.10 + strength * 0.45),
                NumberSequenceKeypoint.new(0.78, 1.65 + strength * 0.58),
                NumberSequenceKeypoint.new(1, 0),
            }),
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.38),
                NumberSequenceKeypoint.new(0.40, 0.58),
                NumberSequenceKeypoint.new(1, 1),
            }),
            Color = ColorSequence.new(Color3.fromRGB(95, 105, 95), Color3.fromRGB(155, 160, 145)),
        })

        smoke:Emit(5 + math.floor(strength * 4))

        local ring = addFxPart(folder, Vector3.new(0.05, 1.0, 1.0), Color3.fromRGB(130, 145, 120), 0.72)
        ring.Shape = Enum.PartType.Cylinder
        ring.Material = Enum.Material.SmoothPlastic
        ring.CFrame = CFrame.new(position + Vector3.new(0, 0.045, 0)) * CFrame.Angles(0, 0, math.rad(90))

        TweenService:Create(
            ring,
            TweenInfo.new(0.34, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {Size = Vector3.new(0.035, 2.9 + strength * 1.15, 2.9 + strength * 1.15), Transparency = 1}
        ):Play()

        task.delay(0.85, function()
            pcall(function() contact:Destroy() end)
            pcall(function() ring:Destroy() end)
        end)
    end

    local dust = addEmitter(core, {
        Texture = "rbxassetid://296874871",
        Rate = 16,
        Speed = NumberRange.new(0.5, 3.5),
        Lifetime = NumberRange.new(0.42, 1.0),
        Rotation = NumberRange.new(0, 360),
        RotSpeed = NumberRange.new(-180, 180),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 0.8,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.10),
            NumberSequenceKeypoint.new(0.48, 0.44),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.18),
            NumberSequenceKeypoint.new(0.72, 0.34),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = seqColor(decayGreen, acidGreen),
    })

    local staticBurst = addEmitter(core, {
        Texture = "rbxassetid://243660364",
        Rate = 0,
        Speed = NumberRange.new(4, 13),
        Lifetime = NumberRange.new(0.12, 0.36),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.08),
            NumberSequenceKeypoint.new(0.24, 0.52),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.02),
            NumberSequenceKeypoint.new(0.62, 0.26),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = seqColor(sickYellow, decayGreen),
    })

    local lastStomp = -math.huge
    local lastStatic = -math.huge

    return function(t, pulse)
        if not hrp.Parent or not folder.Parent then return end

        if token.bouncinEffectHidden or HideEffectsEnabled then
            if not token.bouncinEffectHidden then
                token.bouncinEffectHidden = true
                if token.bouncinSketchRestore then
                    token.bouncinSketchRestore()
                end
            end
            if token.bouncinSetHidden then
                token.bouncinSetHidden(true)
            end
            return
        end

        local torsoCF = getTorsoCFrame(hrp)
        local floorCF = getFloorCFrame(hrp, 0.055)
        local stomp = math.clamp(pulse * 1.55, 0, 1)

        core.CFrame = torsoCF
        light.Color = (math.floor(t * 7) % 2 == 0) and decayGreen or sickYellow
        light.Brightness = 0.5 + stomp * 7
        light.Range = 9 + stomp * 10

        for i, ring in ipairs(stompRings) do
            local phase = t * (1.35 + i * 0.22) * (i % 2 == 0 and -1 or 1)
            local radius = 1.0 + i * 0.72 + stomp * (1.15 + i * 0.30)
            ring.CFrame = floorCF * CFrame.Angles(0, phase, math.rad(90))
            ring.Size = Vector3.new(0.07 + stomp * 0.09, radius * 2, radius * 2)
            ring.Transparency = math.clamp(0.42 - stomp * 0.30 + i * 0.025, 0.12, 0.55)
        end

        for i, ray in ipairs(jaggedRays) do
            local a = ((i - 1) / #jaggedRays) * math.pi * 2 + t * 0.75
            local r = 1.55 + stomp * 0.85
            local y = 0.10 + math.abs(math.sin(t * 3.0 + i)) * (0.35 + stomp * 0.60)
            ray.CFrame = torsoCF
                * CFrame.new(math.cos(a) * r, y, math.sin(a) * r)
                * CFrame.Angles(a * 0.7, t * 2.2 + i, math.sin(t * 4 + i))
            ray.Size = Vector3.new(0.055 + stomp * 0.035, 0.055 + stomp * 0.035, 0.70 + stomp * 1.05)
            ray.Transparency = 0.25 + (1 - stomp) * 0.28
        end

        for i, bar in ipairs(glitchBars) do
            local phase = t * (3.8 + i * 0.34) + i * 1.3
            local width = 0.55 + math.abs(math.sin(phase)) * 1.35 + stomp * 0.55
            local y = -1.0 + ((i * 0.47 + t * 2.0) % 2.9)
            bar.CFrame = torsoCF
                * CFrame.new(math.sin(phase) * 1.1, y, -0.22)
                * CFrame.Angles(0, 0, math.sin(phase * 2.4) * 0.35)
            bar.Size = Vector3.new(0.045 + stomp * 0.025, 0.045 + stomp * 0.025, width)
            bar.Transparency = 0.40 + math.abs(math.sin(phase)) * 0.25
        end

        if #eyes == 2 then
            for _, data in ipairs(eyes) do
                if data.part and data.part.Parent and head and head.Parent then
                    local flicker = 0.04 + math.abs(math.sin(t * 11 + data.x * 20)) * 0.08
                    data.part.CFrame = head.CFrame * CFrame.new(data.x, 0.20, -0.52)
                    data.part.Size = Vector3.new(0.12, 0.19 + stomp * 0.09, 0.17 + flicker + stomp * 0.05)
                    data.part.Transparency = 0.02 + (1 - stomp) * 0.14
                end
            end
        end

        dust.Rate = 12 + math.floor(stomp * 30)

        local groundY = floorCF.Position.Y
        for _, footData in ipairs(footParts) do
            local foot = footData.part
            if foot and foot.Parent then
                local bottomY = foot.Position.Y - foot.Size.Y * 0.5
                local gap = bottomY - groundY
                local descending = footData.previousBottom ~= nil and (footData.previousBottom - bottomY) > 0.012
                local touching = gap <= 0.095 and gap >= -0.08

                if touching and descending and not footData.wasNearFloor and t - lastStomp > 0.07 then
                    footData.wasNearFloor = true
                    lastStomp = t
                    local contactPosition = Vector3.new(foot.Position.X, groundY + 0.035, foot.Position.Z)
                    local impactStrength = math.clamp(0.55 + stomp * 0.80, 0.55, 1.45)
                    createFootSmoke(contactPosition, impactStrength)
                elseif gap > 0.17 then
                    footData.wasNearFloor = false
                end

                footData.previousBottom = bottomY
            end
        end

        if stomp > 0.74 and t - lastStomp > 0.16 then
            lastStomp = t
            burstEmitter(staticBurst, 6 + math.floor(stomp * 10))
            burstEmitter(spark, 4 + math.floor(stomp * 5))
        end

        if stomp > 0.90 and t - lastStatic > 0.42 then
            lastStatic = t
            for _, bar in ipairs(glitchBars) do
                bar.Transparency = 0.04
            end
        end
    end
end
