function startTennaFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)
    local scan = {}
    for i = 1, 6 do
        scan[i] = addFxPart(folder, Vector3.new(7.2, 0.035, 0.08), c[(i % 2) + 1], 0.30)
    end
    local dots = {}
    for i = 1, 16 do dots[i] = addFloatingOrb(folder, c[(i % 3) + 1], 0.13, Vector3.zero) end

    return function(t, pulse)
        local rootCF = hrp.CFrame
        core.CFrame = rootCF
        light.Color = c[1 + (math.floor(t * 5) % 2)]
        light.Brightness = 0.7 + pulse * 5.2

        for i, bar in ipairs(scan) do
            local y = 2.4 - ((t * 3.2 + i * 0.58) % 4.8)
            bar.CFrame = rootCF * CFrame.new(0, y, -0.18)
            bar.Size = Vector3.new(6.7 + pulse * 3.2, 0.035 + pulse * 0.025, 0.08)
            bar.Transparency = 0.20 + (1 - pulse) * 0.25
        end
        for i, dot in ipairs(dots) do
            local gx = ((i - 1) % 4) - 1.5
            local gy = math.floor((i - 1) / 4) - 1.5
            local jitter = pulse * math.sin(t * 10 + i)
            dot.CFrame = rootCF * CFrame.new(gx * 0.58 + jitter, gy * 0.58, -2.0 - pulse * 0.25)
            local s = 0.10 + pulse * 0.12
            dot.Size = Vector3.new(s, s, s)
        end
        if pulse > 0.82 then burstEmitter(spark, 6 + math.floor(pulse * 4)) end
    end
end

