            0.12 + (i % 3) * 0.045,
            Vector3.zero
        )
    end

    local feathers = {}
    for i = 1, 12 do
        local side = i <= 6 and -1 or 1
        local n = ((i - 1) % 6) + 1
        local color = c[(i - 1) % #c + 1]
        local feather = addFxPart(folder, Vector3.new(0.065, 0.065, 1.7 + n * 0.23), color, 0.22)
        feather.Material = Enum.Material.Neon
        feathers[i] = feather
    end

    local wingRoot = addFxPart(folder, Vector3.new(1.65, 1.25, 0.12), c[2], 0.30)
    wingRoot.Material = Enum.Material.Neon

    local wingRibs = {}
    for sideIndex = 1, 2 do
        local side = sideIndex == 1 and -1 or 1
        for i = 1, 4 do
            local rib = addFxPart(folder, Vector3.new(0.08, 0.08, 1.15 + i * 0.34), c[(i + sideIndex) % #c + 1], 0.18)
            wingRibs[#wingRibs + 1] = {part = rib, side = side, index = i}
        end
    end

    local ribbon = addEmitter(core, {
        Texture = "rbxassetid://6893912008",
        Rate = 11,
        Speed = NumberRange.new(0.5, 3.0),
        Lifetime = NumberRange.new(0.24, 0.62),
        Rotation = NumberRange.new(0, 360),
        RotSpeed = NumberRange.new(-240, 240),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.18),
            NumberSequenceKeypoint.new(0.28, 0.48),
            NumberSequenceKeypoint.new(0.72, 0.22),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.12),
            NumberSequenceKeypoint.new(0.75, 0.22),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = seqColor(c[1], c[2]),
    })

    local burst = addEmitter(core, {
        Texture = "rbxassetid://192664810",
        Rate = 0,
        Speed = NumberRange.new(2.5, 6.5),
        Lifetime = NumberRange.new(0.28, 0.7),
        Rotation = NumberRange.new(0, 360),
        RotSpeed = NumberRange.new(-360, 360),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.12),
            NumberSequenceKeypoint.new(0.22, 0.55),
            NumberSequenceKeypoint.new(0.65, 0.22),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.05),
            NumberSequenceKeypoint.new(0.65, 0.18),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = seqColor(c[2], c[3]),
    })

    local trailParts = {}
    if character then
        for _, limbName in ipairs({"Left Arm", "Right Arm", "Left Leg", "Right Leg"}) do
            local limb = character:FindFirstChild(limbName)
            if limb then
                trailParts[#trailParts + 1] = addLimbTrail(folder, limb, c, 0.27, 0.72, 0.34)
            end
        end
    end

    local lastBeat = -math.huge
    return function(t, pulse)
        local torsoCF = getTorsoCFrame(hrp)
        local floorCF = getFloorCFrame(hrp, 0.055)
        local dancePulse = math.clamp(pulse * 1.1, 0, 1)
        local wave = (math.sin(t * 7.2) + 1) * 0.5
        local snap = math.max(dancePulse, wave * 0.42)

        core.CFrame = torsoCF
        aura.CFrame = torsoCF * CFrame.new(0, 0.15, 0)
        local auraScale = 0.72 + snap * 1.8
        aura.Size = Vector3.new(auraScale, auraScale, auraScale)
        aura.Transparency = math.clamp(0.78 - snap * 0.34, 0.34, 0.82)
        auraLight.Color = c[1 + (math.floor(t * 8) % 3)]
        auraLight.Brightness = 0.45 + snap * 2.8
        auraLight.Range = 8 + snap * 7

        light.Color = c[1 + (math.floor(t * 6) % 3)]
        light.Brightness = 0.5 + snap * 4.2
        light.Range = 9 + snap * 7

        for i, ring in ipairs(floorRings) do
            updatePulsingDisk(ring, floorCF, t + i * 0.19, snap, 2.05 + i * 0.17, 1.5 + i * 0.22)
            ring.Transparency = math.clamp(0.26 - snap * 0.13 + i * 0.012, 0.045, 0.34)
        end

        for i, orb in ipairs(orbiters) do
            local a = t * (1.8 + (i % 5) * 0.16) + i * (math.pi * 2 / #orbiters)
            local band = (i % 4) * 0.46
            local r = 1.45 + band + snap * 1.05
            local y = 0.15 + math.sin(t * 3.7 + i * 0.82) * (0.45 + snap * 0.4) + ((i % 3) - 1) * 0.38
            orb.CFrame = torsoCF * CFrame.new(math.cos(a) * r, y, math.sin(a) * r)
            local s = (0.105 + (i % 3) * 0.04) * (0.9 + snap * 1.15)
            orb.Size = Vector3.new(s, s, s)
            orb.Transparency = math.clamp(0.18 - snap * 0.08, 0.035, 0.24)
        end

        for i, feather in ipairs(feathers) do
            local side = i <= 6 and -1 or 1
            local n = ((i - 1) % 6) + 1
            local spread = 0.9 + n * 0.34
            local lift = 0.55 + n * 0.20
            local depth = 0.15 + n * 0.12
            local flutter = math.sin(t * 5.5 + n * 0.55) * (0.08 + snap * 0.12)
            feather.CFrame = torsoCF
                * CFrame.new(side * spread, 0.45 + lift + flutter, 1.55 + depth)
                * CFrame.Angles(math.rad(-8 + n * 4), side * math.rad(8 + n * 2), side * math.rad(10))
            feather.Size = Vector3.new(0.055 + snap * 0.035, 0.055 + snap * 0.035, 1.45 + n * 0.25 + snap * 0.55)
            feather.Transparency = math.clamp(0.27 - snap * 0.17, 0.045, 0.32)
        end

        for _, item in ipairs(wingRibs) do
            local side = item.side
            local i = item.index
            local rib = item.part
            local fan = 0.7 + i * 0.42
            local y = 0.15 + i * 0.35 + math.sin(t * 4.1 + i) * 0.08
            rib.CFrame = torsoCF
                * CFrame.new(side * (1.0 + i * 0.48 + snap * 0.4), y, 1.55)
                * CFrame.Angles(0, side * math.rad(18 + i * 5), side * math.rad(42 + fan * 2))
            local len = 1.05 + i * 0.34 + snap * 0.45
            rib.Size = Vector3.new(0.065 + snap * 0.025, 0.065 + snap * 0.025, len)
            rib.Transparency = math.clamp(0.21 - snap * 0.12, 0.04, 0.27)
        end

        ribbon.Rate = 8 + math.floor(snap * 26)
        if snap > 0.72 and t - lastBeat > 0.12 then
            lastBeat = t
            burstEmitter(burst, 8 + math.floor(snap * 18))
            burstEmitter(spark, 5 + math.floor(snap * 8))
        end
    end
end

