            shell.CFrame = torsoCF * CFrame.new(math.cos(a) * r, math.sin(a * 1.7) * 1.2, math.sin(a) * r) * CFrame.Angles(a, 0, a * 0.4)
            local len = 0.8 + pulse * 1.4
            shell.Size = Vector3.new(0.06 + pulse * 0.03, 0.06 + pulse * 0.03, len)
        end
        if pulse > 0.84 then burstEmitter(spark, 4 + math.floor(pulse * 3)) end
