function startKwikFlipFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)

    local orange = Color3.fromRGB(255, 105, 35)
    local brightOrange = Color3.fromRGB(255, 185, 55)
    local white = Color3.fromRGB(255, 255, 255)
    local hotPink = Color3.fromRGB(255, 70, 190)

    pcall(function()
        light.Color = orange
        light.Brightness = 0
        light.Range = 16
    end)

    local impactRings = {}
    for i = 1, 3 do
        local ring = addFxPart(folder, Vector3.new(0.08, 2.4, 2.4), i == 2 and white or orange, 0.28 + i * 0.06)
        ring.Shape = Enum.PartType.Cylinder
        ring.Material = Enum.Material.Neon
        impactRings[i] = ring
    end

    local speedLines = {}
    for i = 1, 12 do
        local line = addFxPart(folder, Vector3.new(0.06, 0.06, 1.4 + (i % 4) * 0.42), i % 3 == 0 and hotPink or brightOrange, 0.34)
        speedLines[i] = line
    end

    local orbitDots = {}
    for i = 1, 8 do
        orbitDots[i] = addFloatingOrb(folder, i % 2 == 0 and white or brightOrange, 0.16, Vector3.zero)
    end

    local burst = addEmitter(core, {
        Texture = "rbxassetid://243660364",
        Rate = 0,
        Speed = NumberRange.new(7, 15),
        Lifetime = NumberRange.new(0.12, 0.34),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.07),
            NumberSequenceKeypoint.new(0.24, 0.60),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.03),
            NumberSequenceKeypoint.new(0.58, 0.22),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, white),
            ColorSequenceKeypoint.new(0.45, brightOrange),
            ColorSequenceKeypoint.new(1, hotPink),
        }),
    })

    local flipTrail = addEmitter(core, {
        Texture = "rbxassetid://6893912008",
        Rate = 9,
        Speed = NumberRange.new(3, 9),
        Lifetime = NumberRange.new(0.14, 0.36),
        SpreadAngle = Vector2.new(45, 45),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.07),
            NumberSequenceKeypoint.new(0.32, 0.42),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.05),
            NumberSequenceKeypoint.new(0.62, 0.30),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = seqColor(brightOrange, hotPink),
    })

    local lastBurst = -math.huge

    return function(t, pulse)
        if not hrp.Parent or not folder.Parent then return end

        local rootCF = hrp.CFrame
        local torsoCF = getTorsoCFrame(hrp)
        local floorCF = getFloorCFrame(hrp, 0.055)
        local kick = math.clamp(pulse * 1.45, 0, 1)

        core.CFrame = rootCF
        light.Color = (math.floor(t * 10) % 2 == 0) and orange or hotPink
        light.Brightness = 0.8 + kick * 8
        light.Range = 11 + kick * 11

        for i, ring in ipairs(impactRings) do
            local phase = t * (2.6 + i * 0.35) * (i % 2 == 0 and -1 or 1)
            local radius = 1.25 + i * 0.62 + kick * (1.1 + i * 0.35)
            ring.CFrame = floorCF * CFrame.Angles(0, phase, math.rad(90))
            ring.Size = Vector3.new(0.06 + kick * 0.08, radius * 2, radius * 2)
            ring.Transparency = math.clamp(0.46 - kick * 0.34 + i * 0.04, 0.09, 0.58)
        end

        for i, line in ipairs(speedLines) do
            local a = ((i - 1) / #speedLines) * math.pi * 2 + t * (4.4 + i * 0.05)
            local r = 1.55 + (i % 4) * 0.42 + kick * 0.75
            local y = math.sin(t * 8 + i * 1.7) * (0.55 + kick * 0.65)
            line.CFrame = torsoCF
                * CFrame.new(math.cos(a) * r, y, math.sin(a) * r)
                * CFrame.Angles(a, math.cos(a) * 0.8, t * 5 + i)
            line.Size = Vector3.new(0.045 + kick * 0.035, 0.045 + kick * 0.035, 0.70 + kick * 1.65)
            line.Transparency = 0.30 + (1 - kick) * 0.30
        end

        for i, orb in ipairs(orbitDots) do
            local a = -t * (3.3 + i * 0.10) + i * math.pi * 2 / #orbitDots
            local r = 1.8 + kick * 0.85
            local y = math.sin(t * 5.5 + i) * (0.6 + kick * 0.35)
            orb.CFrame = torsoCF * CFrame.new(math.cos(a) * r, y, math.sin(a) * r)
            local s = 0.10 + kick * 0.13 + (i % 2) * 0.03
            orb.Size = Vector3.new(s, s, s)
        end

        flipTrail.Rate = 7 + math.floor(kick * 30)

        if kick > 0.76 and t - lastBurst > 0.10 then
            lastBurst = t
            burstEmitter(burst, 8 + math.floor(kick * 12))
            burstEmitter(spark, 3 + math.floor(kick * 5))
        end
    end
end
