            local radius = 1.7 + i * 0.48 + club * (0.8 + i * 0.22)
            ring.CFrame = floorCF * CFrame.Angles(0, a, math.rad(90))
            ring.Size = Vector3.new(0.06 + club * 0.08, radius * 2, radius * 2)
            ring.Transparency = math.clamp(0.45 - club * 0.33 + i * 0.02, 0.08, 0.55)
        end

        for i, beam in ipairs(laserBeams) do
            local a = ((i - 1) / #laserBeams) * math.pi * 2 + t * 1.25
            local r = 2.3 + club * 0.7
            local y = 1.0 + math.sin(t * 3.4 + i) * 1.15
            beam.CFrame = torsoCF
                * CFrame.new(math.cos(a) * r, y, math.sin(a) * r)
                * CFrame.Angles(0.15 + math.sin(t * 2 + i) * 0.18, -a, t * 2.2)
            beam.Size = Vector3.new(0.045 + club * 0.035, 0.045 + club * 0.035, 2.0 + club * 2.5)
            beam.Transparency = 0.34 + (1 - club) * 0.32
        end

        for i, orb in ipairs(notes) do
            local a = t * (1.8 + (i % 3) * 0.16) + i * math.pi * 2 / #notes
            local r = 2.05 + club * 0.95
            local y = 0.35 + math.sin(t * 4 + i) * (0.8 + club * 0.35)
            orb.CFrame = torsoCF * CFrame.new(math.cos(a) * r, y, math.sin(a) * r)
            local s = 0.09 + club * 0.14 + (i % 2) * 0.02
            orb.Size = Vector3.new(s, s, s)
        end

        for i, data in ipairs(beamLights) do
            local side = (i % 2 == 0) and 1 or -1
            local sweep = math.sin(t * 1.7 + i * 0.8) * (1.1 + club * 1.0)
            local yaw = side * (0.55 + club * 0.28) + sweep * 0.12
            data.part.CFrame = rootCF
                * CFrame.new(side * (1.15 + club * 0.35), 1.25 + math.sin(t * 2.1 + i) * 0.45, -0.4)
                * CFrame.Angles(math.rad(-18 + club * 14), yaw, side * 0.18)
            data.part.Transparency = 0.90
            data.light.Brightness = 0.25 + club * 4.8
            data.light.Range = 18 + club * 12
        end

        clubMist.Rate = 6 + math.floor(club * 24)

        if club > 0.72 and t - lastBurst > 0.12 then
            lastBurst = t
            burstEmitter(clubBurst, 7 + math.floor(club * 14))
            burstEmitter(spark, 4 + math.floor(club * 5))
        end
    end
end
function startSheBuggingFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)
    local char = hrp.Parent

    local rigPalettes = {
        {Color3.fromRGB(255, 92, 40), Color3.fromRGB(255, 196, 54), Color3.fromRGB(255, 238, 148)},
        {Color3.fromRGB(142, 76, 255), Color3.fromRGB(55, 232, 214), Color3.fromRGB(224, 154, 255)},
    }

    local disks = {
        addPulsingDisk(folder, c[1], 3.2, 0.10, 0.07, 0.18),
        addPulsingDisk(folder, c[2], 4.0, 0.08, 0.10, 0.30),
        addPulsingDisk(folder, c[3], 4.8, 0.06, 0.13, 0.40),
    }

    local orbs = {}
    for i = 1, 8 do
        orbs[i] = addFloatingOrb(folder, c[(i - 1) % 3 + 1], 0.22 + (i % 2) * 0.08, Vector3.new())
    end

    local trails = {}
    for _, name in ipairs({
        "LeftHand", "RightHand", "Left Arm", "Right Arm",
        "LeftFoot", "RightFoot", "Left Leg", "Right Leg"
    }) do
        local limb = char and char:FindFirstChild(name)
        if limb and #trails < 8 then
            trails[#trails + 1] = addLimbTrail(folder, limb, c, 1.10, 0.90, 0.34)
        end
    end

    local burst = addEmitter(core, {
        Texture = "rbxassetid://243660364", Rate = 0, Speed = NumberRange.new(3, 10),
        Lifetime = NumberRange.new(0.34, 0.82), SpreadAngle = Vector2.new(360,360),
        LightEmission = 1, LightInfluence = 0, Color = seqColor(c[1], c[3]),
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0,0.10),
            NumberSequenceKeypoint.new(0.30,0.72),
            NumberSequenceKeypoint.new(0.72,0.34),
            NumberSequenceKeypoint.new(1,0)
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0,0.04),
            NumberSequenceKeypoint.new(0.65,0.20),
            NumberSequenceKeypoint.new(1,1)
        }),
    })

    local friendRigs = {}
    local friendTracks = {}
    local friendTargets = {}
    local friendGroundOffsets = {}
    local friendFadeData = {}
    local friendNames = {}
    local friendsReady = false

    local function captureFadeData(model)
        local data = {}
        for _, obj in ipairs(model:GetDescendants()) do
            if obj:IsA("BasePart") then
                data[obj] = obj.Transparency
                obj.Transparency = 1
            elseif obj:IsA("Decal") or obj:IsA("Texture") then
                data[obj] = obj.Transparency
                obj.Transparency = 1
            end
        end
        return data
    end

    local function fadeRig(data, fadeIn, duration)
        for obj, original in pairs(data or {}) do
            if obj and obj.Parent then
                local goal = fadeIn and original or 1
                TweenService:Create(
                    obj,
                    TweenInfo.new(duration, Enum.EasingStyle.Quad, fadeIn and Enum.EasingDirection.Out or Enum.EasingDirection.In),
                    {Transparency = goal}
                ):Play()
            end
        end
    end

    local function styleFriendRig(model, palette)
        if not model then return end
        for _, obj in ipairs(model:GetDescendants()) do
            if obj:IsA("BasePart") then
                obj.CanCollide = false
                obj.CanTouch = false
                obj.CanQuery = false
                obj.CastShadow = false
            elseif obj:IsA("Humanoid") then
                obj.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                obj.AutoRotate = false
                obj.WalkSpeed = 0
                obj.JumpPower = 0
                pcall(function() obj.JumpHeight = 0 end)
                pcall(function() obj:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end)
                pcall(function() obj:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false) end)
            end
        end
    end

    local function getGroundY()
        local floor = getFloorCFrame(hrp, 0.03)
        return floor.Position.Y
    end

    local function getGroundedPivotOffset(model, desiredCF, groundY)
        if not model then return desiredCF, 0 end
        model:PivotTo(desiredCF)
        local boxCF, boxSize = model:GetBoundingBox()
        local currentBottomY = boxCF.Position.Y - (boxSize.Y * 0.5)
        local deltaY = (groundY + 0.035) - currentBottomY
        return desiredCF * CFrame.new(0, deltaY, 0), deltaY
    end

    local function loadFriendDance(model)
        local hum = model and model:FindFirstChildOfClass("Humanoid")
        if not hum then return nil end
        local anim, obfuscatedName = CreateLoggerBlendedAnimation(e.AnimationId, e.Name)
        local tr
        local ok = pcall(function()
            tr = hum:LoadAnimation(anim)
        end)
        anim:Destroy()
        if not ok or not tr then return nil end
        pcall(function() tr.Name = obfuscatedName end)
        tr.Priority = Enum.AnimationPriority.Action
        tr.Looped = true

        local speed = e.AnimationSpeed or 0.59
        local segmentStart = tonumber(e.AnimationSegmentStart)
        local segmentEnd = tonumber(e.AnimationSegmentEnd)
        local hasSegment = segmentStart ~= nil and segmentEnd ~= nil and segmentEnd > segmentStart

        if hasSegment then
            pcall(function() tr.TimePosition = segmentStart end)
        end
        pcall(function() tr:Play(0, 1, speed) end)

        return tr
    end

    local function pickFriends()
        local ok, pages = pcall(function()
            return Players:GetFriendsAsync(LocalPlayer.UserId)
        end)
        if not ok or not pages then return {} end

        local all = {}
        local function consumePage(pg)
            for _, item in ipairs(pg:GetCurrentPage()) do
                if item and item.Id and item.Id ~= LocalPlayer.UserId then
                    all[#all + 1] = item
                end
            end
        end
        consumePage(pages)
        while not pages.IsFinished and #all < 60 do
            local nextOk = pcall(function() pages:AdvanceToNextPageAsync() end)
            if not nextOk then break end
            consumePage(pages)
        end
        return all
    end

    local friends = BugginRigsEnabled and pickFriends() or {}
    if BugginRigsEnabled and #friends > 0 then
        math.randomseed(math.floor(os.clock() * 1000000) % 2147483647)
        for i = #friends, 2, -1 do
            local j = math.random(1, i)
            friends[i], friends[j] = friends[j], friends[i]
        end

        local wanted = math.min(2, #friends)
        local baseGroundY = getGroundY()
        for i = 1, wanted do
            local friend = friends[i]
            local ok, rig = pcall(function()
                local desc = Players:GetHumanoidDescriptionFromUserIdAsync(friend.Id)
                return Players:CreateHumanoidModelFromDescriptionAsync(desc, Enum.HumanoidRigType.R6)
            end)
            if ok and rig and rig:IsA("Model") then
                rig.Name = "BugginFriend_" .. tostring(friend.Id)
                styleFriendRig(rig)
                rig.Parent = folder
                local rigRoot = rig:FindFirstChild("HumanoidRootPart")
                if rigRoot then
                    local glow = addEmitter(rigRoot, {Texture="rbxassetid://243660364", Rate=18, Speed=NumberRange.new(1,4), Lifetime=NumberRange.new(0.45,0.9), SpreadAngle=Vector2.new(360,360), LightEmission=1, LightInfluence=0, Color=seqColor(rigPalettes[i][1], rigPalettes[i][3]), Size=NumberSequence.new(0.18,0.75), Transparency=NumberSequence.new(0.2,1)})
                    glow.Name = "BugginPartnerAura"
                    local pl = Instance.new("PointLight"); pl.Color=rigPalettes[i][1]; pl.Brightness=1.5; pl.Range=10; pl.Parent=rigRoot
                end
                for _, limbName in ipairs({"Left Arm","Right Arm","Left Leg","Right Leg"}) do
                    local limb = rig:FindFirstChild(limbName)
                    if limb then addLimbTrail(folder, limb, rigPalettes[i], 0.9, 0.72, 0.22) end
                end
                local root = rig:FindFirstChild("HumanoidRootPart") or rig.PrimaryPart
                local hum = rig:FindFirstChildOfClass("Humanoid")
                if root and hum then
                    root.Anchored = true
                    local sideX = i == 1 and -4.2 or 4.2
                    local spawnCF = hrp.CFrame * CFrame.new(sideX, 0, 0)
                    local corrected, groundOffsetY = getGroundedPivotOffset(rig, spawnCF, baseGroundY)
                    rig:PivotTo(corrected)
                    friendGroundOffsets[#friendGroundOffsets + 1] = groundOffsetY

                    local fadeData = captureFadeData(rig)
                    friendFadeData[#friendFadeData + 1] = fadeData
                    local track = loadFriendDance(rig)

                    if track and token.directTrack then
                        pcall(function()
                            track.TimePosition = token.directTrack.TimePosition
                        end)
                    end

                    friendRigs[#friendRigs + 1] = rig
                    friendTracks[#friendTracks + 1] = track
                    friendTargets[#friendTargets + 1] = sideX
                    friendNames[#friendNames + 1] = friend.DisplayName or friend.Username or ("Friend " .. i)
                    if track then table.insert(token.tracks, track) end

                    fadeRig(fadeData, true, 0.42)
                else
                    pcall(function() rig:Destroy() end)
                end
            end
        end
        friendsReady = #friendRigs > 0
    token.bugginFriendFadeData = friendFadeData
    end
    token.customFxFadeOut = function(duration)
        for _, data in ipairs(friendFadeData) do
            fadeRig(data, false, duration or 0.24)
        end
    end

    local lastBeat = 0
    local lastT = os.clock()
    local function smoothAlpha(now)
        local dt = math.clamp(now - lastT, 0.001, 0.10)
        lastT = now
        return 1 - math.exp(-9.0 * dt)
    end

    return function(t, pulse)
        local floorCF = getFloorCFrame(hrp, 0.06)
        local torsoCF = getTorsoCFrame(hrp)
        local alpha = smoothAlpha(t)

        core.CFrame = torsoCF
        light.Color = c[1 + (math.floor(t * 2.2) % 3)]
        light.Brightness = 0.35 + pulse * 4.6
        light.Range = 9 + pulse * 13

        for i,d in ipairs(disks) do
            updatePulsingDisk(d, floorCF, t + i * 0.23, pulse, 1.7 + i * 0.45, 0.85 + i * 0.28)
        end

        for i,o in ipairs(orbs) do
            local a = t * (1.55 + i * 0.10) + i * math.pi * 2 / #orbs
            local r = 2.0 + pulse * 1.55 + (i % 2) * 0.42
            local y = 0.3 + math.sin(t * 2.4 + i) * 0.9
            o.CFrame = torsoCF * CFrame.new(math.cos(a) * r, y, math.sin(a) * r)
            local z = (o:GetAttribute("BaseSize") or 0.25) * (0.78 + pulse * 1.45)
            o.Size = Vector3.new(z,z,z)
            o.Transparency = math.clamp(0.26 - pulse * 0.18, 0.035, 0.30)
        end

        for _, tr in ipairs(trails) do
            if tr and tr.Parent then
                tr.Lifetime = 0.92 + pulse * 0.34
                tr.WidthScale = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.90),
                    NumberSequenceKeypoint.new(0.52, 0.36 + pulse * 0.08),
                    NumberSequenceKeypoint.new(1, 0),
                })
            end
        end

        local masterTrack = token.directTrack
        local groundY = getGroundY()
        for i, rig in ipairs(friendRigs) do
            if rig and rig.Parent then
                local sideX = friendTargets[i] or (i == 1 and -4.2 or 4.2)
                local sway = math.sin(t * 3.2 + i * 1.7) * 0.35
                local forward = 0.25 + math.sin(t * 2.1 + i) * 0.16
                local groundOffsetY = friendGroundOffsets[i] or 0
                local target = hrp.CFrame * CFrame.new(sideX, groundOffsetY, forward + sway * 0.05)
                local current = rig:GetPivot()
                local nextCF = current:Lerp(target, alpha)
                rig:PivotTo(nextCF)

                local tr = friendTracks[i]
                if tr and masterTrack then
                    pcall(function()
                        if not tr.IsPlaying then
                            tr:Play(0, 1, e.AnimationSpeed or 0.59)
                        end

                        tr.TimePosition = masterTrack.TimePosition
                        tr:AdjustSpeed(masterTrack.Speed)
                    end)
                end
            end
        end

        spark.Rate = 7 + math.floor(pulse * 34)
        if pulse > 0.72 and t - lastBeat > 0.13 then
            lastBeat = t
            burstEmitter(burst, 10 + math.floor(pulse * 18))
            burstEmitter(spark, 6 + math.floor(pulse * 12))
        end
    end
end

function startJamalFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)
    local gold = Color3.fromRGB(255, 214, 72)
    local pink = Color3.fromRGB(255, 72, 166)
    local cyan = Color3.fromRGB(48, 235, 255)
    local green = Color3.fromRGB(67, 255, 145)
    local white = Color3.fromRGB(255, 255, 255)
    local palette = {gold, pink, cyan, green}

    local highlight = Instance.new("Highlight")
    highlight.Name = "JamalHighlight"
    highlight.Adornee = hrp.Parent
    highlight.FillColor = gold
    highlight.OutlineColor = white
    highlight.FillTransparency = 0.78
    highlight.OutlineTransparency = 0.05
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Parent = folder

    local rings = {}
    for i = 1, 4 do
        local ring = addFxPart(folder, Vector3.new(0.16, 4, 4), palette[i], 0.10)
        ring.Shape = Enum.PartType.Cylinder
        ring.Material = Enum.Material.Neon
        rings[i] = ring
    end

    local orbiters = {}
    for i = 1, 10 do
        orbiters[i] = addFloatingOrb(folder, palette[(i - 1) % #palette + 1], 0.24 + (i % 3) * 0.055, Vector3.zero)
    end

    local streaks = {}
    for i = 1, 4 do
        streaks[i] = addFxPart(folder, Vector3.new(0.10, 0.10, 3.2), palette[i], 0.16)
    end

    local char = hrp.Parent
    local trailIndex = 0
    for _, limbName in ipairs({"Left Arm", "Right Arm", "Left Leg", "Right Leg"}) do
        local limb = char and char:FindFirstChild(limbName)
        if limb then
            trailIndex += 1
            addLimbTrail(folder, limb, {
                palette[(trailIndex - 1) % #palette + 1],
                palette[trailIndex % #palette + 1]
            }, 0.34, 1.0, 0.52)
        end
    end

    local confetti = addEmitter(core, {
        Texture = "rbxassetid://243660364",
        Rate = 8,
        Speed = NumberRange.new(2, 6),
        Lifetime = NumberRange.new(0.7, 1.35),
        Rotation = NumberRange.new(0, 360),
        RotSpeed = NumberRange.new(-360, 360),
        SpreadAngle = Vector2.new(180, 180),
        Acceleration = Vector3.new(0, -7, 0),
        Drag = 1.25,
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.12),
            NumberSequenceKeypoint.new(0.2, 0.30),
            NumberSequenceKeypoint.new(0.75, 0.18),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.02),
            NumberSequenceKeypoint.new(0.72, 0.22),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, gold),
            ColorSequenceKeypoint.new(0.25, pink),
            ColorSequenceKeypoint.new(0.50, cyan),
            ColorSequenceKeypoint.new(0.75, green),
            ColorSequenceKeypoint.new(1, white),
        }),
    })

    local burst = addEmitter(core, {
        Texture = "rbxassetid://6893912008",
        Rate = 0,
        Speed = NumberRange.new(7, 13),
        Lifetime = NumberRange.new(0.20, 0.55),
        Rotation = NumberRange.new(-180, 180),
        RotSpeed = NumberRange.new(-420, 420),
        SpreadAngle = Vector2.new(360, 360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.10),
            NumberSequenceKeypoint.new(0.28, 0.62),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.04),
            NumberSequenceKeypoint.new(0.65, 0.20),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Color = ColorSequence.new(gold, white),
    })

    local wave = addFxPart(folder, Vector3.new(0.14, 3.0, 3.0), cyan, 0.22)
    wave.Shape = Enum.PartType.Cylinder
    wave.Material = Enum.Material.Neon

    local pulseRing = addFxPart(folder, Vector3.new(0.20, 2.5, 2.5), pink, 0.28)
    pulseRing.Shape = Enum.PartType.Cylinder
    pulseRing.Material = Enum.Material.Neon

    local lastBurst = -math.huge
    local t0 = os.clock()

    return function(t, pulse)
        if not hrp.Parent or not folder.Parent then return end
        local torsoCF = getTorsoCFrame(hrp)
        local floorCF = getFloorCFrame(hrp, 0.075)
        local age = math.max(0, os.clock() - t0)
        local strong = math.clamp(pulse * 1.3 + 0.15, 0, 1)

        core.CFrame = torsoCF
        light.Color = palette[(math.floor(t * 8) % #palette) + 1]
        light.Brightness = 2.5 + strong * 9
        light.Range = 12 + strong * 12

        highlight.FillColor = palette[(math.floor(t * 5) % #palette) + 1]
        highlight.FillTransparency = 0.74 - strong * 0.20
        highlight.OutlineTransparency = 0.02 + (1 - strong) * 0.10

        for i, ring in ipairs(rings) do
            local phase = t * (2.0 + i * 0.18) + i * 0.8
            local wave01 = (math.sin(phase) + 1) * 0.5
            local radius = 2.0 + i * 0.72 + wave01 * 0.55 + strong * 1.0
            ring.CFrame = floorCF * CFrame.Angles(0, t * (i % 2 == 0 and -1.7 or 1.7) + i, math.rad(90))
            ring.Size = Vector3.new(0.12 + strong * 0.07, radius * 2, radius * 2)
            ring.Transparency = math.clamp(0.23 - strong * 0.12, 0.035, 0.35)
        end

        for i, orb in ipairs(orbiters) do
            local phase = t * (1.7 + i * 0.08) + i * 0.64
            local radius = 2.35 + strong * 0.75 + math.sin(t * 4 + i) * 0.12
            local y = 0.30 + math.sin(phase * 1.6 + age) * (0.95 + strong * 0.30)
            orb.CFrame = torsoCF * CFrame.new(math.cos(phase) * radius, y, math.sin(phase) * radius)
            local size = 0.20 + strong * 0.16 + (i % 2) * 0.035
            orb.Size = Vector3.new(size, size, size)
        end

        for i, streak in ipairs(streaks) do
            local phase = t * (2.1 + i * 0.13) + i * 1.2
            local radius = 2.0 + strong * 0.9
            streak.CFrame = torsoCF
                * CFrame.new(math.cos(phase) * radius, 0.15 + math.sin(phase * 1.7) * 1.35, math.sin(phase) * radius)
                * CFrame.Angles(phase, phase * 0.8, t * 2)
            local len = 2.8 + strong * 2.3
            streak.Size = Vector3.new(0.08 + strong * 0.05, 0.08 + strong * 0.05, len)
            streak.Transparency = 0.10 + (1 - strong) * 0.22
        end

        local ringRadius = 2.7 + strong * 4.6 + ((math.sin(t * 5.8) + 1) * 0.5) * 0.55
        wave.CFrame = floorCF * CFrame.Angles(0, t * 1.8, math.rad(90))
        wave.Size = Vector3.new(0.13 + strong * 0.07, ringRadius * 2, ringRadius * 2)
        wave.Transparency = math.clamp(0.45 - strong * 0.28, 0.08, 0.48)

        local pRadius = 2.2 + ((math.sin(t * 8) + 1) * 0.5) * 1.8 + strong * 0.8
        pulseRing.CFrame = floorCF * CFrame.Angles(0, -t * 2.3, math.rad(90))
        pulseRing.Size = Vector3.new(0.10 + strong * 0.08, pRadius * 2, pRadius * 2)
        pulseRing.Transparency = math.clamp(0.60 - strong * 0.30, 0.16, 0.65)

        confetti.Rate = 10 + math.floor(strong * 28)
        if strong > 0.52 and t - lastBurst > 0.12 then
            lastBurst = t
            burstEmitter(burst, 10 + math.floor(strong * 18))
            burstEmitter(spark, 5 + math.floor(strong * 7))
        end
    end
end

function startWhoIsYouFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)

