    local lastBurst = -math.huge
    return function(t, pulse)
        if not hrp.Parent or not folder.Parent then return end
        local torsoCF = getTorsoCFrame(hrp)
        local floorCF = getFloorCFrame(hrp, 0.045)
        local strong = math.clamp(pulse * 1.25 + 0.12, 0, 1)

        core.CFrame = torsoCF
        light.Color = c[(math.floor(t * 7) % 3) + 1]
        light.Brightness = 0.8 + strong * 5.5
        light.Range = 10 + strong * 10

        for i, ring in ipairs(rings) do
            updatePulsingDisk(
                ring,
                floorCF,
                t * (i % 2 == 0 and -2.3 or 2.3) + i * 0.55,
                strong,
                1.35 + i * 0.28,
                1.8 + i * 0.48
            )
        end

        for i, orb in ipairs(orbs) do
            local a = t * (2.4 + (i % 4) * 0.18) + i * 0.52
            local radius = 2.15 + strong * 1.0 + (i % 3) * 0.18
            local y = 0.25 + math.sin(t * 3.2 + i * 0.7) * (0.8 + strong * 0.32)
            orb.CFrame = torsoCF * CFrame.new(math.cos(a) * radius, y, math.sin(a) * radius)
            local s = 0.11 + strong * 0.15 + (i % 2) * 0.025
            orb.Size = Vector3.new(s, s, s)
        end

        if strong > 0.72 and t - lastBurst > 0.10 then
            lastBurst = t
            burstEmitter(burst, 5 + math.floor(strong * 12))
            burstEmitter(spark, 2 + math.floor(strong * 5))
        end
    end
end

local function isBouncinFaceAccessoryPart(obj)
    if not obj or not obj:IsA("BasePart") then return false end

    local accessory = obj:FindFirstAncestorOfClass("Accessory")
    if not accessory then return false end

    local isFace = false
    pcall(function()
        isFace = accessory.AccessoryType == Enum.AccessoryType.Face
    end)
    if isFace then return true end

    for _, child in ipairs(accessory:GetDescendants()) do
        if child:IsA("Attachment") then
            local n = child.Name
            if n == "FaceFrontAttachment" or n == "FaceCenterAttachment" or n == "FaceBackAttachment"
                or n:find("Face", 1, true) then
                return true
            end
        end
    end

    return false
end

local function applyBouncinSketchStyle(token, character, folder)
    if not token or not character or not folder then return end
    if token.bouncinEffectHidden or HideEffectsEnabled then return end

    local saved = {}
    local outlineHighlights = {}
    local restored = false

    local pureWhite = Color3.fromRGB(255, 255, 255)
    local inkBlack = Color3.fromRGB(0, 0, 0)

    local function saveAndSet(obj, state)
        saved[obj] = state
    end

    for _, obj in ipairs(character:GetDescendants()) do
        if obj:IsA("BasePart") and obj.Name ~= "HumanoidRootPart" then
            local oldTextureId = nil
            if obj:IsA("MeshPart") then
                oldTextureId = obj.TextureID
            end

            saveAndSet(obj, {
                Kind = "BasePart",
                Color = obj.Color,
                Material = obj.Material,
                Reflectance = obj.Reflectance,
                Transparency = obj.Transparency,
                TextureID = oldTextureId,
            })

            obj.Color = pureWhite
            obj.Material = Enum.Material.SmoothPlastic
            obj.Reflectance = 0

            if obj:IsA("MeshPart") then
                pcall(function()
                    obj.TextureID = ""
                end)
            end

            if not isBouncinFaceAccessoryPart(obj) then
                local h = Instance.new("Highlight")
                h.Name = "BouncinInkOutline"
                h.Adornee = obj
                h.FillColor = pureWhite
                h.FillTransparency = 0.02
                h.OutlineColor = inkBlack
                h.OutlineTransparency = 0
                h.DepthMode = Enum.HighlightDepthMode.Occluded
                h.Parent = folder
                outlineHighlights[#outlineHighlights + 1] = h
            end

        elseif obj:IsA("BodyColors") then
            saveAndSet(obj, {
                Kind = "BodyColors",
                HeadColor3 = obj.HeadColor3,
                LeftArmColor3 = obj.LeftArmColor3,
                RightArmColor3 = obj.RightArmColor3,
                LeftLegColor3 = obj.LeftLegColor3,
                RightLegColor3 = obj.RightLegColor3,
                TorsoColor3 = obj.TorsoColor3,
            })

        elseif obj:IsA("SpecialMesh") then
            saveAndSet(obj, {
                Kind = "SpecialMesh",
                TextureId = obj.TextureId,
            })
            pcall(function()
                obj.TextureId = ""
            end)

        elseif obj:IsA("Shirt") or obj:IsA("Pants") or obj:IsA("ShirtGraphic")
            or obj:IsA("SurfaceAppearance") or obj:IsA("Decal") or obj:IsA("Texture") then
            saveAndSet(obj, {
                Kind = "ParentedObject",
                Parent = obj.Parent,
            })
            obj.Parent = folder
        end
    end

    local function restoreAppearance()
        if restored and next(saved) == nil then return end
        restored = true

        for obj, state in pairs(saved) do
            if obj then
                pcall(function()
                    if state.Kind == "BasePart" then
                        obj.Color = state.Color
                        obj.Material = state.Material
                        obj.Reflectance = state.Reflectance
                        obj.Transparency = state.Transparency
                        if obj:IsA("MeshPart") and state.TextureID ~= nil then
                            obj.TextureID = state.TextureID
                        end
                    elseif state.Kind == "BodyColors" then
                        obj.HeadColor3 = state.HeadColor3
                        obj.LeftArmColor3 = state.LeftArmColor3
                        obj.RightArmColor3 = state.RightArmColor3
                        obj.LeftLegColor3 = state.LeftLegColor3
                        obj.RightLegColor3 = state.RightLegColor3
                        obj.TorsoColor3 = state.TorsoColor3
                    elseif state.Kind == "SpecialMesh" then
                        obj.TextureId = state.TextureId
                    elseif state.Kind == "ParentedObject" then
                        if state.Parent and state.Parent.Parent then
                            obj.Parent = state.Parent
                        end
                    end
                end)
            end
        end

        for _, h in ipairs(outlineHighlights) do
            pcall(function() h:Destroy() end)
        end
        outlineHighlights = {}
    end

    local function setEffectObjectsHidden(hidden)
        for _, obj in ipairs(folder:GetDescendants()) do
            pcall(function()
                if obj:IsA("BasePart") then
                    if hidden then
                        obj.LocalTransparencyModifier = 1
                    else
                        obj.LocalTransparencyModifier = 0
                    end
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
                    or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles")
                    or obj:IsA("Highlight") then
                    obj.Enabled = not hidden
                elseif obj:IsA("BillboardGui") or obj:IsA("SurfaceGui") then
                    obj.Enabled = not hidden
                end
            end)
        end
    end

    token.bouncinSetHidden = function(hidden)
        if not token or not folder or not folder.Parent then return end
        token.bouncinEffectHidden = hidden == true
        if token.bouncinEffectHidden then
            restoreAppearance()
        else
            restored = false
            saved = {}
            applyBouncinSketchStyle(token, character, folder)
        end
        setEffectObjectsHidden(token.bouncinEffectHidden)
    end

    token.bouncinSketchRestore = function()
        if not token or not character or not character.Parent then
            restoreAppearance()
            saved = {}
            token.bouncinSketchRestore = nil
            return
        end

        restoreAppearance()

        task.defer(function()
            if character and character.Parent then
                for obj, state in pairs(saved) do
                    if obj and obj.Parent then
                        pcall(function()
                            if state.Kind == "BasePart" then
                                obj.Color = state.Color
                                obj.Material = state.Material
                                obj.Reflectance = state.Reflectance
                                obj.Transparency = state.Transparency
                                if obj:IsA("MeshPart") and state.TextureID ~= nil then
                                    obj.TextureID = state.TextureID
                                end
                            elseif state.Kind == "BodyColors" then
                                obj.HeadColor3 = state.HeadColor3
                                obj.LeftArmColor3 = state.LeftArmColor3
                                obj.RightArmColor3 = state.RightArmColor3
                                obj.LeftLegColor3 = state.LeftLegColor3
                                obj.RightLegColor3 = state.RightLegColor3
                                obj.TorsoColor3 = state.TorsoColor3
                            elseif state.Kind == "SpecialMesh" then
                                obj.TextureId = state.TextureId
                            elseif state.Kind == "ParentedObject" and state.Parent and state.Parent.Parent then
                                obj.Parent = state.Parent
                            end
                        end)
                    end
                end
            end
        end)

        task.delay(0.08, function()
            if character and character.Parent then
                for obj, state in pairs(saved) do
                    if obj and obj.Parent then
                        pcall(function()
                            if state.Kind == "BasePart" then
                                obj.Color = state.Color
                                obj.Material = state.Material
                                obj.Reflectance = state.Reflectance
                                obj.Transparency = state.Transparency
                                if obj:IsA("MeshPart") and state.TextureID ~= nil then
                                    obj.TextureID = state.TextureID
                                end
                            elseif state.Kind == "BodyColors" then
                                obj.HeadColor3 = state.HeadColor3
                                obj.LeftArmColor3 = state.LeftArmColor3
                                obj.RightArmColor3 = state.RightArmColor3
                                obj.LeftLegColor3 = state.LeftLegColor3
                                obj.RightLegColor3 = state.RightLegColor3
                                obj.TorsoColor3 = state.TorsoColor3
                            elseif state.Kind == "SpecialMesh" then
                                obj.TextureId = state.TextureId
                            elseif state.Kind == "ParentedObject" and state.Parent and state.Parent.Parent then
                                obj.Parent = state.Parent
                            end
                        end)
                    end
                end
            end

            saved = {}
            token.bouncinSketchRestore = nil
            token.bouncinSetHidden = nil
        end)
    end
end

function startBounceFx(token, e, hrp)
    local folder, core, light, spark = setupBaseFx(token, e, hrp)
    local character = hrp and hrp.Parent
    token.bouncinEffectHidden = HideEffectsEnabled == true
    if not token.bouncinEffectHidden then
        applyBouncinSketchStyle(token, character, folder)
    end

    local white = Color3.fromRGB(255, 255, 255)
    local softWhite = Color3.fromRGB(235, 235, 235)
    local paleGray = Color3.fromRGB(205, 205, 205)

    pcall(function()
        light.Brightness = 0
        light.Range = 0
        light.Color = white
        spark.Color = ColorSequence.new(white)
        spark.LightEmission = 0.25
        spark.LightInfluence = 1
        spark.Rate = 0
        spark.Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.05),
            NumberSequenceKeypoint.new(0.35, 0.18),
            NumberSequenceKeypoint.new(1, 0),
        })
        spark.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.2),
            NumberSequenceKeypoint.new(0.55, 0.5),
            NumberSequenceKeypoint.new(1, 1),
        })
    end)

    local ring1 = addFxPart(folder, Vector3.new(0.07, 2.2, 2.2), white, 0.55)
    ring1.Shape = Enum.PartType.Cylinder
    ring1.Material = Enum.Material.SmoothPlastic

    local ring2 = addFxPart(folder, Vector3.new(0.055, 3.4, 3.4), softWhite, 0.72)
    ring2.Shape = Enum.PartType.Cylinder
    ring2.Material = Enum.Material.SmoothPlastic

    local ring3 = addFxPart(folder, Vector3.new(0.04, 4.7, 4.7), paleGray, 0.84)
    ring3.Shape = Enum.PartType.Cylinder
    ring3.Material = Enum.Material.SmoothPlastic

    local impact = addFxPart(folder, Vector3.new(0.06, 2.6, 2.6), white, 0.68)
    impact.Shape = Enum.PartType.Cylinder
    impact.Material = Enum.Material.SmoothPlastic

    local puffs = {}
    for i = 1, 8 do
        local puff = Instance.new("Part")
        puff.Name = "BouncePuff"
        puff.Shape = Enum.PartType.Ball
        puff.Size = Vector3.new(0.18, 0.18, 0.18)
        puff.Color = white
        puff.Material = Enum.Material.SmoothPlastic
        puff.Transparency = 0.55
        puff.Anchored = true
        puff.CanCollide = false
        puff.CanTouch = false
        puff.CanQuery = false
        puff.CastShadow = false
        puff.Parent = folder
        puffs[i] = puff
    end

    local labelGui = Instance.new("BillboardGui")
    labelGui.Name = "BouncinSketchWord"
    labelGui.Adornee = core
    labelGui.AlwaysOnTop = false
    labelGui.Size = UDim2.fromOffset(220, 62)
    labelGui.StudsOffset = Vector3.new(0, 3.45, 0)
    labelGui.MaxDistance = 90
    labelGui.Parent = folder

    local label = Instance.new("TextLabel")
    label.Name = "Word"
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = Enum.Font.Gotham
    label.Text = "BOUNCE!"
    label.TextScaled = false
    label.TextSize = 28
    label.TextWrapped = false
    label.TextColor3 = white
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0.16
    label.TextTransparency = 0.12
    label.Rotation = -4
    local labelScale = Instance.new("UIScale")
    labelScale.Name = "BeatPulseScale"
    labelScale.Scale = 1
    labelScale.Parent = label
    label.Parent = labelGui

    local lastPulse = -math.huge
    local lastPop = -math.huge
    local originPhase = math.random() * math.pi * 2

    return function(t, pulse)
        if not hrp.Parent or not folder.Parent then return end

        local torsoCF = getTorsoCFrame(hrp)
        local floorCF = getFloorCFrame(hrp, 0.035)

        local dance = (math.sin(t * 7.5 + originPhase) + 1) * 0.5
        local bounce = math.max(0, math.sin(t * 3.75 + originPhase))
        local strong = math.clamp(pulse * 1.55 + bounce * 0.28, 0, 1)

        core.CFrame = torsoCF

        for _, h in ipairs(folder:GetChildren()) do
            if h:IsA("Highlight") and h.Name == "BouncinInkOutline" then
                h.FillColor = white
                h.OutlineColor = Color3.fromRGB(0, 0, 0)
                h.FillTransparency = 0.02 + (1 - strong) * 0.025
                h.OutlineTransparency = 0.02 + (1 - strong) * 0.035
                h.DepthMode = Enum.HighlightDepthMode.Occluded
            end
        end

        local radius1 = 2.05 + dance * 0.45 + strong * 1.05
        local radius2 = radius1 + 0.48 + strong * 0.35
        local radius3 = radius2 + 0.65 + strong * 0.40

        ring1.CFrame = floorCF * CFrame.Angles(0, 0, math.rad(90))
        ring1.Size = Vector3.new(0.06, radius1 * 2, radius1 * 2)
        ring1.Transparency = math.clamp(0.34 - strong * 0.20, 0.10, 0.38)

        ring2.CFrame = floorCF * CFrame.Angles(0, 0, math.rad(90))
        ring2.Size = Vector3.new(0.05, radius2 * 2, radius2 * 2)
        ring2.Transparency = math.clamp(0.56 - strong * 0.24, 0.20, 0.62)

        ring3.CFrame = floorCF * CFrame.Angles(0, 0, math.rad(90))
        ring3.Size = Vector3.new(0.035, radius3 * 2, radius3 * 2)
        ring3.Transparency = math.clamp(0.70 - strong * 0.20, 0.38, 0.74)

        impact.CFrame = floorCF * CFrame.new(0, 0.012, 0) * CFrame.Angles(0, 0, math.rad(90))
        impact.Size = Vector3.new(
            0.045,
            2.0 + dance * 0.65 + strong * 1.35,
            2.0 + dance * 0.65 + strong * 1.35
        )
        impact.Transparency = math.clamp(0.74 - strong * 0.44, 0.18, 0.78)

        for i, puff in ipairs(puffs) do
            local a = ((i - 1) / #puffs) * math.pi * 2
            local pulseWave = (math.sin(t * 4.0 + i * 0.6 + originPhase) + 1) * 0.5
            local r = 1.75 + strong * (1.3 + pulseWave * 0.85)
            local y = 0.08 + pulseWave * 0.18 + bounce * 0.08
            local s = 0.12 + pulseWave * 0.09 + strong * 0.07

            puff.CFrame = floorCF * CFrame.new(
                math.cos(a) * r,
                y,
                math.sin(a) * r
            )
            puff.Size = Vector3.new(s, s, s)
            puff.Transparency = math.clamp(
                0.64 - strong * 0.26 + pulseWave * 0.10,
                0.28,
                0.78
            )
        end

        if labelGui and labelGui.Parent then
            local beatBounce = math.clamp(pulse * 1.35, 0, 1)
            local beatPulse = math.clamp(pulse * 1.15, 0, 1)

            labelGui.StudsOffset = Vector3.new(
                0,
                3.38 + bounce * 0.28 + beatBounce * 0.72 + math.sin(t * 5.2) * 0.04,
                0
            )

            labelScale.Scale = 1 + beatPulse * 0.12
            label.Rotation = -4 + math.sin(t * 4.0) * 1.5 + beatBounce * 2.5
            label.TextTransparency = math.clamp(0.26 - strong * 0.20 - beatPulse * 0.08, 0.02, 0.30)
            label.TextStrokeTransparency = math.clamp(0.18 - strong * 0.08 - beatPulse * 0.08, 0.03, 0.20)
        end

        pcall(function()
            light.Brightness = 0
            light.Range = 0

            local emitRate = math.floor(strong * 12)
            spark.Rate = emitRate

            if strong > 0.72 and t - lastPulse > 0.14 then
                lastPulse = t
                burstEmitter(spark, 3 + math.floor(strong * 4))
            end

            if bounce > 0.86 and t - lastPop > 0.20 then
                lastPop = t
                burstEmitter(spark, 5 + math.floor(strong * 3))
            end
        end)
    end
end

function startDanceAloneFx(token, e, hrp)
    local folder, core, light, spark, c = setupBaseFx(token, e, hrp)
    local white = Color3.fromRGB(255,255,255)
    local cyan = Color3.fromRGB(70,235,255)
    local violet = Color3.fromRGB(170,105,255)
    local pink = Color3.fromRGB(255,85,190)

    local bloom = AddClientPostEffect(token, "BloomEffect", "DanceAloneBloom")
    bloom.Intensity = 0.08
    bloom.Size = 16
    bloom.Threshold = 0.88

    local grade = AddClientPostEffect(token, "ColorCorrectionEffect", "DanceAloneGrade")
    grade.Contrast = 0.10
    grade.Saturation = 0.18
    grade.TintColor = Color3.fromRGB(224,235,255)

    local spotlightTarget = addFxPart(folder, Vector3.new(0.1, 0.1, 0.1), white, 1)
    spotlightTarget.Name = "DanceAloneSpotlightTarget"
    local targetAttachment = Instance.new("Attachment")
    targetAttachment.Name = "SpotlightTargetAttachment"
    targetAttachment.Parent = spotlightTarget

    local spotlights = {}
    local spots = {
        {-9.0, 11.5, 6.0, cyan, 22, 8.5},
        {-3.5, 14.0, 8.0, white, 20, 9.5},
        {0.0, 16.0, 10.5, white, 18, 11},
        {3.5, 14.0, 8.0, pink, 20, 9.5},
        {9.0, 11.5, 6.0, violet, 22, 8.5},
    }

    for i, data in ipairs(spots) do
        local rig = addFxPart(folder, Vector3.new(0.08, 0.08, 0.08), data[4], 1)
        rig.Name = "DanceAloneConcertHeadlight" .. i
        local lightAttachment = Instance.new("Attachment")
        lightAttachment.Name = "ConcertLightAttachment"
        lightAttachment.Parent = rig

        local beamLight = Instance.new("SpotLight")
        beamLight.Name = "DanceAloneConcertSpotlight" .. i
        beamLight.Color = data[4]
        beamLight.Brightness = data[6]
        beamLight.Range = 32
        beamLight.Angle = data[5]
        beamLight.Shadows = true
        beamLight.Face = Enum.NormalId.Front
        beamLight.Parent = rig

        local beam = Instance.new("Beam")
        beam.Name = "DanceAloneConcertBeam" .. i
        beam.Attachment0 = lightAttachment
        beam.Attachment1 = targetAttachment
        beam.FaceCamera = true
        beam.Width0 = 0.85
        beam.Width1 = 3.8
        beam.LightEmission = 1
        beam.LightInfluence = 0
        beam.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.72),
            NumberSequenceKeypoint.new(0.65, 0.86),
            NumberSequenceKeypoint.new(1, 1),
        })
        beam.Color = ColorSequence.new(data[4])
        beam.Parent = rig

        spotlights[i] = {part = rig, light = beamLight, beam = beam, color = data[4], angle = data[5], attachment = lightAttachment}
    end

    local tiles = {}
    local tileColors = {cyan, violet, pink, white}
    for gx = -4, 4 do
        for gz = -4, 4 do
            local tile = addFxPart(folder, Vector3.new(1.45, 0.06, 1.45), white, 0.48)
            tile.Name = "DiscoTile"
            tiles[#tiles + 1] = {part = tile, gx = gx, gz = gz, phase = math.random() * math.pi * 2}
        end
    end

    local floorRings = {}
    for i = 1, 4 do
        floorRings[i] = addPulsingDisk(folder, tileColors[i], 2.3 + i * 0.72, 0.08, 0.07 + i * 0.015, 0.58)
    end

    local halo = addFxPart(folder, Vector3.new(0.35,0.35,0.35), white, 0.72)
    halo.Shape = Enum.PartType.Ball
    local haloLight = Instance.new("PointLight")
    haloLight.Color = white
    haloLight.Brightness = 2
    haloLight.Range = 10
    haloLight.Shadows = false
    haloLight.Parent = halo

    local burst = addEmitter(core, {
        Texture = "rbxassetid://243660364",
        Rate = 0,
        Speed = NumberRange.new(6, 14),
        Lifetime = NumberRange.new(0.15, 0.48),
        SpreadAngle = Vector2.new(360,360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0,0.08),
            NumberSequenceKeypoint.new(0.25,0.55),
            NumberSequenceKeypoint.new(1,0),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0,0.04),
            NumberSequenceKeypoint.new(0.65,0.2),
            NumberSequenceKeypoint.new(1,1),
        }),
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,cyan),
            ColorSequenceKeypoint.new(0.5,pink),
            ColorSequenceKeypoint.new(1,white),
        }),
    })

    local lastBeat = -math.huge
    return function(t, pulse, beatSnap)
        if not hrp.Parent or not folder.Parent then return end
        local floorCF = getFloorCFrame(hrp, 0.075)
        local torsoCF = getTorsoCFrame(hrp)
        core.CFrame = hrp.CFrame
        halo.CFrame = torsoCF * CFrame.new(0, 1.8, 0)

        local drive = math.clamp(pulse * 1.35 + (beatSnap or 0) * 0.45, 0, 1)
        haloLight.Brightness = 1.2 + drive * 8
        haloLight.Range = 8 + drive * 12
        light.Color = tileColors[(math.floor(t * 7) % #tileColors) + 1]
        light.Brightness = 0.45 + drive * 3.8
        light.Range = 10 + drive * 8

        local target = hrp.Position + Vector3.new(0, 1.25, 0)
        spotlightTarget.CFrame = CFrame.new(target)
        for i, s in ipairs(spotlights) do
            local p = s.part
            local sl = s.light
            local sway = Vector3.new(
                math.sin(t * 1.45 + i * 0.9) * 1.4,
                math.sin(t * 1.8 + i * 0.45) * 0.55,
                math.cos(t * 1.25 + i * 0.7) * 1.1
            )
            local localOffset = Vector3.new(spots[i][1], spots[i][2], spots[i][3]) + sway
            local pos = hrp.Position + hrp.CFrame:VectorToWorldSpace(localOffset)
            local aim = hrp.Position + Vector3.new(0, 1.25, 0)
            p.CFrame = CFrame.lookAt(pos, aim, hrp.CFrame.UpVector)
            sl.Brightness = spots[i][6] + drive * 16 + ((i % 2 == 0) and pulse * 3 or 0)
            sl.Range = 28 + drive * 18
            sl.Angle = spots[i][5] + drive * 5
            sl.Color = tileColors[((i + math.floor(t * 3)) % #tileColors) + 1]
            local beam = s.beam
            beam.Color = ColorSequence.new(sl.Color)
            beam.Width0 = 0.70 + drive * 0.55
            beam.Width1 = 3.0 + drive * 2.2
            beam.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, math.clamp(0.82 - drive * 0.26, 0.48, 0.84)),
                NumberSequenceKeypoint.new(0.60, math.clamp(0.90 - drive * 0.18, 0.62, 0.92)),
                NumberSequenceKeypoint.new(1, 1),
            })
        end

        for _, data in ipairs(tiles) do
            local tile = data.part
            local pulseTile = math.clamp(0.35 + pulse * 0.85 + math.max(0, math.sin(t * 8 + data.phase)) * 0.20, 0, 1)
            local idx = (math.floor(t * 5 + data.gx * 1.7 + data.gz * 2.3) % #tileColors) + 1
            if idx < 1 then idx += #tileColors end
            tile.Color = tileColors[idx]
            tile.Transparency = math.clamp(0.78 - pulseTile * 0.60, 0.08, 0.82)
            tile.CFrame = floorCF
                * CFrame.new(data.gx * 1.55, 0, data.gz * 1.55)
                * CFrame.Angles(0, math.rad(((data.gx + data.gz) % 2) * 6), 0)
        end

        for i, ring in ipairs(floorRings) do
            updatePulsingDisk(ring, floorCF, t + i * 0.12, drive, 1.6 + i * 0.18, 1.25 + i * 0.45)
        end

        if beatSnap and beatSnap > 0.72 and t - lastBeat > 0.10 then
            lastBeat = t
            burstEmitter(burst, 12 + math.floor(beatSnap * 18))
        end
    end
end

