    end

    local highlight = Instance.new("Highlight")
    highlight.Name = "BloodPopGlow"
    highlight.Adornee = hrp.Parent
    highlight.FillColor = Color3.fromRGB(170,50,70)
    highlight.OutlineColor = sunsetA
    highlight.FillTransparency = 0.64
    highlight.OutlineTransparency = 0.18
    highlight.DepthMode = Enum.HighlightDepthMode.Occluded
    highlight.Parent = folder

    local burst = addEmitter(core, {
        Texture = "rbxassetid://243660364",
        Rate = 0,
        Speed = NumberRange.new(8, 15),
        Lifetime = NumberRange.new(0.16, 0.42),
        SpreadAngle = Vector2.new(360,360),
        LightEmission = 1,
        LightInfluence = 0,
        Size = NumberSequence.new(0.12,0.62),
        Transparency = NumberSequence.new(0.08,1),
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,sunsetA),
            ColorSequenceKeypoint.new(0.55,sunsetB),
            ColorSequenceKeypoint.new(1,warmWhite),
        }),
    })

    local lastBeat = -math.huge
    return function(t, pulse, beatSnap)
        if not hrp.Parent or not folder.Parent then return end
        local floorCF = getFloorCFrame(hrp, 0.06)
        local torsoCF = getTorsoCFrame(hrp)
        local drive = math.clamp(pulse * 1.15 + (beatSnap or 0) * 0.45, 0, 1)

        core.CFrame = torsoCF
        sun.CFrame = torsoCF * CFrame.new(0, 3.4 + math.sin(t * 1.4) * 0.22, 2.8)
        sun.Color = Color3.fromRGB(
