            math.floor(54 + 70 * pulse)
        )
        sunLight.Color = sun.Color
        sunLight.Brightness = 1.8 + drive * 9
        sunLight.Range = 12 + drive * 10

        grade.TintColor = Color3.fromRGB(
            255,
            math.floor(158 + 60 * pulse),
            math.floor(150 + 45 * pulse)
        )
        bloom.Intensity = 0.72 + drive * 0.58
        light.Color = sunsetB
        light.Brightness = 0.55 + drive * 4.8
        light.Range = 10 + drive * 10

        for i, beam in ipairs(horizon) do
            local a = t * 0.55 + i * math.pi / 3
            local radius = 4.8 + i * 0.55
            beam.CFrame = torsoCF
                * CFrame.new(math.cos(a) * radius, 0.4 + math.sin(t * 0.9 + i) * 0.55, math.sin(a) * radius)
                * CFrame.Angles(0.5 * math.sin(a), -a, 0.25 * math.cos(a))
            beam.Transparency = math.clamp(0.65 - drive * 0.34, 0.18, 0.72)
            beam.Color = i % 2 == 0 and sunsetB or sunsetC
        end

        for i, ring in ipairs(rings) do
            updatePulsingDisk(ring, floorCF, t + i * 0.27, drive, 1.25 + i * 0.2, 1.0 + i * 0.35)
        end

        embers.Rate = 7 + math.floor(drive * 24)
        highlight.FillTransparency = math.clamp(0.72 - drive * 0.22, 0.28, 0.74)

        if beatSnap and beatSnap > 0.70 and t - lastBeat > 0.11 then
            lastBeat = t
            burstEmitter(burst, 10 + math.floor(beatSnap * 16))
            burstEmitter(spark, 4 + math.floor(beatSnap * 8))
        end
    end
end

