local function ApplyEmoteLightLimiter(token)
    if not token or not token.customFxFolder or not token.customFxFolder.Parent then return end
    for _, obj in ipairs(token.customFxFolder:GetDescendants()) do
        if obj:IsA("PointLight") then
            local baseBrightness = obj:GetAttribute("EWV5_BaseBrightness")
            local baseRange = obj:GetAttribute("EWV5_BaseRange")
            if baseBrightness == nil then
                baseBrightness = obj.Brightness
                obj:SetAttribute("EWV5_BaseBrightness", baseBrightness)
            end
            if baseRange == nil then
                baseRange = obj.Range
                obj:SetAttribute("EWV5_BaseRange", baseRange)
            end
            obj.Brightness = math.min(baseBrightness * 0.14, 0.65)
            obj.Range = math.min(baseRange * 0.72, 8)
        end
    end
end

function StartCustomDirectFx(token, e, hrp)
    if not token or token.cancelled or not e or not e.DirectAnimation then return end
    if CUSTOM_FX_EXCLUDED[e.Name] then return end

    local builder = DIRECT_FX_BUILDERS[e.Name]
    if not builder then return end

    local ok, updater = pcall(function()
        return builder(token, e, hrp)
    end)
    if not ok or type(updater) ~= "function" then
        if token.customFxFolder then
            pcall(function() token.customFxFolder:Destroy() end)
            token.customFxFolder = nil
        end
        return
    end

    token.customFxConnection = RunService.Heartbeat:Connect(function()
        if token.cancelled or ActiveToken ~= token or not hrp or not hrp.Parent then return end

        local sound = CurrentSound
        local loudness = 0
        if sound then
            pcall(function()
                loudness = math.clamp((sound.PlaybackLoudness or 0) / 260, 0, 1)
            end)
        end

        local clock = os.clock()
        token.fxLoudness = token.fxLoudness or 0
        token.fxPeak = token.fxPeak or 0
        token.fxLastBeat = token.fxLastBeat or -math.huge
        local smoothLoudness = token.fxLoudness + (loudness - token.fxLoudness) * 0.38
        local rising = smoothLoudness - token.fxLoudness
        token.fxLoudness = smoothLoudness
        token.fxPeak = math.max(smoothLoudness, token.fxPeak * 0.975)

        local syntheticBeat = (math.sin(clock * math.pi * 3.2) + 1) * 0.5
        local beatCandidate = math.clamp((smoothLoudness - 0.18) / 0.55, 0, 1)
        local beatSnap = 0
        if (beatCandidate > 0.32 and rising > 0.018) or (syntheticBeat > 0.985 and smoothLoudness > 0.10) then
            if clock - token.fxLastBeat > 0.11 then
                token.fxLastBeat = clock
                beatSnap = math.clamp(0.55 + beatCandidate * 0.75 + rising * 5.0, 0, 1)
            end
        end

        local pulse = math.clamp(smoothLoudness * 0.82 + syntheticBeat * 0.18 + beatSnap * 0.18, 0, 1)

        pcall(function()
            updater(clock, pulse, beatSnap)
            ApplyEmoteLightLimiter(token)
        end)
    end)
    table.insert(token.connections, token.customFxConnection)
end

function StopCustomDirectFx(token, fadeTime)
    if not token then return end
    if token.customLightingEffects then
        for _, effect in ipairs(token.customLightingEffects) do
            pcall(function()
                if effect and effect.Parent then
                    effect:Destroy()
                end
            end)
        end
        token.customLightingEffects = {}
    end
    if token.bouncinSketchRestore then
        pcall(token.bouncinSketchRestore)
        token.bouncinSketchRestore = nil
    end
    if token.customFxConnection then
        pcall(function()
            token.customFxConnection:Disconnect()
        end)
        token.customFxConnection = nil
    end
    if token.customFxFadeOut then
        pcall(function() token.customFxFadeOut(fadeTime or 0.24) end)
        token.customFxFadeOut = nil
    end
    if token.customFxFolder then
        local folder = token.customFxFolder
        token.customFxFolder = nil
        task.delay(fadeTime or 0, function()
            pcall(function()
                if folder and folder.Parent then
                    folder:Destroy()
                end
            end)
        end)
    end
end

