function PlayUISound(kind)
    local soundId = UI_SFX_IDS[kind]
    if not soundId then return end

    local sound = Instance.new("Sound")
    sound.Name = "EmoteWheelSFX_" .. tostring(kind)
    sound.SoundId = "rbxassetid://" .. tostring(soundId)
    sound.Volume = getUISFXVolume(kind)
    sound.RollOffMode = Enum.RollOffMode.InverseTapered
    sound.Parent = game:GetService("SoundService")
    UI_SFX_ACTIVE[sound] = kind

    local endedConn
    endedConn = sound.Ended:Connect(function()
        UI_SFX_ACTIVE[sound] = nil
        if endedConn then endedConn:Disconnect() end
        if sound and sound.Parent then sound:Destroy() end
    end)

    sound:Play()
    task.delay(8, function()
        UI_SFX_ACTIVE[sound] = nil
        if endedConn then pcall(function() endedConn:Disconnect() end) end
        if sound and sound.Parent then sound:Destroy() end
    end)
