function fadeOutSound(sound, duration, expectedFadeToken)
    if not sound or not sound.Parent then return end
    local fadeDuration = duration or TRANSITION_TIME
    TweenService:Create(sound, TweenInfo.new(fadeDuration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Volume = 0}):Play()
    task.delay(fadeDuration, function()
        if sound and sound.Parent then sound:Destroy() end
        if CurrentSound == sound and (expectedFadeToken == nil or CurrentSoundFadeToken == expectedFadeToken) then
            CurrentSound = nil
        end
    end)
end
function createLoadedSound(e, instantStart)
    if not e or NoMusicEnabled then return nil end
    local function makeSound()
        if not e.LocalAudioId and e.LocalAudioFile and isfile and getAsset and isfile(e.LocalAudioFile) then
            pcall(function() e.LocalAudioId = getAsset(e.LocalAudioFile) end)
        end
        if not e.LocalAudioId then return nil end
        local sound = Instance.new("Sound")
        sound.Name = "EmoteMusic_" .. tostring(e.AudioName or e.Name or "Audio")
        sound.SoundId = e.LocalAudioId
        sound.Looped = e.DirectAnimation == true and LoopEmotesEnabled and e.AudioSegmentEnd == nil
        sound.TimePosition = e.StartPos or e.AudioSegmentStart or 0
        sound.Parent = workspace
        return sound
    end
    local sound = makeSound()
    if not sound then
        cacheAudioForEmote(e, true)
        sound = makeSound()
    end
    if not sound then return nil end
    local loaded = sound.IsLoaded
    if not loaded and not instantStart then
        local done = false
        local conn
        conn = sound.Loaded:Connect(function()
            done = true
        end)
        local deadline = os.clock() + 1.35
        while not done and not sound.IsLoaded and os.clock() < deadline do
            task.wait(0.05)
        end
        pcall(function() conn:Disconnect() end)
        loaded = sound.IsLoaded or done
    end
    if instantStart and not loaded then
        return sound
    end
    if not loaded and e.AudioUrl then
        pcall(function() sound:Destroy() end)
        e.LocalAudioId = nil
        if cacheAudioForEmote(e, true) then
            sound = makeSound()
            if sound then
                local done = false
                local conn = sound.Loaded:Connect(function() done = true end)
                local deadline = os.clock() + 1.5
                while not done and not sound.IsLoaded and os.clock() < deadline do
                    task.wait(0.05)
                end
                pcall(function() conn:Disconnect() end)
                loaded = sound.IsLoaded or done
            end
        end
    end
    if not loaded then
        pcall(function() if sound then sound:Destroy() end end)
        return nil
    end
    return sound
end

