local EmoteLyricsCache = {}
local EmoteLyricsFetchFailed = {}

local EmoteLyricsCache = {}
local EmoteLyricsFetchFailed = {}

local function ParseEmoteLRC(raw)
    local entries = {}
    if type(raw) ~= "string" or #raw == 0 then
        return entries
    end

    local function parseTimestamp(stamp)
        local mm, ss, frac = stamp:match("^(%d+):(%d+)[%.:](%d+)$")
        mm, ss = tonumber(mm), tonumber(ss)
        if not mm or not ss or not frac then
            return nil
        end
        return (mm * 60) + ss + (tonumber("0." .. frac) or 0)
    end

    for rawLine in raw:gmatch("[^\r\n]+") do
        local line = rawLine:gsub("\r", "")

        if not line:match("^%s*%[[%a]+:[^%]]*%]%s*$") then
            local lineStamp = line:match("^%s*%[(%d+:%d+[%.:]%d+)%]")
            local lineTime = lineStamp and parseTimestamp(lineStamp)

            if lineTime then
                local body = line:gsub("^%s*%[[%d:%.,]+%]%s*", "")
                local segments = {}

                local firstStart = body:find("<%d+:%d+[%.:]%d+>")
                if firstStart then
                    local prefix = body:sub(1, firstStart - 1)
                    if prefix ~= "" then
                        segments[#segments + 1] = {
                            Time = lineTime,
                            Text = prefix,
                        }
                    end

                    local cursor = firstStart
                    while cursor <= #body do
                        local stampStart, stampEnd, stampText = body:find("<(%d+:%d+[%.:]%d+)>", cursor)
                        if not stampStart then
                            break
                        end

                        local nextStart = body:find("<%d+:%d+[%.:]%d+>", stampEnd + 1)
                        local endPos = nextStart and (nextStart - 1) or #body
                        local segmentText = body:sub(stampEnd + 1, endPos)
                        local segmentTime = parseTimestamp(stampText)

                        if segmentTime and segmentText ~= "" then
                            segments[#segments + 1] = {
                                Time = segmentTime,
                                Text = segmentText,
                            }
                        end

                        if not nextStart then
                            break
                        end
                        cursor = nextStart
                    end
                else
                    local tokens = {}
                    local cursor = 1
                    while cursor <= #body do
                        local startPos, endPos = body:find("%S+", cursor)
                        if not startPos then
                            local tail = body:sub(cursor)
                            if tail ~= "" then
                                tokens[#tokens + 1] = {Text = tail}
                            end
                            break
                        end
                        if startPos > cursor then
                            tokens[#tokens + 1] = {Text = body:sub(cursor, startPos - 1)}
                        end
                        local wordEnd = body:find("%s", endPos + 1)
                        if wordEnd then
                            local p = wordEnd
                            while p <= #body and body:sub(p, p):match("%s") do
                                p += 1
                            end
                            tokens[#tokens + 1] = {Text = body:sub(startPos, p - 1)}
                            cursor = p
                        else
                            tokens[#tokens + 1] = {Text = body:sub(startPos, endPos)}
                            cursor = endPos + 1
                        end
                    end

                    local nextLineStamp = nil
                    for _, token in ipairs(tokens) do
                        segments[#segments + 1] = {Time = nil, Text = token.Text}
                    end
                end

                local textParts = {}
                for _, segment in ipairs(segments) do
                    textParts[#textParts + 1] = segment.Text
                end

                local lyricText = table.concat(textParts):gsub("^%s+", ""):gsub("%s+$", "")
                if lyricText ~= "" then
                    entries[#entries + 1] = {
                        Time = lineTime,
                        Text = lyricText,
                        Words = segments,
                    }
                end
            end
        end
    end

    table.sort(entries, function(a, b)
        return a.Time < b.Time
    end)

    for i, entry in ipairs(entries) do
        local words = entry.Words
        local hasTimedWords = false
        for _, segment in ipairs(words or {}) do
            if segment.Time ~= nil then
                hasTimedWords = true
                break
            end
        end
        if words and #words > 0 and not hasTimedWords then
            local nextTime = entries[i + 1] and entries[i + 1].Time or (entry.Time + 3.5)
            local duration = math.max(0.35, nextTime - entry.Time)
            local totalWeight = 0
            for _, segment in ipairs(words) do
                local clean = tostring(segment.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
                if clean ~= "" then
                    totalWeight += math.max(1, #clean)
                end
            end
            if totalWeight > 0 then
                local elapsedWeight = 0
                for _, segment in ipairs(words) do
                    local clean = tostring(segment.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    if clean ~= "" then
                        segment.Time = entry.Time + (elapsedWeight / totalWeight) * duration
                        elapsedWeight += math.max(1, #clean)
                    else
                        segment.Time = entry.Time + (elapsedWeight / totalWeight) * duration
                    end
                end
            else
                for _, segment in ipairs(words) do
                    segment.Time = entry.Time
                end
            end
        end
    end

    local compact = {}
    local last
    for _, entry in ipairs(entries) do
        local duplicate = last
            and math.abs((last.Time or 0) - entry.Time) < 0.0005
            and last.Text == entry.Text
        if not duplicate then
            compact[#compact + 1] = entry
            last = entry
        end
    end

    return compact
end

local function FetchEmoteLyrics(emoteName)
    local config = EMOTE_LYRIC_CONFIG[emoteName]
    if not config then
        return nil
    end

    local url = config.LRC_URL
    if EmoteLyricsCache[url] then
        return EmoteLyricsCache[url]
    end
    local ok, raw = pcall(function()
        return game:HttpGet(url)
    end)
    if not ok or type(raw) ~= "string" or #raw < 8 then
        EmoteLyricsFetchFailed[url] = true
        return nil
    end

    local parsed = ParseEmoteLRC(raw)
    if #parsed == 0 then
        EmoteLyricsFetchFailed[url] = true
        return nil
    end

    EmoteLyricsCache[url] = parsed
    return parsed
end

local function DestroyDanceAloneLyrics(token, instant)
    if not token then return end

    if token.danceAloneLyricsConnection then
        pcall(function()
            token.danceAloneLyricsConnection:Disconnect()
        end)
        token.danceAloneLyricsConnection = nil
    end

    if token.danceAloneLyricsPulseConnection then
        pcall(function()
            token.danceAloneLyricsPulseConnection:Disconnect()
        end)
        token.danceAloneLyricsPulseConnection = nil
    end

    local gui = token.danceAloneLyricsGui
    token.danceAloneLyricsGui = nil

    local part = token.danceAloneLyricsPart
    token.danceAloneLyricsPart = nil

    token.danceAloneLyricsEntries = nil

    if gui then
        pcall(function()
            gui.Enabled = false
        end)
        pcall(function()
            gui:Destroy()
        end)
    end

    if part then
        pcall(function()
            part:Destroy()
        end)
    end
end

local function MakeEmoteLyricLabel(parent, name, zIndex, font, fontSize, alpha)
    local label = Instance.new("TextLabel")
    label.Name = name
    label.BackgroundTransparency = 1
    label.BorderSizePixel = 0
    label.ZIndex = zIndex
    label.Font = font or Enum.Font.GothamBold
    label.Text = ""
    label.TextColor3 = Color3.fromRGB(255, 255, 255)
    label.TextTransparency = alpha or 0
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0.62
    label.TextSize = fontSize or 48
    label.TextWrapped = true
    label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextYAlignment = Enum.TextYAlignment.Center
    label.Parent = parent
    return label
end

local function Utf8Characters(text)
    local chars = {}
    text = tostring(text or "")

    local function isCombining(codepoint)
        return (codepoint >= 0x0300 and codepoint <= 0x036F)
            or (codepoint >= 0x1AB0 and codepoint <= 0x1AFF)
            or (codepoint >= 0x1DC0 and codepoint <= 0x1DFF)
            or (codepoint >= 0x20D0 and codepoint <= 0x20FF)
            or (codepoint >= 0xFE20 and codepoint <= 0xFE2F)
            or (codepoint >= 0xFE00 and codepoint <= 0xFE0F)
            or (codepoint >= 0x1F3FB and codepoint <= 0x1F3FF)
    end

    local function appendCodepoint(codepoint)
        local value = utf8.char(codepoint)
        if #chars > 0 and (isCombining(codepoint) or codepoint == 0x200D) then
            chars[#chars] = chars[#chars] .. value
        elseif #chars > 0 and chars[#chars]:sub(-#utf8.char(0x200D)) == utf8.char(0x200D) then
            chars[#chars] = chars[#chars] .. value
        else
            chars[#chars + 1] = value
        end
    end

    local ok = pcall(function()
        for _, codepoint in utf8.codes(text) do
            appendCodepoint(codepoint)
        end
    end)

    if not ok or #chars == 0 then
        chars = {}
        for i = 1, #text do
            chars[#chars + 1] = text:sub(i, i)
        end
    end
    return chars
end

local LYRIC_BALL_TOP_OFFSET = 4
local LYRIC_BALL_BOUNCE_HEIGHT = 21

local function BuildLyricTimeline(entry, nextTime)
    local startTime = entry.Time or 0
    local lineEndTime = nextTime or (startTime + 3.5)
    if lineEndTime <= startTime then lineEndTime = startTime + 3.5 end

    local words = {}
    local sourceWords = entry.Words
    if type(sourceWords) ~= "table" or #sourceWords == 0 then
        sourceWords = {{Time = startTime, Text = entry.Text}}
    end

    local timed = false
    for _, seg in ipairs(sourceWords) do
        if seg.Time ~= nil then timed = true break end
    end

    local textEndTime = lineEndTime
    local pauseStart = lineEndTime
    local gap = lineEndTime - startTime
    if not timed and nextTime and gap >= LYRIC_PAUSE_MIN_GAP then
        local reserved = math.clamp(gap * 0.28, LYRIC_PAUSE_MIN_DURATION, LYRIC_PAUSE_MAX_RESERVED)
        if gap - reserved >= 0.35 then
            textEndTime = lineEndTime - reserved
            pauseStart = textEndTime
        end
    end

    if not timed then
        local totalWeight = 0
        for _, seg in ipairs(sourceWords) do
            local chars = Utf8Characters(seg.Text)
            local weight = 0
            for _, ch in ipairs(chars) do
                if not ch:match("%s") then weight += 1 end
            end
            totalWeight += math.max(1, weight)
        end
        local cursor = startTime
        local availableDuration = math.max(0.35, textEndTime - startTime)
        for _, seg in ipairs(sourceWords) do
            local chars = Utf8Characters(seg.Text)
            local weight = 0
            for _, ch in ipairs(chars) do
                if not ch:match("%s") then weight += 1 end
            end
            local span = availableDuration * (math.max(1, weight) / math.max(1, totalWeight))
            words[#words + 1] = {
                Time = cursor,
                EndTime = cursor + span,
                Text = seg.Text,
            }
            cursor += span
        end
    else
        for i, seg in ipairs(sourceWords) do
            local segStart = tonumber(seg.Time) or startTime
            local segEnd = (sourceWords[i + 1] and tonumber(sourceWords[i + 1].Time)) or textEndTime
            if segEnd <= segStart then segEnd = segStart + 0.08 end
            words[#words + 1] = {
                Time = segStart,
                EndTime = math.min(textEndTime, segEnd),
                Text = seg.Text,
            }
        end
    end

    local lastVisibleWordEnd = startTime
    for _, word in ipairs(words) do
        word.EndTime = math.max(word.EndTime or textEndTime, word.Time + 0.06)
        if word.EndTime > textEndTime then word.EndTime = textEndTime end
        local hasVisible = false
        for _, ch in ipairs(Utf8Characters(word.Text)) do
            if not ch:match("%s") then hasVisible = true break end
        end
        if hasVisible then
            lastVisibleWordEnd = math.max(lastVisibleWordEnd, word.EndTime)
        end

        local chars = Utf8Characters(word.Text)
        local charCount = 0
        for _, ch in ipairs(chars) do
            if ch ~= "" then charCount += 1 end
        end
        word.Characters = {}
        local span = math.max(0.06, word.EndTime - word.Time)
        for ci, ch in ipairs(chars) do
            local t0 = word.Time + ((ci - 1) / math.max(1, charCount)) * span
            local t1 = word.Time + (ci / math.max(1, charCount)) * span
            if ch:match("%s") then
                t0 = word.Time + ((ci - 1) / math.max(1, charCount)) * span
                t1 = math.max(t0 + 0.02, t1)
            end
            word.Characters[#word.Characters + 1] = {Text = ch, Time = t0, EndTime = t1}
        end
    end

    if timed and nextTime and lineEndTime - lastVisibleWordEnd >= LYRIC_PAUSE_MIN_DURATION then
        pauseStart = lastVisibleWordEnd
    elseif not nextTime then
        pauseStart = lineEndTime
    end

    return words, startTime, lineEndTime, math.clamp(pauseStart, startTime, lineEndTime)
end

local function DestroyDanceAloneLyrics(token, instant)
    if not token then return end
    if token.danceAloneLyricsConnection then
        pcall(function() token.danceAloneLyricsConnection:Disconnect() end)
        token.danceAloneLyricsConnection = nil
    end
    if token.danceAloneLyricsPulseConnection then
        pcall(function() token.danceAloneLyricsPulseConnection:Disconnect() end)
        token.danceAloneLyricsPulseConnection = nil
    end
    if token.countdownLabel then
        pcall(function() token.countdownLabel:Destroy() end)
        token.countdownLabel = nil
    end
    if token.danceAloneLyricsCountdownConnection then
        pcall(function() token.danceAloneLyricsCountdownConnection:Disconnect() end)
        token.danceAloneLyricsCountdownConnection = nil
    end
    local gui = token.danceAloneLyricsGui
    token.danceAloneLyricsGui = nil
    local part = token.danceAloneLyricsPart
    token.danceAloneLyricsPart = nil
    token.danceAloneLyricsEntries = nil
    if gui then pcall(function() gui.Enabled = false end); pcall(function() gui:Destroy() end) end
    if part then pcall(function() part:Destroy() end) end
end

local function StartEmoteLyrics(token, emote)
    if not token or token.cancelled or ActiveToken ~= token then return end
    if not emote or not LyricsEnabled then return end
    local config = EMOTE_LYRIC_CONFIG[emote.Name]
    if not config then return end

    local character = LocalPlayer.Character
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not character or not hrp then return end
    DestroyDanceAloneLyrics(token, true)

    local panelPart = Instance.new("Part")
    panelPart.Name = emote.Name:gsub("%W", "") .. "LyricsPanel"
    panelPart.Size = Vector3.new(7.6, 2.05, 0.05)
    panelPart.Transparency = 1
    panelPart.CanCollide = false
    panelPart.CanTouch = false
    panelPart.CanQuery = false
    panelPart.CastShadow = false
    panelPart.Massless = true
    panelPart.Anchored = false
    panelPart.CFrame = hrp.CFrame * CFrame.new(0, 0.20, -3.15)
    panelPart.Parent = character

    local weld = Instance.new("WeldConstraint")
    weld.Name = "EmoteLyricsWeld"
    weld.Part0 = hrp
    weld.Part1 = panelPart
    weld.Parent = panelPart

    local surface = Instance.new("SurfaceGui")
    surface.Name = "EmoteLyricsSurface"
    surface.Face = Enum.NormalId.Front
    surface.AlwaysOnTop = true
    surface.LightInfluence = 0
    surface.CanvasSize = Vector2.new(1200, 360)
    surface.PixelsPerStud = 135
    surface.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    surface.Parent = panelPart

    local root = Instance.new("Frame")
    root.Name = "Root"
    root.Size = UDim2.fromScale(1, 1)
    root.BackgroundTransparency = 1
    root.BorderSizePixel = 0
    root.ClipsDescendants = false
    root.Parent = surface

    local lyricBackground = Instance.new("Frame")
    lyricBackground.Name = "LyricBackground"
    lyricBackground.AnchorPoint = Vector2.new(0.5, 0.5)
    lyricBackground.Position = UDim2.new(0.5, 0, 0.5, 0)
    lyricBackground.Size = UDim2.fromOffset(100, 60)
    lyricBackground.BackgroundColor3 = Color3.fromRGB(8, 8, 10)
    lyricBackground.BackgroundTransparency = config.BackgroundTransparency or 0.28
    lyricBackground.BorderSizePixel = 0
    lyricBackground.ClipsDescendants = false
    lyricBackground.ZIndex = 2
    lyricBackground.Parent = root
    local bgCorner = Instance.new("UICorner")
    bgCorner.CornerRadius = UDim.new(0, config.CornerRadius or 12)
    bgCorner.Parent = lyricBackground
    local bgStroke = Instance.new("UIStroke")
    bgStroke.Color = Color3.fromRGB(255, 255, 255)
    bgStroke.Transparency = 0.93
    bgStroke.Thickness = 1
    bgStroke.Parent = lyricBackground

    local lyricHolder = Instance.new("Frame")
    lyricHolder.Name = "LyricHolder"
    lyricHolder.AnchorPoint = Vector2.new(0.5, 0.5)
    lyricHolder.Position = UDim2.new(0.5, 0, 0.5, 0)
    lyricHolder.Size = UDim2.fromOffset(1, 58)
    lyricHolder.BackgroundTransparency = 1
    lyricHolder.BorderSizePixel = 0
    lyricHolder.ZIndex = 3
    lyricHolder.Parent = root

    local wordsFrame = Instance.new("Frame")
    wordsFrame.Name = "Words"
    wordsFrame.AnchorPoint = Vector2.new(0.5, 0.5)
    wordsFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
    wordsFrame.Size = UDim2.fromOffset(1, 58)
    wordsFrame.BackgroundTransparency = 1
    wordsFrame.BorderSizePixel = 0
    wordsFrame.ClipsDescendants = false
    wordsFrame.ZIndex = 4
    wordsFrame.Parent = lyricHolder
    local wordLayout = Instance.new("UIListLayout")
    wordLayout.FillDirection = Enum.FillDirection.Horizontal
    wordLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    wordLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    wordLayout.SortOrder = Enum.SortOrder.LayoutOrder
    wordLayout.Padding = UDim.new(0, 0)
    wordLayout.Parent = wordsFrame

    local ballLayer = Instance.new("Frame")
    ballLayer.Name = "BallBounceLayer"
    ballLayer.AnchorPoint = Vector2.new(0.5, 0.5)
    ballLayer.Position = UDim2.new(0.5, 0, 0.5, 0)
    ballLayer.Size = UDim2.fromOffset(1, 58)
    ballLayer.BackgroundTransparency = 1
    ballLayer.BorderSizePixel = 0
    ballLayer.ClipsDescendants = false
    ballLayer.ZIndex = 8
    ballLayer.Parent = lyricHolder

    local ballIndicator = Instance.new("Frame")
    ballIndicator.Name = "BallBounceIndicator"
    ballIndicator.AnchorPoint = Vector2.new(0.5, 0.5)
    ballIndicator.Size = UDim2.fromOffset(15, 15)
    ballIndicator.Position = UDim2.fromOffset(0, 0)
    ballIndicator.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    ballIndicator.BorderSizePixel = 0
    ballIndicator.Visible = false
    ballIndicator.ZIndex = 9
    ballIndicator.Parent = ballLayer
    local ballCorner = Instance.new("UICorner")
    ballCorner.CornerRadius = UDim.new(1, 0)
    ballCorner.Parent = ballIndicator
    local ballStroke = Instance.new("UIStroke")
    ballStroke.Color = Color3.fromRGB(0, 0, 0)
    ballStroke.Transparency = 0.35
    ballStroke.Thickness = 1
    ballStroke.Parent = ballIndicator

    local pauseDotsHolder = Instance.new("Frame")
    pauseDotsHolder.Name = "LyricPauseDots"
    pauseDotsHolder.AnchorPoint = Vector2.new(0.5, 0.5)
    pauseDotsHolder.Position = UDim2.new(0.5, 0, 0.5, 0)
    pauseDotsHolder.Size = UDim2.fromOffset(120, 60)
    pauseDotsHolder.BackgroundTransparency = 1
    pauseDotsHolder.BorderSizePixel = 0
    pauseDotsHolder.Visible = false
    pauseDotsHolder.ZIndex = 12
    pauseDotsHolder.Parent = root

    local pauseDotsLayout = Instance.new("UIListLayout")
    pauseDotsLayout.FillDirection = Enum.FillDirection.Horizontal
    pauseDotsLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    pauseDotsLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    pauseDotsLayout.Padding = UDim.new(0, 9)
    pauseDotsLayout.Parent = pauseDotsHolder

    local pauseDots = {}
    for i = 1, 3 do
        local dot = MakeEmoteLyricLabel(pauseDotsHolder, "Dot" .. i, 13, config.Font or Enum.Font.GothamBold, math.max(38, (config.FontSize or 48) - 2), 0.72)
        dot.Size = UDim2.fromOffset(22, 48)
        dot.Text = "."
        dot.TextXAlignment = Enum.TextXAlignment.Center
        dot.TextYAlignment = Enum.TextYAlignment.Center
        pauseDots[i] = dot
    end

    local previousLine = MakeEmoteLyricLabel(root, "PreviousLine", 1, Enum.Font.GothamMedium, config.ContextFontSize or 18, 0.83)
    previousLine.AnchorPoint = Vector2.new(0.5, 0.5)
    previousLine.Position = UDim2.new(0.5, 0, 0.5, -66)
    previousLine.Size = UDim2.fromOffset(config.MaxTextWidth or 900, 34)
    previousLine.Font = Enum.Font.GothamMedium
    previousLine.TextStrokeTransparency = 0.82
    local nextLine = MakeEmoteLyricLabel(root, "NextLine", 1, Enum.Font.GothamMedium, config.ContextFontSize or 18, 0.85)
    nextLine.AnchorPoint = Vector2.new(0.5, 0.5)
    nextLine.Position = UDim2.new(0.5, 0, 0.5, 66)
    nextLine.Size = UDim2.fromOffset(config.MaxTextWidth or 900, 34)
    nextLine.Font = Enum.Font.GothamMedium
    nextLine.TextStrokeTransparency = 0.82
    if config.ShowContextLines == false then previousLine.Visible = false; nextLine.Visible = false end

    local currentCharLabels = {}
    local currentCharData = {}
    local currentWordLabels = {}
    local currentWordTimeline = {}
    local currentLyricIndex = 0
    local lineTransitionId = 0
    local pulseClock = 0
    local lastSoundTime = -1
    local firstFrame = true
    local currentLyricPauseStart = math.huge
    local currentLyricPauseEnd = math.huge
    local ballSmoothX = nil
    local ballSmoothY = nil
    local ballLastSoundTime = nil
    local ballCharacterCenters = {}

    local function clearWords()
        for _, child in ipairs(wordsFrame:GetChildren()) do
            if child:IsA("TextLabel") or child:IsA("Frame") then
                child:Destroy()
            end
        end
        currentCharLabels = {}
        currentCharData = {}
        currentWordLabels = {}
        currentWordTimeline = {}
        ballSmoothX = nil
        ballSmoothY = nil
        ballLastSoundTime = nil
        ballCharacterCenters = {}
        ballIndicator.Visible = false
        pauseDotsHolder.Visible = false
    end

    local function fitFont(text)
        local maxWidth = config.MaxTextWidth or 900
        local size = config.FontSize or 48
        while size > (config.MinFontSize or 30) do
            local bounds = TextService:GetTextSize(tostring(text or ""), size, config.Font or Enum.Font.GothamBold, Vector2.new(2000, 300))
            if bounds.X <= maxWidth then return size, bounds end
            size -= 2
        end
        return size, TextService:GetTextSize(tostring(text or ""), size, config.Font or Enum.Font.GothamBold, Vector2.new(maxWidth, 300))
    end

    local function makeCharacter(char, order, fontSize)
        local label = Instance.new("TextLabel")
        label.Name = "Letter_" .. tostring(order)
        label.BackgroundTransparency = 1
        label.BorderSizePixel = 0
        label.Font = config.Font or Enum.Font.GothamBold
        label.Text = char
        label.TextSize = fontSize
        label.TextColor3 = Color3.fromRGB(105, 105, 112)
        label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        label.TextStrokeTransparency = 0.78
        label.TextTransparency = 0.05
        label.TextXAlignment = Enum.TextXAlignment.Center
        label.TextYAlignment = Enum.TextYAlignment.Center
        local measuredWidth = TextService:GetTextSize(char, fontSize, label.Font, Vector2.new(500, 100)).X
        local baseWidth = math.max(1, measuredWidth)
        if char:match("%s") then
            baseWidth = math.max(baseWidth, math.floor(fontSize * 0.28))
        end
        label:SetAttribute("BaseWidth", baseWidth)
        label:SetAttribute("BaseHeight", fontSize + 10)
        label.Size = UDim2.fromOffset(baseWidth, fontSize + 10)
        label.LayoutOrder = order
        label.ZIndex = 5
        label.Parent = wordsFrame
        return label
    end

    local function renderLyric(index, entries, animate)
        clearWords()
        local entry = entries and entries[index]
        if not entry then
            previousLine.Text = ""
            nextLine.Text = entries and entries[index + 1] and entries[index + 1].Text or ""
            lyricBackground.Size = UDim2.fromOffset(1, 1)
            return
        end

        local nextTime = entries[index + 1] and entries[index + 1].Time or nil
        local words, _, endTime, pauseStart = BuildLyricTimeline(entry, nextTime)
        currentWordTimeline = words or {}
        local allChars = {}
        for wi, word in ipairs(words) do
            local cleanWord = tostring(word.Text or "")
            local hasVisible = false
            for _, ch in ipairs(Utf8Characters(cleanWord)) do
                if not ch:match("%s") then hasVisible = true break end
            end
            if hasVisible then
                for _, chData in ipairs(word.Characters) do
                    allChars[#allChars + 1] = {
                        Text = chData.Text, Time = chData.Time, EndTime = chData.EndTime, WordIndex = wi, Word = word
                    }
                end
            end
        end

        local fullText = entry.Text or ""
        local fontSize, bounds = fitFont(fullText)
        local totalBaseWidth = 0
        local baseWidths = {}
        for i, chData in ipairs(allChars) do
            currentCharData[i] = chData
            local label = makeCharacter(chData.Text, i, fontSize)
            currentCharLabels[i] = label
            local baseWidth = label:GetAttribute("BaseWidth") or label.AbsoluteSize.X
            baseWidths[i] = math.max(1, baseWidth)
            totalBaseWidth += baseWidths[i]
        end
        local lineHeight = math.max(56, fontSize + 12)
        local width = math.clamp(bounds.X, 40, config.MaxTextWidth or 900)
        lyricHolder.Size = UDim2.fromOffset(width, lineHeight)
        wordsFrame.Size = UDim2.fromOffset(width, lineHeight)
        ballLayer.Size = UDim2.fromOffset(width, lineHeight)
        ballLayer.Position = UDim2.new(0.5, 0, 0.5, 0)
        lyricBackground.Size = UDim2.fromOffset(width + (config.HorizontalPadding or 24), lineHeight + (config.VerticalPadding or 10))

        ballCharacterCenters = {}
        local stableX = -totalBaseWidth * 0.5
        for i, baseWidth in ipairs(baseWidths) do
            ballCharacterCenters[i] = stableX + (baseWidth * 0.5) + (baseWidth > 0 and 0 or 0)
            stableX += baseWidth
        end

        previousLine.Text = entries[index - 1] and entries[index - 1].Text or ""
        nextLine.Text = entries[index + 1] and entries[index + 1].Text or ""
        lineTransitionId += 1
        local thisTransition = lineTransitionId
        if animate then
            lyricHolder.Position = UDim2.new(0.5, 20, 0.5, 7)
            lyricBackground.Position = UDim2.new(0.5, 20, 0.5, 7)
            TweenService:Create(lyricHolder, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2.new(0.5, 0, 0.5, 0)}):Play()
            TweenService:Create(lyricBackground, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2.new(0.5, 0, 0.5, 0)}):Play()
            for _, label in ipairs(currentCharLabels) do
                local target = label
                task.defer(function()
                    if token.cancelled or ActiveToken ~= token or thisTransition ~= lineTransitionId then return end
                    TweenService:Create(target, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()
                end)
            end
        end
        currentLyricPauseStart = pauseStart or endTime
        currentLyricPauseEnd = endTime
        token.currentLyricEndTime = endTime
        token.currentLyricPauseStart = currentLyricPauseStart
        token.currentLyricPauseEnd = currentLyricPauseEnd
    end

    local function findLyricIndex(entries, t)
        if not entries or #entries == 0 then return 0 end
        local low, high, answer = 1, #entries, 0
        while low <= high do
            local mid = math.floor((low + high) / 2)
            if entries[mid].Time <= t then answer = mid; low = mid + 1 else high = mid - 1 end
        end
        return answer
    end

    token.danceAloneLyricsPart = panelPart
    token.danceAloneLyricsGui = surface

    task.spawn(function()
        local entries = FetchEmoteLyrics(emote.Name)
        if token.cancelled or ActiveToken ~= token or not surface.Parent then return end
        token.danceAloneLyricsEntries = entries or {}
        currentLyricIndex = 0
        if #token.danceAloneLyricsEntries > 0 then
            currentLyricIndex = 0
        end
    end)

    token.danceAloneLyricsConnection = RunService.RenderStepped:Connect(function(dt)
        if token.cancelled or ActiveToken ~= token or not surface.Parent then return end
        local sound = CurrentSound
        if not sound or not sound.Parent then return end
        local soundTime = 0
        pcall(function() soundTime = sound.TimePosition or 0 end)
        local entries = token.danceAloneLyricsEntries
        if not entries or #entries == 0 then return end

        if lastSoundTime > soundTime + 0.75 then
            currentLyricIndex = 0
            clearWords()
        end
        lastSoundTime = soundTime
        local newIndex = findLyricIndex(entries, soundTime)
        if newIndex ~= currentLyricIndex then
            currentLyricIndex = newIndex
            if currentLyricIndex > 0 then renderLyric(currentLyricIndex, entries, not firstFrame)
            else
                clearWords()
                previousLine.Text = ""
                nextLine.Text = entries[1] and entries[1].Text or ""
                lyricBackground.Size = UDim2.fromOffset(1, 1)
            end
        end

        if currentLyricIndex > 0 and entries[currentLyricIndex] then
            local entry = entries[currentLyricIndex]
            local words = currentWordTimeline
            local inLyricPause = soundTime >= (currentLyricPauseStart or math.huge) and soundTime < (currentLyricPauseEnd or math.huge)

            if inLyricPause then
                pauseDotsHolder.Visible = true
                ballIndicator.Visible = false
                for _, label in ipairs(currentCharLabels) do
                    if label and label.Parent then
                        label.TextTransparency = 1
                        label.Rotation = 0
                    end
                end

                local pauseDuration = math.max(0.05, (currentLyricPauseEnd or soundTime) - (currentLyricPauseStart or soundTime))
                local pauseProgress = math.clamp((soundTime - currentLyricPauseStart) / pauseDuration, 0, 0.9999)
                local dotPhase = pauseProgress * 3
                for i, dot in ipairs(pauseDots) do
                    local localPhase = math.clamp(dotPhase - (i - 1), 0, 1)
                    local brightness = 0.18 + 0.82 * localPhase
                    dot.TextColor3 = Color3.fromRGB(
                        math.floor(70 + 185 * brightness),
                        math.floor(70 + 185 * brightness),
                        math.floor(76 + 179 * brightness)
                    )
                    dot.TextTransparency = 0.08 + (1 - brightness) * 0.65
                    dot.Position = UDim2.fromOffset(0, -math.sin(localPhase * math.pi) * 5)
                end
            elseif type(words) == "table" and #words > 0 then
                pauseDotsHolder.Visible = false
                local wordIndex = 1
                for wi, word in ipairs(words) do
                    if soundTime >= word.Time then wordIndex = wi end
                end
                wordIndex = math.clamp(wordIndex, 1, #words)
                local activeWord = words[wordIndex]

                for i, label in ipairs(currentCharLabels) do
                    local data = currentCharData[i]
                    if label and label.Parent and data then
                        local active = soundTime >= data.Time and soundTime < data.EndTime
                        local sung = soundTime >= data.EndTime
                        local wordActive = data.WordIndex == wordIndex
                        local targetColor
                        local targetTransparency = 0
                        local scale = 1
                        local yOffset = 0

                        if sung then
                            targetColor = Color3.fromRGB(255, 255, 255)
                        elseif active then
                            local progress = math.clamp((soundTime - data.Time) / math.max(0.025, data.EndTime - data.Time), 0, 1)
                            targetColor = Color3.fromRGB(170 + math.floor(85 * progress), 170 + math.floor(85 * progress), 170 + math.floor(85 * progress))
                            scale = 1.04 + progress * 0.10
                        elseif wordActive then
                            targetColor = Color3.fromRGB(145, 145, 152)
                        else
                            targetColor = Color3.fromRGB(92, 92, 100)
                            targetTransparency = 0.10
                        end

                        if LyricStyle == "Ball Bounce" then
                            if wordActive or active then
                                local pulse = math.clamp((soundTime - (data.Time or 0)) / math.max(0.08, (data.EndTime or 0) - (data.Time or 0)), 0, 1)
                                yOffset = -math.abs(math.sin(pulse * math.pi)) * 11
                                scale += 0.08
                            end
                        elseif LyricStyle == "Wave Smooth" then
                            local phase = soundTime * 7 - (i * 0.42)
                            yOffset = math.sin(phase) * (wordActive and 7 or 2.2)
                            if active then targetColor = Color3.fromRGB(235, 235, 255) end
                        elseif LyricStyle == "Typewriter" then
                            targetTransparency = soundTime < (data.Time or 0) and 1 or (sung and 0 or 0.02)
                            if soundTime >= (data.Time or 0) then targetColor = Color3.fromRGB(255,255,255) else targetColor = Color3.fromRGB(85,85,92) end
                        elseif LyricStyle == "Letter Pop" then
                            if active then scale = 1.24 end
                        elseif LyricStyle == "Neon Sweep" then
                            if active or wordActive then
                                targetColor = Color3.fromRGB(255, 225, 255)
                                targetTransparency = 0
                            end
                        elseif LyricStyle == "Classic" then
                            if active then targetColor = Color3.fromRGB(245,245,245) end
                        else
                            if active then targetColor = Color3.fromRGB(255,255,255) end
                        end

                        label.TextColor3 = targetColor
                        label.TextTransparency = targetTransparency
                        label.TextStrokeTransparency = LyricStyle == "Neon Sweep" and 0.44 or (active and 0.55 or 0.76)
                        label.Position = UDim2.new(0, 0, 0, yOffset)
                        local baseWidth = label:GetAttribute("BaseWidth") or math.max(1, label.AbsoluteSize.X)
                        local baseHeight = label:GetAttribute("BaseHeight") or math.max(1, fontSize + 10)
                        if LyricCharacterEffects then
                            label.Size = UDim2.fromOffset(
                                math.max(1, baseWidth * scale),
                                math.max(1, baseHeight * math.min(scale, 1.18))
                            )
                        else
                            label.Size = UDim2.fromOffset(baseWidth, baseHeight)
                        end
                    end
                end

                if LyricStyle == "Ball Bounce" then
                    ballIndicator.Visible = true

                    local function getCharacterCenter(charIndex)
                        local label = currentCharLabels[charIndex]
                        local data = currentCharData[charIndex]
                        if not label or not label.Parent or not data or tostring(data.Text or ""):match("%s") then
                            return nil
                        end
                        local ballAbs = ballLayer.AbsolutePosition
                        local centerX = label.AbsolutePosition.X + (label.AbsoluteSize.X * 0.5)
                        return centerX - ballAbs.X
                    end

                    local activeCharIndex = nil
                    local nextCharIndex = nil
                    for ci, charData in ipairs(currentCharData) do
                        if charData.WordIndex == wordIndex
                            and not tostring(charData.Text or ""):match("%s")
                            and soundTime >= (charData.Time or 0)
                            and soundTime < (charData.EndTime or 0) then
                            activeCharIndex = ci
                            break
                        end
                    end

                    if not activeCharIndex then
                        for ci, charData in ipairs(currentCharData) do
                            if charData.WordIndex == wordIndex
                                and not tostring(charData.Text or ""):match("%s")
                                and soundTime >= (charData.Time or 0) then
                                activeCharIndex = ci
                            end
                        end
                    end

                    if activeCharIndex then
                        for ci = activeCharIndex + 1, #currentCharData do
                            local candidate = currentCharData[ci]
                            local label = currentCharLabels[ci]
                            if candidate and candidate.WordIndex == wordIndex and not tostring(candidate.Text or ""):match("%s") and label and label.Parent and label.Text ~= " " then
                                nextCharIndex = ci
                                break
                            end
                        end

                        if not nextCharIndex then
                            for ci = activeCharIndex + 1, #currentCharData do
                                local candidate = currentCharData[ci]
                                local label = currentCharLabels[ci]
                                if candidate and not tostring(candidate.Text or ""):match("%s") and label and label.Parent and label.Text ~= " " then
                                    nextCharIndex = ci
                                    break
                                end
                            end
                        end
                    end

                    local currentCenter = activeCharIndex and getCharacterCenter(activeCharIndex) or nil
                    local nextCenter = nextCharIndex and getCharacterCenter(nextCharIndex) or currentCenter
                    if currentCenter then
                        local charData = currentCharData[activeCharIndex]
                        local charStart = charData and charData.Time or soundTime
                        local charEnd = charData and charData.EndTime or (charStart + 0.2)
                        local charProgress = math.clamp((soundTime - charStart) / math.max(0.05, charEnd - charStart), 0, 1)
                        local eased = charProgress * charProgress * (3 - 2 * charProgress)
                        local x = currentCenter
                        if nextCenter then
                            x = currentCenter + (nextCenter - currentCenter) * eased
                        end
                        local bounce = math.sin(charProgress * math.pi)
                        local lyricCenterY = ballLayer.AbsoluteSize.Y * 0.5
                        local y = lyricCenterY - 24 - LYRIC_BALL_TOP_OFFSET - (bounce * LYRIC_BALL_BOUNCE_HEIGHT)

                        local seeked = ballLastSoundTime ~= nil and math.abs(soundTime - ballLastSoundTime) > 0.25
                        local dtBall = math.clamp(tonumber(dt) or (1 / 60), 1 / 240, 1 / 20)
                        local smoothAlpha = 1 - math.exp(-dtBall * 24)
                        if ballSmoothX == nil or ballSmoothY == nil or seeked then
                            ballSmoothX = x
                            ballSmoothY = y
                        else
                            ballSmoothX += (x - ballSmoothX) * smoothAlpha
                            ballSmoothY += (y - ballSmoothY) * smoothAlpha
                        end
                        ballLastSoundTime = soundTime
                        ballIndicator.Position = UDim2.fromOffset(ballSmoothX, ballSmoothY)
                        ballIndicator.Rotation = 0
                    else
                        ballSmoothX = nil
                        ballSmoothY = nil
                        ballLastSoundTime = nil
                        ballIndicator.Visible = false
                    end
                else
                    ballSmoothX = nil
                    ballSmoothY = nil
                    ballLastSoundTime = nil
                    ballIndicator.Visible = false
                end

                if LyricStyle == "Ball Bounce" then
                    for i, label in ipairs(currentCharLabels) do
                        local data = currentCharData[i]
                        if data and data.WordIndex == wordIndex then
                            label.Rotation = math.sin(soundTime * 9 + i * 0.3) * 2.2
                        else
                            label.Rotation = 0
                        end
                    end
                elseif LyricStyle == "Wave Smooth" then
                    for i, label in ipairs(currentCharLabels) do
                        label.Rotation = math.sin(soundTime * 4 + i * 0.22) * 1.2
                    end
                else
                    for _, label in ipairs(currentCharLabels) do label.Rotation = 0 end
                end
            end
        end

        firstFrame = false
        pulseClock += dt
        local floatY = math.sin(pulseClock * 1.8) * 2
        local floatX = math.sin(pulseClock * 1.15) * 1.2
        lyricHolder.Position = UDim2.new(0.5, floatX, 0.5, floatY)
        lyricBackground.Position = UDim2.new(0.5, floatX, 0.5, floatY)
    end)

    if LyricCountdownEnabled then
        token.danceAloneLyricsCountdownConnection = RunService.RenderStepped:Connect(function()
            if token.cancelled or ActiveToken ~= token or not surface.Parent then return end
            local sound = CurrentSound
            if not sound or not sound.Parent then return end
            local entries = token.danceAloneLyricsEntries
            if not entries or #entries == 0 then return end

            local t = sound.TimePosition or 0
            local firstStart = tonumber(entries[1].Time) or 0
            local lead = math.min(LyricCountdownDuration or 3, firstStart)

            if firstStart < LYRIC_COUNTDOWN_MIN_LEAD or t < 0 or t >= firstStart then
                if token.countdownLabel then
                    token.countdownLabel.Text = ""
                    token.countdownLabel.Visible = false
                end
                return
            end

            local countdownStart = math.max(0, firstStart - lead)
            if t >= countdownStart and t < firstStart then
                if not token.countdownLabel or not token.countdownLabel.Parent then
                    token.countdownLabel = MakeEmoteLyricLabel(root, "LyricCountdown", 14, config.Font or Enum.Font.GothamBold, math.max(64, (config.FontSize or 48) + 16), 0)
                    token.countdownLabel.AnchorPoint = Vector2.new(0.5, 0.5)
                    token.countdownLabel.Position = UDim2.new(0.5, 0, 0.5, 0)
                    token.countdownLabel.Size = UDim2.fromOffset(420, 150)
                end

                local remaining = math.max(0.001, firstStart - t)
                local number = math.clamp(math.ceil(remaining), 1, 3)
                local secondProgress = 1 - (remaining - math.floor(remaining))
                if remaining > 3 then
                    number = 3
                    secondProgress = (t - countdownStart) / math.max(0.001, lead / 3)
                end

                token.countdownLabel.Visible = true
                token.countdownLabel.Text = tostring(number)
                token.countdownLabel.TextTransparency = math.clamp(secondProgress * 0.78, 0, 0.78)
                token.countdownLabel.Rotation = math.sin(secondProgress * math.pi * 2) * 6
                token.countdownLabel.Size = UDim2.fromOffset(420 + math.floor((1 - secondProgress) * 58), 150 + math.floor((1 - secondProgress) * 58))
            elseif token.countdownLabel then
                token.countdownLabel.Text = ""
                token.countdownLabel.Visible = false
            end
        end)
    end

    token.danceAloneLyricsPulseConnection = LocalPlayer.CharacterRemoving:Connect(function(removingCharacter)
        if removingCharacter == character then DestroyDanceAloneLyrics(token, true) end
    end)
end

local function StartDanceAloneLyrics(token, emote)
    return StartEmoteLyrics(token, emote)
end

function PlaySound(e, transition)
    CurrentSoundFadeToken += 1
    local myFadeToken = CurrentSoundFadeToken
    if CurrentSound then
        local oldSound = CurrentSound
        CurrentSound = nil
        if transition then
            fadeOutSound(oldSound, TRANSITION_TIME, myFadeToken - 1)
        else
            pcall(function() oldSound:Destroy() end)
        end
    end
    if NoMusicEnabled then return end
    if not e.LocalAudioId and AutoDownloadAudioEnabled then
        cacheAudioForEmote(e, false)
    end
    if not e.LocalAudioId then return end
    local s = createLoadedSound(e, e.InstantStart == true)
    if not s then return end
    s.Volume = getEmoteMusicVolume()
    local instantAudio = e.InstantStart == true
    if transition and not instantAudio then
        s.Volume = 0
    end
    s:Play()
    if transition and not instantAudio then
        TweenService:Create(
            s,
            TweenInfo.new(TRANSITION_TIME, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {Volume = getEmoteMusicVolume()}
        ):Play()
    end
    CurrentSound = s
    if not e.DirectAnimation then
        task.delay(e.Duration or 20, function()
            if s and s.Parent then s:Destroy() end
            if CurrentSound == s then CurrentSound = nil end
        end)
    end
end
local function HardRecoverAnimationState(hum)
    if not hum or not hum.Parent then return end
    pcall(function()
        hum.PlatformStand = false
        hum.Sit = false
        hum.AutoRotate = true
    end)

end

local function SanitizeEmoteCollision(token)
    local character = LocalPlayer.Character
    if not character then return end
    local protectedNames = {
        HumanoidRootPart = true, Head = true, Torso = true,
        ["Left Arm"] = true, ["Right Arm"] = true,
        ["Left Leg"] = true, ["Right Leg"] = true,
        UpperTorso = true, LowerTorso = true,
        LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
        RightUpperArm = true, RightLowerArm = true, RightHand = true,
        LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
        RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
    }
    for _, obj in ipairs(character:GetDescendants()) do
        if obj:IsA("BasePart") and not protectedNames[obj.Name] then
            local isLikelyInvisibleTemp = obj.Transparency >= 0.95 or obj.Name == "EyesClosedEffectPart" or obj.Name:find("LyricsPanel", 1, true)
            if isLikelyInvisibleTemp then
                pcall(function()
                    obj.CanCollide = false
                    obj.CanTouch = false
                    obj.CanQuery = false
                    obj.Massless = true
                end)
            end
        end
    end

    if token and token.customFxFolder then
        for _, obj in ipairs(token.customFxFolder:GetDescendants()) do
            if obj:IsA("BasePart") then
                pcall(function()
                    obj.CanCollide = false
                    obj.CanTouch = false
                    obj.CanQuery = false
                end)
            end
        end
    end

end

function CancelActiveEmote()
    StopRandomAnimationNoise()
    BugginSyncTarget = nil
    EmoteGeneration += 1
    if ActiveToken then
        local token = ActiveToken
        token.cancelled = true
        SanitizeEmoteCollision(token)
        if token.collisionSanitizeConnection then
            pcall(function() token.collisionSanitizeConnection:Disconnect() end)
            token.collisionSanitizeConnection = nil
        end
        RestoreDirectHeadCamera(token)
        if token.bangBangRestore then
            pcall(token.bangBangRestore)
            token.bangBangRestore = nil
        end
        if token.segmentAnimationConnection then
            pcall(function() token.segmentAnimationConnection:Disconnect() end)
            token.segmentAnimationConnection = nil
        end
        if token.segmentAudioConnection then
            pcall(function() token.segmentAudioConnection:Disconnect() end)
            token.segmentAudioConnection = nil
        end
        for _, effect in ipairs(token.customLightingEffects or {}) do
            pcall(function()
                if effect and effect.Parent then effect:Destroy() end
            end)
        end
        token.customLightingEffects = {}
        for _, conn in ipairs(token.connections) do
            pcall(function() conn:Disconnect() end)
        end
        token.connections = {}
        for _, snd in ipairs(token.sounds) do
            pcall(function()
                if snd and snd.Parent then snd:Destroy() end
            end)
        end
        for _, trk in ipairs(token.tracks) do
            pcall(function() trk:Stop(0) end)
        end
        local hum = token.humanoid
        if hum then
            pcall(function()
                if token.directTrack then
                    token.directTrack:Stop(0)
                end
                hum.PlatformStand = false
                hum.Sit = token.oldSit or false
                hum.AutoRotate = token.oldAutoRotate ~= nil and token.oldAutoRotate or true
                if token.oldWalkSpeed ~= nil then hum.WalkSpeed = token.oldWalkSpeed end
                if token.oldUseJumpPower ~= nil then hum.UseJumpPower = token.oldUseJumpPower end
                if token.oldJumpPower ~= nil then hum.JumpPower = token.oldJumpPower end
                if token.oldJumpHeight ~= nil then hum.JumpHeight = token.oldJumpHeight end
                if token.oldCameraOffset then
                    hum.CameraOffset = token.oldCameraOffset
                else
                    hum.CameraOffset = Vector3.zero
                end
            end)
            HardRecoverAnimationState(hum)
        end
        if token.restoreGhost then
            pcall(token.restoreGhost)
        end
        local hrp = token.hrp
        if hrp then
            pcall(function() hrp.Anchored = false end)
        end
        if token.checkpoint then
            pcall(function()
                if token.checkpoint.Parent then token.checkpoint:Destroy() end
            end)
        end
        local customFade = token.customFxFadeOut and 0.32 or 0
        StopCustomDirectFx(token, customFade)
        if token.eyeEffectPart then
            pcall(function()
                if token.eyeEffectPart.Parent then
                    token.eyeEffectPart:Destroy()
                end
            end)
            token.eyeEffectPart = nil
        end
        DestroyDanceAloneLyrics(token, true)
        if token.proxyCharacter then
            pcall(function()
                if token.proxyCharacter.Parent then token.proxyCharacter:Destroy() end
            end)
            token.proxyCharacter = nil
            token.proxyHumanoid = nil
            token.proxyAnimator = nil
            token.proxyJointPairs = nil
            token.proxyPoseConnection = nil
        end
        ActiveToken = nil
    end
    if CurrentSound then
        CurrentSoundFadeToken += 1
        CurrentSound:Destroy()
        CurrentSound = nil
    end
    if TransitionHandoffTrack then
        pcall(function()
            if TransitionHandoffTrack.Parent then
                TransitionHandoffTrack:AdjustWeight(0, 0)
                TransitionHandoffTrack:Stop(0)
                TransitionHandoffTrack:Destroy()
            end
        end)
        TransitionHandoffTrack = nil
        TransitionHandoffHumanoid = nil
        TransitionHandoffToken = nil
    end
    IsEmoting = false
    EmoteOrigin = nil
    local recoveryHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if recoveryHum then
        pcall(function() recoveryHum.CameraOffset = Vector3.zero end)
    end
end
function TransitionActiveEmote()
    StopRandomAnimationNoise()
    BugginSyncTarget = nil
    local switchHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if switchHum then pcall(function() switchHum.CameraOffset = Vector3.zero end) end
    EmoteGeneration += 1
    local oldToken = ActiveToken

    if not oldToken then
        if CurrentSound then
            CurrentSoundFadeToken += 1
            local oldSound = CurrentSound
            CurrentSound = nil
            pcall(function() oldSound:Stop() end)
            pcall(function() oldSound:Destroy() end)
        end
        IsEmoting = false
        EmoteOrigin = nil
        return
    end

    oldToken.cancelled = true
    SanitizeEmoteCollision(oldToken)
    if oldToken.collisionSanitizeConnection then
        pcall(function() oldToken.collisionSanitizeConnection:Disconnect() end)
        oldToken.collisionSanitizeConnection = nil
    end
    oldToken.loggerProtectionGeneration = (oldToken.loggerProtectionGeneration or 0) + 1
    RestoreDirectHeadCamera(oldToken)

    for _, conn in ipairs(oldToken.connections) do
        pcall(function() conn:Disconnect() end)
    end
    oldToken.connections = {}
    StopOwnedProtectionTracks(oldToken.humanoid)

    for _, trk in ipairs(oldToken.tracks) do
        if trk and trk ~= oldToken.directTrack then
            pcall(function() trk:Stop(0) end)
        end
    end

    if oldToken.directTrack then
        pcall(function()
            oldToken.directTrack:AdjustWeight(0, 0)
            oldToken.directTrack:Stop(0)
        end)
    end

    if oldToken.restoreGhost then pcall(oldToken.restoreGhost) end
    if oldToken.hrp then pcall(function() oldToken.hrp.Anchored = false end) end
    if oldToken.checkpoint then
        pcall(function()
            if oldToken.checkpoint.Parent then oldToken.checkpoint:Destroy() end
        end)
    end
    StopCustomDirectFx(oldToken, 0)

    if oldToken.massiveLoggerProtectionTracks then
        for i, tr in pairs(oldToken.massiveLoggerProtectionTracks) do
            pcall(function() tr:Stop(0) end)
            pcall(function() tr:Destroy() end)
            oldToken.massiveLoggerProtectionTracks[i] = nil
        end
        oldToken.massiveLoggerProtectionTracks = nil
    end
    oldToken.massiveLoggerProtectionGeneration = (oldToken.massiveLoggerProtectionGeneration or 0) + 1

    if oldToken.eyeEffectConnection then
        pcall(function() oldToken.eyeEffectConnection:Disconnect() end)
        oldToken.eyeEffectConnection = nil
    end
    if oldToken.eyeEffectPart then
        pcall(function()
            if oldToken.eyeEffectPart.Parent then
                oldToken.eyeEffectPart:Destroy()
            end
        end)
        oldToken.eyeEffectPart = nil
    end

    DestroyDanceAloneLyrics(oldToken, true)

    if oldToken.proxyCharacter then
        pcall(function()
            if oldToken.proxyCharacter.Parent then oldToken.proxyCharacter:Destroy() end
        end)
        oldToken.proxyCharacter = nil
        oldToken.proxyHumanoid = nil
        oldToken.proxyAnimator = nil
        oldToken.proxyJointPairs = nil
        oldToken.proxyPoseConnection = nil
    end

    for _, snd in ipairs(oldToken.sounds) do
        if snd and snd.Parent then
            pcall(function() snd:Stop() end)
            pcall(function() snd:Destroy() end)
        end
    end
    oldToken.sounds = {}

    local oldHum = oldToken.humanoid
    if oldHum then
        pcall(function()
            oldHum.PlatformStand = false
            oldHum.Sit = false
            oldHum.AutoRotate = true
        end)
    end

    ActiveToken = nil
    IsEmoting = false
    EmoteOrigin = nil

    if CurrentSound then
        CurrentSoundFadeToken += 1
        local oldSound = CurrentSound
        CurrentSound = nil
        pcall(function() oldSound:Stop() end)
        pcall(function() oldSound:Destroy() end)
    end
end

local function FinishTransitionHandoff(newTrack)
    local oldTrack = TransitionHandoffTrack
    local oldHum = TransitionHandoffHumanoid
    TransitionHandoffTrack = nil
    TransitionHandoffHumanoid = nil
    TransitionHandoffToken = nil
    if oldTrack and oldTrack ~= newTrack and oldTrack.Parent then
        pcall(function()
            oldTrack:AdjustWeight(0, 0.06)
            oldTrack:Stop(0.06)
        end)
    end
    if oldHum and oldHum.Parent then
        pcall(function()
            oldHum.PlatformStand = false
            oldHum.Sit = false
            oldHum.AutoRotate = true
        end)
    end
end

LocalPlayer.CharacterAdded:Connect(function(newChar)
    if ActiveToken or IsEmoting then
        CancelActiveEmote()
    end
    Character = newChar
    Character.Archivable = true
end)
function createSpoofedEnv(fn, token)
    local character = LocalPlayer.Character
    local fP = setmetatable({Character = character}, {__index = LocalPlayer})
    local fPs = setmetatable({LocalPlayer = fP}, {__index = Players})
    local fRS = setmetatable({}, {
        __index = function(_, key)
            local orig = RunService[key]
            if key == "RenderStepped" or key == "Heartbeat" or key == "Stepped" then
                return setmetatable({}, {
                    __index = function(_, mkey)
                        if mkey == "Connect" then
                            return function(_, cb)
                                local conn = RunService[key]:Connect(function(dt)
                                    if token.cancelled then return end
                                    cb(dt)
                                end)
                                table.insert(token.connections, conn)
                                return conn
                            end
                        end
                        return orig[mkey]
                    end
                })
            end
            return orig
        end
    })
    local fG = setmetatable({Players = fPs}, {
        __index = function(_, k)
            if k == "GetService" then
                return function(_, svc)
                    if svc == "Players" then return fPs end
                    if svc == "RunService" then return fRS end
                    return game:GetService(svc)
                end
            end
            return game[k]
        end
    })
    local fTask = setmetatable({}, {
        __index = function(_, k)
            if k == "spawn" then
                return function(cb)
                    task.spawn(function()
                        if token.cancelled then return end
                        cb()
                    end)
                end
            elseif k == "wait" or k == "delay" then
                return function(t2, cb2)
                    if cb2 then
                        task.delay(t2, function()
                            if token.cancelled then return end
                            cb2()
                        end)
                    else
                        task.wait(t2)
                    end
                end
            end
            return task[k]
        end
    })
    local function sfxWrapped(id, parent, duration, startPos)
        if token.cancelled then return Instance.new("Sound") end
        local s = Instance.new("Sound")
        s.SoundId = id
        s.Parent = parent
        applySoundVolume(s, 1)
        s:Play()
        s.TimePosition = startPos or 0
        table.insert(token.sounds, s)
        task.spawn(function()
            local fadeTime = 3
            local startFade = math.max((duration or s.TimeLength) - fadeTime, 0)
            task.wait(startFade)
            local startVol = s.Volume
            local steps = 30
            for i = 1, steps do
                if not s.Parent or token.cancelled then break end
                s.Volume = startVol * (1 - (i / steps))
                task.wait(fadeTime / steps)
            end
            if s.Parent then s.Volume = 0 end
        end)
        pcall(function() game.Debris:AddItem(s, duration or 0) end)
        return s
    end
    local function humanoidProxy(realHum)
        return setmetatable({}, {
            __index = function(_, k)
                if k == "LoadAnimation" then
                    return function(_, anim)
                        local trk = realHum:LoadAnimation(anim)
                        table.insert(token.tracks, trk)
                        return trk
                    end
                end
                if not token.humanoid then
                    token.humanoid = realHum
                    token.oldSit = realHum.Sit
                    token.oldAutoRotate = realHum.AutoRotate
                end
                return realHum[k]
            end,
            __newindex = function(_, k, v)
                realHum[k] = v
            end,
        })
    end
    local charProxy = setmetatable({}, {
        __index = function(_, k)
            if k == "WaitForChild" then
                return function(_, name, timeout)
                    local obj = character:WaitForChild(name, timeout)
                    if name == "Humanoid" then
                        return humanoidProxy(obj)
                    elseif name == "HumanoidRootPart" then
                        token.hrp = obj
                    elseif name == "Head" then
                        token.head = obj
                    end
                    return obj
                end
            end
            return character[k]
        end,
        __newindex = function(_, k, v) character[k] = v end,
    })
    local fPWrapped = setmetatable({Character = charProxy}, {__index = LocalPlayer})
    local fPsWrapped = setmetatable({LocalPlayer = fPWrapped}, {__index = Players})
    fG.Players = fPsWrapped
    local function WaitWrapped(t2)
        if token.cancelled then return end
        task.wait(t2)
    end
    local env = getfenv(fn)
    return setmetatable({
        game = fG,
        Game = fG,
        workspace = workspace,
        task = fTask,
        Wait = WaitWrapped,
        wait = WaitWrapped,
        sfx = sfxWrapped,
        RunService = fRS,
        _cancelToken = token,
    }, {
        __index = env,
        __newindex = function(_, k, v) env[k] = v end,
    })
end

local function StartAnimationSegmentLoop(token, track, e)
    if not token or not track or not e then return end
    local startPos = tonumber(e.AnimationSegmentStart)
    local endPos = tonumber(e.AnimationSegmentEnd)
    if startPos == nil or endPos == nil or endPos <= startPos then return end

    if token.segmentAnimationConnection then
        pcall(function() token.segmentAnimationConnection:Disconnect() end)
        token.segmentAnimationConnection = nil
    end

    pcall(function()
        track.Looped = true
        track.TimePosition = startPos
    end)

    token.segmentAnimationConnection = RunService.RenderStepped:Connect(function()
        if token.cancelled or ActiveToken ~= token or not track.IsPlaying then return end
        if track.TimePosition >= endPos then
            pcall(function()
                track.TimePosition = startPos
            end)
        elseif track.TimePosition < startPos then
            pcall(function()
                track.TimePosition = startPos
            end)
        end
    end)

    table.insert(token.connections, token.segmentAnimationConnection)
end

local function StartAudioSegmentLoop(token, e)
    if not token or not e then return end
    local startPos = tonumber(e.AudioSegmentStart)
    local endPos = tonumber(e.AudioSegmentEnd)
    if startPos == nil or endPos == nil or endPos <= startPos then return end

    if token.segmentAudioConnection then
        pcall(function() token.segmentAudioConnection:Disconnect() end)
        token.segmentAudioConnection = nil
    end

    token.segmentAudioConnection = RunService.Heartbeat:Connect(function()
        if token.cancelled or ActiveToken ~= token then return end
        local sound = CurrentSound
        if not sound or not sound.Parent then return end

        pcall(function()
            if sound.TimePosition < startPos - 0.05 then
                sound.TimePosition = startPos
            elseif sound.TimePosition >= endPos then
                sound.TimePosition = startPos
            end
        end)
    end)

    table.insert(token.connections, token.segmentAudioConnection)
end

local function BuildProtectedProxyRig(token, sourceCharacter)
    if not token or not sourceCharacter then return nil, nil, nil end
    local ok, proxy = pcall(function() return sourceCharacter:Clone() end)
    if not ok or not proxy then return nil, nil, nil end

    proxy.Name = "EWV5_ProtectedProxy_" .. tostring(token.generation)
    proxy.Archivable = false

    for _, obj in ipairs(proxy:GetDescendants()) do
        if obj:IsA("BasePart") then
            obj.Anchored = true
            obj.CanCollide = false
            obj.CanTouch = false
            obj.CanQuery = false
            obj.Transparency = 1
            obj.LocalTransparencyModifier = 1
            obj.CastShadow = false
        elseif obj:IsA("Decal") or obj:IsA("Texture") then
            obj.Transparency = 1
        elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
            or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
            obj.Enabled = false
        elseif obj:IsA("Script") or obj:IsA("LocalScript") or obj:IsA("ModuleScript") then
            pcall(function() obj:Destroy() end)
        elseif obj:IsA("Tool") then
            pcall(function() obj:Destroy() end)
        end
    end

    local humanoid = proxy:FindFirstChildOfClass("Humanoid")
    if not humanoid then
        proxy:Destroy()
        return nil, nil, nil
    end

    local animator = humanoid:FindFirstChildOfClass("Animator") or Instance.new("Animator")
    animator.Parent = humanoid

    local camera = workspace.CurrentCamera
    proxy.Parent = camera or workspace
    if proxy.PrimaryPart then
        proxy:PivotTo(sourceCharacter:GetPivot())
    end

    local sourceJoints = {}
    local proxyJoints = {}
    for _, obj in ipairs(sourceCharacter:GetDescendants()) do
        if obj:IsA("Motor6D") then
            sourceJoints[obj.Name] = obj
        end
    end
    for _, obj in ipairs(proxy:GetDescendants()) do
        if obj:IsA("Motor6D") then
            proxyJoints[obj.Name] = obj
        end
    end

    local pairsToCopy = {}
    for name, sourceJoint in pairs(sourceJoints) do
        local proxyJoint = proxyJoints[name]
        if proxyJoint then
            pairsToCopy[#pairsToCopy + 1] = {source = sourceJoint, proxy = proxyJoint}
        end
    end

    token.proxyCharacter = proxy
    token.proxyHumanoid = humanoid
    token.proxyAnimator = animator
    token.proxyJointPairs = pairsToCopy
    token.protectedClock = 0
    token.protectedSpeed = 1

    local existingAnimator = sourceCharacter:FindFirstChildOfClass("Humanoid")
    existingAnimator = existingAnimator and existingAnimator:FindFirstChildOfClass("Animator")
    if existingAnimator then
        for _, oldTrack in ipairs(existingAnimator:GetPlayingAnimationTracks()) do
            pcall(function()
                oldTrack:AdjustWeight(0, 0)
                oldTrack:Stop(0)
            end)
        end
    end

    local connection
    local bind = function()
        if token.cancelled or ActiveToken ~= token or not proxy.Parent or not sourceCharacter.Parent then
            if connection then pcall(function() connection:Disconnect() end) end
            return
        end
        for _, pair in ipairs(token.proxyJointPairs or {}) do
            local sourceJoint = pair.source
            local proxyJoint = pair.proxy
            if sourceJoint.Parent and proxyJoint.Parent then
                pcall(function()
                    sourceJoint.Transform = proxyJoint.Transform
                end)
            end
        end
    end

    local okPre = pcall(function()
        connection = RunService.PreSimulation:Connect(bind)
    end)
    if not okPre or not connection then
        connection = RunService.RenderStepped:Connect(bind)
    end
    token.proxyPoseConnection = connection
    table.insert(token.connections, connection)

    return proxy, humanoid, animator
end

function ExecEmoteImmediate(e)
    StopRandomAnimationNoise()
    if IsEmoting or ActiveToken or CurrentSound then
        TransitionActiveEmote()
    else
        CancelActiveEmote()
    end
    local token = NewToken()
    token.emote = e
    local tokenGeneration = token.generation
    ActiveToken = token
    StartRetroTrackWatcher(token)
    SanitizeEmoteCollision(token)
    token.collisionSanitizeConnection = workspace.DescendantAdded:Connect(function(obj)
        if token.cancelled or ActiveToken ~= token then return end
        if not obj:IsA("BasePart") then return end

        local localCharacter = LocalPlayer.Character
        local inLocalCharacter = localCharacter and obj:IsDescendantOf(localCharacter)
        local ancestorModel = obj:FindFirstAncestorOfClass("Model")
        local owner = ancestorModel and Players:GetPlayerFromCharacter(ancestorModel)
        local parent = obj.Parent
        local parentName = parent and tostring(parent.Name) or ""
        local parentParent = parent and parent.Parent
        local grandParentName = parentParent and tostring(parentParent.Name) or ""
        local isEmoteFx = parentName:sub(1, 8) == "EmoteFX_"
            or grandParentName:sub(1, 8) == "EmoteFX_"
            or obj.Name == "FXPart"
            or obj.Name:find("LyricsPanel", 1, true)
            or obj.Name:find("Emote", 1, true)
            or obj.Name:find("Effect", 1, true)
            or obj.Name:find("FX", 1, true)

        if owner and owner ~= LocalPlayer then return end

        if inLocalCharacter or isEmoteFx or not owner then
            pcall(function()
                obj.CanCollide = false
                obj.CanTouch = false
                obj.CanQuery = false
                obj.Massless = true
            end)
        end
    end)
    table.insert(token.connections, token.collisionSanitizeConnection)

    token.collisionSanitizeHeartbeat = RunService.Heartbeat:Connect(function()
        if token.cancelled or ActiveToken ~= token then return end
        local currentChar = LocalPlayer.Character
        local root = currentChar and currentChar:FindFirstChild("HumanoidRootPart")
        if not root then return end

        pcall(function()
            for _, obj in ipairs(currentChar:GetDescendants()) do
                if obj:IsA("BasePart") and obj.Name ~= "HumanoidRootPart" then
                    local isCharacterBody = obj.Name == "Head" or obj.Name == "Torso"
                        or obj.Name == "Left Arm" or obj.Name == "Right Arm"
                        or obj.Name == "Left Leg" or obj.Name == "Right Leg"
                        or obj.Name == "UpperTorso" or obj.Name == "LowerTorso"
                        or obj.Name == "LeftUpperArm" or obj.Name == "LeftLowerArm"
                        or obj.Name == "LeftHand" or obj.Name == "RightUpperArm"
                        or obj.Name == "RightLowerArm" or obj.Name == "RightHand"
                        or obj.Name == "LeftUpperLeg" or obj.Name == "LeftLowerLeg"
                        or obj.Name == "LeftFoot" or obj.Name == "RightUpperLeg"
                        or obj.Name == "RightLowerLeg" or obj.Name == "RightFoot"
                    if not isCharacterBody then
                        obj.CanCollide = false
                        obj.CanTouch = false
                        obj.CanQuery = false
                        obj.Massless = true
                    end
                end
            end

            local params = OverlapParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = {currentChar}
            params.MaxParts = 100
            for _, obj in ipairs(workspace:GetPartBoundsInRadius(root.Position, 10, params)) do
                if obj:IsA("BasePart") and obj.Transparency >= 0.95 then
                    local ownerModel = obj:FindFirstAncestorOfClass("Model")
                    local owner = ownerModel and Players:GetPlayerFromCharacter(ownerModel)
                    if not owner or owner == LocalPlayer then
                        obj.CanCollide = false
                        obj.CanTouch = false
                        obj.CanQuery = false
                        obj.Massless = true
                    end
                end
            end
        end)
    end)
    table.insert(token.connections, token.collisionSanitizeHeartbeat)
    local char = LocalPlayer.Character
    if char then
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp then EmoteOrigin = hrp.CFrame end
    end
    IsEmoting = true
    StopRandomAnimationNoise()
    if RememberLastEmoteEnabled then
        LastEmoteName = e.Name
        SaveSettings()
    end
    if StopOnMovementEnabled then
        local movementConn = RunService.RenderStepped:Connect(function()
            if token.cancelled or ActiveToken ~= token then return end
            local currentChar = LocalPlayer.Character
            local currentHum = currentChar and currentChar:FindFirstChildOfClass("Humanoid")
            if currentHum and currentHum.MoveDirection.Magnitude > 0.05 then
                local state = currentHum:GetState()
                local airborne = state == Enum.HumanoidStateType.Jumping
                    or state == Enum.HumanoidStateType.Freefall
                    or state == Enum.HumanoidStateType.FallingDown
                if not (ContinueEmoteOnJumpEnabled and airborne) then
                    CancelActiveEmote()
                end
            end
        end)
        table.insert(token.connections, movementConn)
    end
    ShowNotification(e.Name, not NoMusicEnabled)
    if e.DirectAnimation then
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local head = char and char:FindFirstChild("Head")
        if not hum or not hrp or not head then
            IsEmoting = false
            EmoteOrigin = nil
            ActiveToken = nil
            return
        end
        token.humanoid = hum
        token.hrp = hrp
        token.head = head
        token.oldSit = hum.Sit
        token.oldAutoRotate = hum.AutoRotate
        token.oldWalkSpeed = hum.WalkSpeed
        token.oldJumpPower = hum.JumpPower
        token.oldJumpHeight = hum.JumpHeight
        token.oldUseJumpPower = hum.UseJumpPower
        token.directAnimation = true

        local animator = hum:FindFirstChildOfClass("Animator")
        if not animator then
            animator = Instance.new("Animator")
            animator.Parent = hum
        end

        local anim = Instance.new("Animation")
        anim.Name = e.Name .. "_EWV5"
        local numericId = tonumber(tostring(e.AnimationId):match("(%d+)$"))
        if not numericId then
            anim:Destroy()
            CancelActiveEmote()
            return
        end
        anim.AnimationId = BuildEmoteAnimationId(numericId)

        local track
        local ok = pcall(function()
            track = animator:LoadAnimation(anim)
        end)
        anim:Destroy()
        if not ok or not track then
            CancelActiveEmote()
            return
        end
        token.directTrack = track
        table.insert(token.tracks, track)
        track.Priority = Enum.AnimationPriority.Action4
        local forcedLoop = e.ForceAnimationLoop == true
        local hasAnimationSegment = e.AnimationSegmentStart ~= nil or (e.AudioSegmentStart ~= nil and e.AudioSegmentEnd ~= nil)
        track.Looped = forcedLoop or LoopEmotesEnabled
        if not track.Looped and not hasAnimationSegment then
            local endedConn = track.Stopped:Connect(function()
                if ActiveToken == token and not token.cancelled then
                    IsEmoting = false
                    EmoteOrigin = nil
                    CancelActiveEmote()
                end
            end)
            table.insert(token.connections, endedConn)
        end
        if token.oldWalkSpeed ~= nil then hum.WalkSpeed = token.oldWalkSpeed end
        if token.oldUseJumpPower ~= nil then hum.UseJumpPower = token.oldUseJumpPower end
        if token.oldJumpPower ~= nil then hum.JumpPower = token.oldJumpPower end
        if token.oldJumpHeight ~= nil then hum.JumpHeight = token.oldJumpHeight end
        hum.PlatformStand = false
        hum.Sit = false
        hum.AutoRotate = token.oldAutoRotate ~= nil and token.oldAutoRotate or true
        StartDirectHeadCamera(token, hum, hrp, head)
        if e.Name == "Bounce" then
            token.bounceTrack = track
            track:Play(0.12, 1, 0)
            pcall(function()
                track:AdjustSpeed(0)
            end)
            StartBounceStopMotion(token, track)
        else
            if e.AnimationSegmentStart ~= nil and e.AnimationSegmentEnd ~= nil then
                pcall(function() track.TimePosition = tonumber(e.AnimationSegmentStart) or 0 end)
            end
            local normalSpeed = e.AnimationSpeed or 1
            track:Play(0.12, 1, RetroModeEnabled and 0 or normalSpeed)
            if RetroModeEnabled then
                StartRetroChoppyMotion(token, track, normalSpeed)
            end
        end
        local jumpConn = hum.StateChanged:Connect(function(_, newState)
            if token.cancelled or ActiveToken ~= token or not ContinueEmoteOnJumpEnabled then return end
            if newState == Enum.HumanoidStateType.Jumping
                or newState == Enum.HumanoidStateType.Freefall
                or newState == Enum.HumanoidStateType.Landed then
                if not track.IsPlaying then
                    local normalSpeed = e.AnimationSpeed or 1
                    pcall(function()
                        track:Play(0.05, 1, (e.Name == "Bounce" or RetroModeEnabled) and 0 or normalSpeed)
                    end)
                    if e.Name == "Bounce" then
                        StartBounceStopMotion(token, track)
                    elseif RetroModeEnabled then
                        StartRetroChoppyMotion(token, track, normalSpeed)
                    end
                end
            end
        end)
        table.insert(token.connections, jumpConn)
        StartRandomAnimationNoise(token)

        if e.AnimationSegmentStart ~= nil and e.AnimationSegmentEnd ~= nil then
            StartAnimationSegmentLoop(token, track, e)
        elseif e.AnimationLoopAt then
            local loopAt = math.max(0.05, tonumber(e.AnimationLoopAt) or 0.05)
            local loopConn = RunService.RenderStepped:Connect(function()
                if token.cancelled or ActiveToken ~= token or not track.IsPlaying then return end
                if track.TimePosition >= loopAt then
                    pcall(function()
                        track.TimePosition = 0
                    end)
                    if e.AudioLoopAt and CurrentSound and CurrentSound.Parent then
                        pcall(function()
                            CurrentSound.TimePosition = 0
                        end)
                    end
                end
            end)
            table.insert(token.connections, loopConn)
        end


        PlaySound(e, true)
        StartAudioSegmentLoop(token, e)
        if LyricsEnabled and EMOTE_LYRIC_CONFIG[e.Name] then
            StartEmoteLyrics(token, e)
        end
        if e.Name == EYE_CLOSED_EMOTE then
            StartEyeClosedEffect(token, hrp)
        end
        if e.DirectAnimation and not CUSTOM_FX_EXCLUDED[e.Name] then
            StartCustomDirectFx(token, e, hrp)
        end
        return
    end
    PlaySound(e, true)
    local early = e.MusicEarly or 0
    task.spawn(function()
        local fallback = e.Duration or 30
        local elapsed = 0
        local interval = 0.1
        local waitedForTrack = 0
        while #token.tracks == 0 and not token.cancelled and waitedForTrack < 3 do
            task.wait(interval)
            waitedForTrack += interval
        end
        if token.cancelled then return end
        if #token.tracks == 0 then
            task.wait(math.max(0, fallback - waitedForTrack))
            if ActiveToken == token and EmoteGeneration == tokenGeneration then
                IsEmoting = false
                EmoteOrigin = nil
                ActiveToken = nil

            end
            return
        end
        while not token.cancelled and elapsed < fallback do
            task.wait(interval)
            elapsed += interval
            local anyPlaying = false
            for _, trk in ipairs(token.tracks) do
                if trk and trk.IsPlaying then
                    anyPlaying = true
                    break
                end
            end
            if not anyPlaying then break end
        end
        if ActiveToken == token and not token.cancelled and EmoteGeneration == tokenGeneration then
            IsEmoting = false
            EmoteOrigin = nil
            ActiveToken = nil

        end
    end)
    task.delay(early, function()
        if token.cancelled then return end
        local code = ScriptCache[e.Name]
        if code then
            task.spawn(function()
                local fn = loadstring(code)
                if fn then
                    setfenv(fn, createSpoofedEnv(fn, token))
                    pcall(fn)
                end
            end)
        else
            task.spawn(function()
                while not ScriptCache[e.Name] and not token.cancelled do task.wait(0.05) end
                if token.cancelled then return end
                local fn = loadstring(ScriptCache[e.Name])
                if fn then
                    setfenv(fn, createSpoofedEnv(fn, token))
                    pcall(fn)
                end
            end)
        end
    end)
end

local RemoteEmoteFxTokens = {}
local RemoteEmoteFxWatcherClock = 0

local function GetAnimationNumericId(animationId)
    if type(animationId) == "number" then
        return math.floor(animationId)
    end
    local text = tostring(animationId or "")
    return tonumber(text:match("[&?]id=(%d+)")
        or text:match("rbxassetid://(%d+)")
        or text:match("asset/(%d+)")
        or text:match("(%d+)$"))
end

local EMOTE_BY_ANIMATION_ID = {}
local EMOTE_BY_TRACK_NAME = {}
local function normalizeRemoteEmoteName(value)
    return string.lower(tostring(value or "")):gsub("[%W_]+", "")
end

for _, emote in ipairs(EMOTES) do
    local id = GetAnimationNumericId(emote.AnimationId)
    if id then
        EMOTE_BY_ANIMATION_ID[id] = EMOTE_BY_ANIMATION_ID[id] or {}
        table.insert(EMOTE_BY_ANIMATION_ID[id], emote)
    end
    local names = {emote.Name, emote.Short, emote.AudioName}
    for _, nameValue in ipairs(names) do
        local key = normalizeRemoteEmoteName(nameValue)
        if key ~= "" then
            EMOTE_BY_TRACK_NAME[key] = EMOTE_BY_TRACK_NAME[key] or emote
        end
    end
end

local REMOTE_PROTECTED_ID_SET = {}
if type(LOGGER_PROTECTION_MASSIVE_IDS) == "table" then
    for _, entry in ipairs(LOGGER_PROTECTION_MASSIVE_IDS) do
        local id = type(entry) == "table" and entry.Id or entry
        id = tonumber(id)
        if id then REMOTE_PROTECTED_ID_SET[math.floor(id)] = true end
    end
end
if type(LOGGER_PROTECTION_IDS) == "table" then
    for _, group in pairs(LOGGER_PROTECTION_IDS) do
        if type(group) == "table" then
            for _, value in ipairs(group) do
                local id = tonumber(type(value) == "table" and value.Id or value)
                if id then REMOTE_PROTECTED_ID_SET[math.floor(id)] = true end
            end
        end
    end
end

local function IsRemoteProtectionTrack(track)
    if not track then return true end

    local owned = false
    pcall(function()
        owned = track:GetAttribute("EWV5_LoggerProtection") == true
    end)
    if owned then return true end

    return false
end

function GetRemoteEmoteForTrack(track)
    if not track or not track.IsPlaying or IsRemoteProtectionTrack(track) then return nil end

    local animation = track.Animation
    local id = animation and GetAnimationNumericId(animation.AnimationId)
    local candidates = id and EMOTE_BY_ANIMATION_ID[id]
    if candidates then
        local position = tonumber(track.TimePosition) or 0
        for _, emote in ipairs(candidates) do
            local startPos = tonumber(emote.AnimationSegmentStart)
            local endPos = tonumber(emote.AnimationSegmentEnd)
            if startPos ~= nil and endPos ~= nil and position >= (startPos - 0.16) and position <= (endPos + 0.16) then
                return emote
            end
        end
        for _, emote in ipairs(candidates) do
            if emote.DirectAnimation then return emote end
        end
        return candidates[1]
    end

    local nameCandidates = {
        animation and animation.Name,
        track.Name,
    }
    for _, nameValue in ipairs(nameCandidates) do
        local key = normalizeRemoteEmoteName(nameValue)
        if key ~= "" then
            local exact = EMOTE_BY_TRACK_NAME[key]
            if exact then return exact end
        end
    end

    for _, nameValue in ipairs(nameCandidates) do
        local key = normalizeRemoteEmoteName(nameValue)
        if #key >= 6 then
            for knownKey, knownEmote in pairs(EMOTE_BY_TRACK_NAME) do
                if #knownKey >= 6 and (string.find(key, knownKey, 1, true) or string.find(knownKey, key, 1, true)) then
                    return knownEmote
                end
            end
        end
    end
    return nil
end

local function StopRemoteEmoteFx(player)
    local state = RemoteEmoteFxTokens[player]
    if not state then return end
    state.cancelled = true
    if state.connection then pcall(function() state.connection:Disconnect() end) end
    if state.customFxFolder and state.customFxFolder.Parent then pcall(function() state.customFxFolder:Destroy() end) end
    for _, effect in ipairs(state.customLightingEffects or {}) do
        pcall(function() if effect and effect.Parent then effect:Destroy() end end)
    end
    RemoteEmoteFxTokens[player] = nil
end

local function StartRemoteEmoteFx(player, emote, track)
    if not BugginRigsEnabled or not player or player == LocalPlayer or not emote or not track then return end
    if not emote.DirectAnimation or CUSTOM_FX_EXCLUDED[emote.Name] then return end
    local builder = DIRECT_FX_BUILDERS[emote.Name]
    if not builder then return end
    local character = player.Character
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local existing = RemoteEmoteFxTokens[player]
    if existing and existing.track == track and not existing.cancelled then return end
    StopRemoteEmoteFx(player)

    local token = {cancelled=false, customLightingEffects={}, remote=true, track=track}
    local ok, updater = pcall(function() return builder(token, emote, hrp) end)
    if not ok or type(updater) ~= "function" then
        if token.customFxFolder and token.customFxFolder.Parent then token.customFxFolder:Destroy() end
        return
    end

    token.connection = RunService.Heartbeat:Connect(function()
        if token.cancelled or not track.Parent or not track.IsPlaying or not hrp.Parent then
            StopRemoteEmoteFx(player)
            return
        end
        local position = track.TimePosition or 0
        local speed = math.max(0.05, math.abs(track.Speed or 1))
        local phase = position * 4.2 + os.clock() * speed * 0.35
        local synthetic = (math.sin(phase * math.pi * 2) + 1) * 0.5
        local beat = synthetic > 0.96 and 0.85 or 0
        local pulse = math.clamp(0.55 + synthetic * 0.30 + beat * 0.20, 0, 1)
        pcall(function() updater(os.clock(), pulse, beat) end)
    end)
    RemoteEmoteFxTokens[player] = token
end

local function RefreshRemoteEmoteFx()
    if not BugginRigsEnabled then
        for player in pairs(RemoteEmoteFxTokens) do StopRemoteEmoteFx(player) end
        return
    end
    local seen = {}
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer then
            local character = player.Character
            local hum = character and character:FindFirstChildOfClass("Humanoid")
            local animator = hum and hum:FindFirstChildOfClass("Animator")
            if animator then
                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                    local emote = GetRemoteEmoteForTrack(track)
                    if emote then
                        seen[player] = true
                        StartRemoteEmoteFx(player, emote, track)
                        break
                    end
                end
            end
        end
    end
    for player in pairs(RemoteEmoteFxTokens) do
        if not seen[player] then StopRemoteEmoteFx(player) end
    end
end

