local RemoteSyncClickClock = 0
local RemoteHoverPlayer = nil
local RemoteHoverEmote = nil
local RemoteHoverHighlight = nil

local function GetPlayerFromScreenPoint(screenPosition)
    if not screenPosition then return nil, nil end

    local camera = workspace.CurrentCamera
    if camera then
        local unitRay = camera:ScreenPointToRay(screenPosition.X, screenPosition.Y)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = {LocalPlayer.Character}
        params.IgnoreWater = true

        local result = workspace:Raycast(unitRay.Origin, unitRay.Direction * 1000, params)
        local part = result and result.Instance
        local model = part and part:FindFirstAncestorOfClass("Model")
        local player = model and Players:GetPlayerFromCharacter(model)
        if player and player ~= LocalPlayer then
            return player, model
        end
    end

    local mouse = LocalPlayer:GetMouse()
    local targetPart = mouse and mouse.Target
    if targetPart then
        local targetModel = targetPart:FindFirstAncestorOfClass("Model")
        local targetPlayer = targetModel and Players:GetPlayerFromCharacter(targetModel)
        if targetPlayer and targetPlayer ~= LocalPlayer then
            return targetPlayer, targetModel
        end
    end

    return nil, nil
end

local function GetBestRemoteEmoteTrack(player)
    local character = player and player.Character
    local hum = character and character:FindFirstChildOfClass("Humanoid")
    local animator = hum and hum:FindFirstChildOfClass("Animator")
    if not animator then return nil, nil end

    local bestTrack, bestEmote, bestScore = nil, nil, -math.huge
    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
        if track and track.IsPlaying and not IsRemoteProtectionTrack(track) then
            local emote = GetRemoteEmoteForTrack(track)
            if emote then
                local score = 0
                local weight = tonumber(track.WeightCurrent) or 0
                local speed = math.abs(tonumber(track.Speed) or 1)
                local priority = 0
                pcall(function() priority = tonumber(track.Priority.Value) or 0 end)
                score += math.clamp(weight, 0, 1) * 100
                score += priority * 2
                if speed > 0.01 then score += 10 end
                if emote.DirectAnimation then score += 30 end
                if score > bestScore then
                    bestScore = score
                    bestTrack = track
                    bestEmote = emote
                end
            end
        end
    end
    return bestTrack, bestEmote
end

local function GetTokenSyncTrack(token)
    if not token or token.cancelled then return nil end
    if token.directTrack and token.directTrack.Parent and token.directTrack.IsPlaying then
        return token.directTrack
    end
    for _, candidate in ipairs(token.tracks or {}) do
        if candidate and candidate.Parent and candidate.IsPlaying then
            return candidate
        end
    end
    return nil
end

local function ApplyRemoteSyncToToken(token, remoteTrack, desired)
    if not token or token.cancelled or not remoteTrack or not remoteTrack.IsPlaying then return false end
    local deadline = os.clock() + 1.25
    while os.clock() < deadline and not token.cancelled and ActiveToken == token do
        local targetTrack = GetTokenSyncTrack(token)
        if targetTrack then
            pcall(function()
                if remoteTrack.IsPlaying and targetTrack.IsPlaying then
                    targetTrack.TimePosition = remoteTrack.TimePosition
                    local targetSpeed = tonumber(remoteTrack.Speed) or 1
                    local fallbackSpeed = tonumber(desired and desired.AnimationSpeed) or 1
                    targetTrack:AdjustSpeed(targetSpeed ~= 0 and targetSpeed or fallbackSpeed)
                end
            end)
            return true
        end
        task.wait(0.03)
    end
    return false
end

local function SetRemoteHoverHighlight(player, emote)
    if not SyncWithOthersEnabled or not player or player == LocalPlayer or not emote then
        if RemoteHoverHighlight then
            RemoteHoverHighlight.Enabled = false
            RemoteHoverHighlight.Adornee = nil
        end
        RemoteHoverPlayer = nil
        RemoteHoverEmote = nil
        return
    end

    local character = player.Character
    if not character then return end
    if not RemoteHoverHighlight then
        RemoteHoverHighlight = Instance.new("Highlight")
        RemoteHoverHighlight.Name = "EWV6_RemoteEmoteHover"
        RemoteHoverHighlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        RemoteHoverHighlight.FillTransparency = 0.82
        RemoteHoverHighlight.OutlineTransparency = 0.05
        RemoteHoverHighlight.FillColor = Color3.fromRGB(255, 255, 255)
        RemoteHoverHighlight.OutlineColor = Color3.fromRGB(255, 255, 255)
        RemoteHoverHighlight.Parent = workspace
    end
    RemoteHoverHighlight.Adornee = character
    RemoteHoverHighlight.Enabled = true
    RemoteHoverPlayer = player
    RemoteHoverEmote = emote
end

local function UpdateRemoteEmoteHover(screenPosition)
    if not SyncWithOthersEnabled or not screenPosition then
        SetRemoteHoverHighlight(nil, nil)
        return
    end
    local player = GetPlayerFromScreenPoint(screenPosition)
    if not player or player == LocalPlayer then
        SetRemoteHoverHighlight(nil, nil)
        return
    end
    local remoteTrack, desired = GetBestRemoteEmoteTrack(player)
    if not remoteTrack or not desired then
        SetRemoteHoverHighlight(nil, nil)
        return
    end
    SetRemoteHoverHighlight(player, desired)

    StartRemoteEmoteFx(player, desired and remoteTrack or nil, remoteTrack)
end

local RemoteContinuousSyncToken = nil
local RemoteContinuousSyncTrack = nil

local function StopRemoteContinuousSync()
    RemoteContinuousSyncToken = nil
    RemoteContinuousSyncTrack = nil
    BugginSyncTarget = nil
    PendingSyncTrack = nil
end

local function StartRemoteContinuousSync(token, remoteTrack, desired)
    if not token or token.cancelled or not remoteTrack then return end
    RemoteContinuousSyncToken = token
    RemoteContinuousSyncTrack = remoteTrack
    BugginSyncTarget = remoteTrack
    PendingSyncTrack = nil

    task.spawn(function()
        while RemoteContinuousSyncToken == token
            and RemoteContinuousSyncTrack == remoteTrack
            and not token.cancelled
            and ActiveToken == token do
            if not remoteTrack.Parent or not remoteTrack.IsPlaying then
                break
            end
            local localTrack = GetTokenSyncTrack(token)
            if localTrack and localTrack.Parent and localTrack.IsPlaying then
                pcall(function()
                    localTrack.TimePosition = remoteTrack.TimePosition
                    local remoteSpeed = tonumber(remoteTrack.Speed) or 1
                    local fallbackSpeed = tonumber(desired and desired.AnimationSpeed) or 1
                    localTrack:AdjustSpeed(remoteSpeed ~= 0 and remoteSpeed or fallbackSpeed)
                end)
            end
            RunService.RenderStepped:Wait()
        end
        if RemoteContinuousSyncToken == token then
            RemoteContinuousSyncToken = nil
            RemoteContinuousSyncTrack = nil
            if BugginSyncTarget == remoteTrack then
                BugginSyncTarget = nil
            end
        end
    end)
end

local function SyncToRemotePlayerAt(screenPosition)
    if not SyncWithOthersEnabled or not screenPosition then return false end
    local now = os.clock()
    if now - RemoteSyncClickClock < 0.15 then return false end

    local player = GetPlayerFromScreenPoint(screenPosition)
    if not player or player == LocalPlayer then return false end
    local remoteTrack, desired = GetBestRemoteEmoteTrack(player)
    if not remoteTrack or not desired then return false end

    StartRemoteEmoteFx(player, desired, remoteTrack)

    RemoteSyncClickClock = now
    BugginSyncTarget = remoteTrack
    PendingSyncTrack = remoteTrack

    if ActiveToken and ActiveToken.emote and ActiveToken.directAnimation then
        local current = ActiveToken.emote
        local currentId = GetAnimationNumericId(current.AnimationId)
        local remoteId = GetAnimationNumericId(remoteTrack.Animation and remoteTrack.Animation.AnimationId)
        if current == desired or (currentId and remoteId and currentId == remoteId) then
            StartRemoteContinuousSync(ActiveToken, remoteTrack, current)
            ApplyRemoteSyncToToken(ActiveToken, remoteTrack, current)
            return true
        end
    end

    task.spawn(function()
        if not SyncWithOthersEnabled or not remoteTrack.Parent or not remoteTrack.IsPlaying then return end

        local previousToken = ActiveToken
        local previousGeneration = previousToken and previousToken.generation or -1
        local previousEmote = previousToken and previousToken.emote or nil

        ExecEmoteImmediate(desired)

        local deadline = os.clock() + 1.75
        local token = nil
        while os.clock() < deadline and SyncWithOthersEnabled do
            if not remoteTrack.Parent or not remoteTrack.IsPlaying then return end

            local candidate = ActiveToken
            if candidate and not candidate.cancelled
                and candidate ~= previousToken
                and candidate.emote == desired
                and (candidate.generation or -1) ~= previousGeneration then
                token = candidate
                break
            end

            if not previousEmote and candidate and not candidate.cancelled and candidate.emote == desired then
                token = candidate
                break
            end

            task.wait(0.02)
        end

        if not token or token.cancelled or ActiveToken ~= token then
            PendingSyncTrack = nil
            return
        end

        PendingSyncTrack = nil
        StartRemoteContinuousSync(token, remoteTrack, desired)
        ApplyRemoteSyncToToken(token, remoteTrack, desired)

        if V6 and V6.Toast and token and ActiveToken == token then
            local targetCharacter = remoteTrack.Parent
                and remoteTrack.Parent.Parent
                and remoteTrack.Parent.Parent.Parent
            local targetPlayer = targetCharacter and Players:GetPlayerFromCharacter(targetCharacter)
            V6:Toast(
                "SYNCED",
                targetPlayer and ("Following " .. targetPlayer.DisplayName .. "'s dance") or "Following clicked player's dance"
            )
        end
    end)
    return true
end

RunService.Heartbeat:Connect(function()
