local EMOTE_SPAM_WINDOW = 0.12
local LastEmoteStartClock = 0
local PendingEmote = nil
local PendingEmoteSerial = 0

function ExecEmote(e)
    if not e then return end
    local now = os.clock()
    local elapsed = now - LastEmoteStartClock

    if elapsed < EMOTE_SPAM_WINDOW then
        PendingEmote = e
        PendingEmoteSerial += 1
        local serial = PendingEmoteSerial
        local delayTime = EMOTE_SPAM_WINDOW - elapsed

        task.delay(delayTime, function()
            if serial ~= PendingEmoteSerial or PendingEmote ~= e then return end
            PendingEmote = nil
            LastEmoteStartClock = os.clock()
            ExecEmoteImmediate(e)
        end)
        return
    end

    PendingEmote = nil
    PendingEmoteSerial += 1
    LastEmoteStartClock = now
    ExecEmoteImmediate(e)
end

function CanOpenWheelWhileEmoting()
    return true
end
function IsDirectEmoteActive()
    return IsEmoting and ActiveToken and ActiveToken.directAnimation
end
function RunRig(clone, e)
    task.spawn(function()
        if e.DirectAnimation then
            local hum = clone:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            local anim = Instance.new("Animation")
            local numericId = tonumber(tostring(e.AnimationId):match("(%d+)$"))
            if not numericId then return end
            anim.Name = e.Name .. "_EWV5_Clone"
            anim.AnimationId = BuildEmoteAnimationId(numericId)
            local track
            local ok = pcall(function()
                track = hum:LoadAnimation(anim)
            end)
            anim:Destroy()
            if not ok or not track then return end
            track.Priority = Enum.AnimationPriority.Action4
            track.Looped = true
            track:Play(0.12, 1, e.AnimationSpeed or 1)
            local animSegStart = tonumber(e.AnimationSegmentStart)
            local animSegEnd = tonumber(e.AnimationSegmentEnd)
            if animSegStart ~= nil and animSegEnd ~= nil and animSegEnd > animSegStart then
                pcall(function()
                    track.TimePosition = animSegStart
                end)
                local segStart = animSegStart
                local segEnd = animSegEnd
                local segmentConn
                segmentConn = RunService.RenderStepped:Connect(function()
                    if not track or not track.Parent or not track.IsPlaying then
                        if segmentConn then
                            pcall(function() segmentConn:Disconnect() end)
                        end
                        return
                    end
                    if track.TimePosition < segStart then
                        pcall(function() track.TimePosition = segStart end)
                    elseif track.TimePosition >= segEnd then
                        pcall(function() track.TimePosition = segStart end)
                    end
                end)
            elseif e.AnimationLoopAt then
                local loopAt = math.max(0.05, tonumber(e.AnimationLoopAt) or 0.05)
                local previewConn
                previewConn = RunService.RenderStepped:Connect(function()
                    if not track or not track.Parent or not track.IsPlaying then
                        if previewConn then
                            previewConn:Disconnect()
                            previewConn = nil
                        end
                        return
                    end
                    if track.TimePosition >= loopAt then
                        pcall(function()
                            track.TimePosition = 0
                        end)
                    end
                end)
            end
            return
        end
        while not ScriptCache[e.Name] do
            task.wait(0.05)
        end
        local fn = loadstring(ScriptCache[e.Name])
        if fn then
            local animator = clone:FindFirstChildOfClass("Humanoid") and clone:FindFirstChildOfClass("Humanoid"):FindFirstChildOfClass("Animator")
            if animator then
                animator.AnimationPlayed:Connect(function(previewTrack)
                    pcall(function() previewTrack.Priority = Enum.AnimationPriority.Action4 end)
                end)
                for _, playingTrack in ipairs(animator:GetPlayingAnimationTracks()) do
                    pcall(function() playingTrack.Priority = Enum.AnimationPriority.Action4 end)
                end
            end
            local fP = setmetatable({Character = clone}, {__index = LocalPlayer})
            local fPs = setmetatable({LocalPlayer = fP}, {__index = Players})
            local fG = setmetatable({Players = fPs}, {
                __index = function(_, k)
                    if k == "GetService" then
                        return function(_, svc)
                            if svc == "Players" then return fPs end
                            return game:GetService(svc)
                        end
                    end
                    return game[k]
                end
            })
            local env = getfenv(fn)
            setfenv(fn, setmetatable({game=fG, Game=fG, workspace=clone.Parent}, {
                __index = env,
                __newindex = function(_,k,v) env[k]=v end
            }))
            pcall(fn)
        end
    end)
end
function makeBuffer()
    return table.create(RES * RES * 4, 0)
end
function normAngle(a)
    local TAU = math.pi * 2
    while a < 0 do a += TAU end
    while a >= TAU do a -= TAU end
    return a
end
function angleInSlice(a, sA, eA)
    a = normAngle(a)
    sA = normAngle(sA)
    eA = normAngle(eA)
    if sA <= eA then
        return a >= sA and a < eA
    else
        return a >= sA or a < eA
    end
end
function drawWheel(buf, hovered, pageEmotes)
    for i = 1, #buf do buf[i] = 0 end
    local num = #pageEmotes
    local sliceRad = math.rad(360 / num)
    local gapRad = math.rad(GAP_DEG)
    local startBase = -math.pi / 2
    for i = 1, num do
        local sA = startBase + (i-1) * sliceRad + gapRad * 0.5
        local eA = startBase + i * sliceRad - gapRad * 0.5
        local isH = hovered == i
        for py = 0, RES-1 do
            for px = 0, RES-1 do
                local dx = px - HALF
                local dy = py - HALF
                local dist = math.sqrt(dx*dx + dy*dy)
                if dist >= INNER_R and dist <= OUTER_R then
                    local ang = math.atan2(dy, dx)
                    if angleInSlice(ang, sA, eA) then
                        local t = (dist - INNER_R) / (OUTER_R - INNER_R)
                        local pr, pg, pb, alpha
                        if isH then
                            local bright = math.floor(200 + t * 40)
                            pr, pg, pb = bright, bright, bright
                            alpha = math.floor(230 + t * 20)
                        else
                            local dark = math.floor(15 + t * 10)
                            pr, pg, pb = dark, dark, dark
                            alpha = math.floor(170 + t * 30)
                        end
                        if dist > OUTER_R - 2 then
                            alpha = math.floor(alpha * (OUTER_R - dist) / 2)
                        elseif dist < INNER_R + 2 then
                            alpha = math.floor(alpha * (dist - INNER_R) / 2)
                        end
                        alpha = math.clamp(alpha, 0, 255)
                        local idx = (py * RES + px) * 4 + 1
                        buf[idx] = pr
                        buf[idx+1] = pg
                        buf[idx+2] = pb
                        buf[idx+3] = alpha
                    end
                end
            end
        end
    end
    for py = 0, RES-1 do
        for px = 0, RES-1 do
            local dx = px - HALF
            local dy = py - HALF
            local dist = math.sqrt(dx*dx + dy*dy)
            local idx = (py * RES + px) * 4 + 1
            if math.abs(dist - OUTER_R) < 1.8 then
                local a = math.max(0, 255 - math.abs(dist - OUTER_R) * 145)
                buf[idx]=220; buf[idx+1]=220; buf[idx+2]=220; buf[idx+3]=a
            end
            if math.abs(dist - INNER_R) < 1.4 then
                local a = math.max(0, 200 - math.abs(dist - INNER_R) * 155)
                buf[idx]=180; buf[idx+1]=180; buf[idx+2]=180; buf[idx+3]=a
            end
        end
    end
    for i = 1, num do
        local lineAng = startBase + (i-1) * sliceRad
        local lx = math.cos(lineAng)
        local ly = math.sin(lineAng)
        for r = INNER_R, OUTER_R do
            local wx = HALF + lx * r
            local wy = HALF + ly * r
            for ox = -1, 1 do
                for oy = -1, 1 do
                    local px2 = math.floor(wx + ox)
                    local py2 = math.floor(wy + oy)
                    if px2 >= 0 and px2 < RES and py2 >= 0 and py2 < RES then
                        local perp = math.abs(ox * (-ly) + oy * lx)
                        if perp < 0.9 then
                            local idx = (py2 * RES + px2) * 4 + 1
                            local alpha = math.floor(220 * (1 - perp))
                            buf[idx] = 220
                            buf[idx+1] = 220
                            buf[idx+2] = 220
                            buf[idx+3] = math.min(255, buf[idx+3] + alpha)
                        end
                    end
                end
            end
        end
    end
end
