        local midRad = math.rad(midDeg)
        local cx = DISPLAY/2 + math.cos(midRad) * vpMidR * SCALE
        local cy = DISPLAY/2 + math.sin(midRad) * vpMidR * SCALE
        local holder = Instance.new("Frame")
