SETTINGS_FOLDER = "EmoteWheelV5"
SETTINGS_FILE = SETTINGS_FOLDER .. "/settings.txt"

local function ensureSettingsFolder()
    if not makefolder then return false end
    if isfolder then
        if not isfolder(SETTINGS_FOLDER) then
            pcall(function() makefolder(SETTINGS_FOLDER) end)
        end
    else
        pcall(function() makefolder(SETTINGS_FOLDER) end)
    end
    return isfolder and isfolder(SETTINGS_FOLDER) or true
end

function BuildEmoteAnimationId(numericId)
    numericId = tonumber(numericId)
    if not numericId then return nil end

    local mode = AnimationIdMode
    if mode == "GUID_COVER" then
        mode = "GUID"
    elseif mode == "VERSION_COVER" then
        mode = "VERSION"
    end

    if mode == "RBXASSETID" then
        return "rbxassetid://" .. tostring(numericId)
    elseif mode == "VERSION" then
        local length = math.random(1, 15)
        local digits = {tostring(math.random(1, 9))}
        for i = 2, length do
            digits[i] = tostring(math.random(0, 9))
        end
        return "http://www.roblox.com/asset/?version=" .. table.concat(digits) .. "&id=" .. tostring(numericId)
    end
    return "http" .. HttpService:GenerateGUID() .. "=" .. tostring(numericId)
end

function SaveSettings()
    if not (writefile and HttpService and HttpService.JSONEncode) then return false end
    ensureSettingsFolder()
    local data = {
        MasterVolume = MasterVolume,
        EmoteMusicVolume = EmoteMusicVolume,
        WheelDim = WheelDim,
        NotificationsOn = NotificationsOn,
        LyricsEnabled = LyricsEnabled,
        BugginRigsEnabled = BugginRigsEnabled,
        SyncWithOthersEnabled = SyncWithOthersEnabled,
        HideEffectsEnabled = HideEffectsEnabled,
        LowEffectsEnabled = LowEffectsEnabled,
        ScreenEffectsEnabled = ScreenEffectsEnabled,
        PerformanceModeEnabled = PerformanceModeEnabled,
        ShowStatsEnabled = ShowStatsEnabled,
        AutoDownloadAudioEnabled = AutoDownloadAudioEnabled,
        StopOnMovementEnabled = StopOnMovementEnabled,
        RememberLastEmoteEnabled = RememberLastEmoteEnabled,
        LoopEmotesEnabled = LoopEmotesEnabled,
        RetroModeEnabled = RetroModeEnabled,
        ContinueEmoteOnJumpEnabled = ContinueEmoteOnJumpEnabled,
        ContinueEmoteStopKey = ContinueEmoteStopKey and ContinueEmoteStopKey.Name or "P",
        InterfaceScale = InterfaceScale,
        AnimationIdMode = AnimationIdMode,
        MusicEnabled = not NoMusicEnabled,
        CommandStatusBarEnabled = CommandStatusBarEnabled,
        LastEmoteName = LastEmoteName,
        LyricStyle = LyricStyle,
        LyricCountdownEnabled = LyricCountdownEnabled,
        LyricCharacterEffects = LyricCharacterEffects,
        UISFX = UI_SFX_VOLUMES,
        Keybinds = {},
    }
    for name, keyCode in pairs(KEYBINDS) do
        if typeof(keyCode) == "EnumItem" then
            data.Keybinds[name] = keyCode.Name
        elseif keyCode then
            data.Keybinds[name] = tostring(keyCode):match("%.([^%.]+)$")
        end
    end
    local ok, encoded = pcall(function() return HttpService:JSONEncode(data) end)
    if not ok or type(encoded) ~= "string" then return false end
    return pcall(function() writefile(SETTINGS_FILE, encoded) end)
end

local function LoadSettings()
    if not (readfile and isfile and HttpService and HttpService.JSONDecode) then return false end
    if not isfile(SETTINGS_FILE) then return false end
    local okRead, raw = pcall(function() return readfile(SETTINGS_FILE) end)
    if not okRead or type(raw) ~= "string" or raw == "" then return false end
    local okDecode, data = pcall(function() return HttpService:JSONDecode(raw) end)
    if not okDecode or type(data) ~= "table" then return false end

    MasterVolume = tonumber(data.MasterVolume) or MasterVolume
    EmoteMusicVolume = tonumber(data.EmoteMusicVolume) or EmoteMusicVolume
    WheelDim = tonumber(data.WheelDim) or WheelDim
    if data.NotificationsOn ~= nil then NotificationsOn = data.NotificationsOn == true end
    if data.LyricsEnabled ~= nil then LyricsEnabled = data.LyricsEnabled == true end
    if data.BugginRigsEnabled ~= nil then BugginRigsEnabled = data.BugginRigsEnabled == true end
    if data.SyncWithOthersEnabled ~= nil then SyncWithOthersEnabled = data.SyncWithOthersEnabled == true end
    if data.HideEffectsEnabled ~= nil then HideEffectsEnabled = data.HideEffectsEnabled == true end
    if data.LowEffectsEnabled ~= nil then LowEffectsEnabled = data.LowEffectsEnabled == true end
    if data.ScreenEffectsEnabled ~= nil then ScreenEffectsEnabled = data.ScreenEffectsEnabled == true end
    if data.PerformanceModeEnabled ~= nil then PerformanceModeEnabled = data.PerformanceModeEnabled == true end
    if data.ShowStatsEnabled ~= nil then ShowStatsEnabled = data.ShowStatsEnabled == true end
    if data.AutoDownloadAudioEnabled ~= nil then AutoDownloadAudioEnabled = data.AutoDownloadAudioEnabled == true end
    if data.StopOnMovementEnabled ~= nil then StopOnMovementEnabled = data.StopOnMovementEnabled == true end
    if data.RememberLastEmoteEnabled ~= nil then RememberLastEmoteEnabled = data.RememberLastEmoteEnabled == true end
    if data.LoopEmotesEnabled ~= nil then LoopEmotesEnabled = data.LoopEmotesEnabled == true end
    if data.RetroModeEnabled ~= nil then RetroModeEnabled = data.RetroModeEnabled == true end
    if data.ContinueEmoteOnJumpEnabled ~= nil then ContinueEmoteOnJumpEnabled = data.ContinueEmoteOnJumpEnabled == true end
    if type(data.ContinueEmoteStopKey) == "string" and Enum.KeyCode[data.ContinueEmoteStopKey] then
        ContinueEmoteStopKey = Enum.KeyCode[data.ContinueEmoteStopKey]
    end
    InterfaceScale = tonumber(data.InterfaceScale) or InterfaceScale
    if type(data.AnimationIdMode) == "string" and (data.AnimationIdMode == "GUID" or data.AnimationIdMode == "VERSION" or data.AnimationIdMode == "RBXASSETID" or data.AnimationIdMode == "GUID_COVER" or data.AnimationIdMode == "VERSION_COVER") then
        AnimationIdMode = data.AnimationIdMode
    end
    if data.MusicEnabled ~= nil then NoMusicEnabled = not (data.MusicEnabled == true) end
    if data.CommandStatusBarEnabled ~= nil then CommandStatusBarEnabled = data.CommandStatusBarEnabled == true end
    if type(data.LyricStyle) == "string" then
        for _, style in ipairs(LYRIC_STYLES) do
            if data.LyricStyle == style then LyricStyle = style break end
        end
    end
    if data.LyricCountdownEnabled ~= nil then LyricCountdownEnabled = data.LyricCountdownEnabled == true end
    if data.LyricCharacterEffects ~= nil then LyricCharacterEffects = data.LyricCharacterEffects == true end
    if type(data.LastEmoteName) == "string" and data.LastEmoteName ~= "" then LastEmoteName = data.LastEmoteName end

    if type(data.UISFX) == "table" then
        for name, value in pairs(data.UISFX) do
            if UI_SFX_VOLUMES[name] ~= nil and tonumber(value) then
                UI_SFX_VOLUMES[name] = math.clamp(tonumber(value), 0, 1)
            end
        end
    end

    if HideEffectsEnabled then LowEffectsEnabled = false end
    if LowEffectsEnabled then HideEffectsEnabled = false end

    if type(data.Keybinds) == "table" then
        for name, keyName in pairs(data.Keybinds) do
            if type(name) == "string" and type(keyName) == "string" and Enum.KeyCode[keyName] then
                KEYBINDS[name] = Enum.KeyCode[keyName]
            end
        end
    end
    return true
end

