    value.TextColor3 = Color3.fromRGB(235,235,235)
    value.Text = formatter and formatter(initialV, false) or tostring(initialV)
    value.TextXAlignment = Enum.TextXAlignment.Right
    value.ZIndex = 62
    value.Parent = row

    local track = Instance.new("Frame")
    track.Size = UDim2.new(1,0,0,5)
    track.Position = UDim2.new(0,0,0,28)
    track.BackgroundColor3 = Color3.fromRGB(38,38,38)
    track.BorderSizePixel = 0
    track.ZIndex = 62
    track.Parent = row
    Instance.new("UICorner", track).CornerRadius = UDim.new(1,0)

    local pct0 = (initialV-minV)/(maxV-minV)
    local fill = Instance.new("Frame")
    fill.Size = UDim2.new(math.clamp(pct0,0,1),0,1,0)
    fill.BackgroundColor3 = Color3.fromRGB(210,210,210)
    fill.BorderSizePixel = 0
    fill.ZIndex = 63
    fill.Parent = track
    Instance.new("UICorner", fill).CornerRadius = UDim.new(1,0)

    local knob = Instance.new("Frame")
    knob.Size = UDim2.new(0,11,0,11)
    knob.AnchorPoint = Vector2.new(0.5,0.5)
    knob.Position = UDim2.new(math.clamp(pct0,0,1),0,0.5,0)
    knob.BackgroundColor3 = Color3.fromRGB(245,245,245)
    knob.BorderSizePixel = 0
    knob.ZIndex = 64
    knob.Parent = track
    Instance.new("UICorner", knob).CornerRadius = UDim.new(1,0)

    local drag = Instance.new("TextButton")
    drag.Size = UDim2.new(1,18,0,24)
    drag.Position = UDim2.new(0,-9,0,19)
    drag.BackgroundTransparency = 1
    drag.Text = ""
    drag.ZIndex = 65
    drag.Parent = row

    local current = initialV
    local function setValue(v)
        current = math.clamp(v, minV, maxV)
        local pct = (current-minV)/(maxV-minV)
        fill.Size = UDim2.new(pct,0,1,0)
        knob.Position = UDim2.new(pct,0,0.5,0)
        value.Text = formatter and formatter(current, false) or tostring(current)
        callback(current)
    end
    local function updateFromX(x)
        local left = track.AbsolutePosition.X
        local width = math.max(track.AbsoluteSize.X,1)
        setValue(minV + math.clamp((x-left)/width,0,1)*(maxV-minV))
    end
    drag.Activated:Connect(function()
        SettingsDragging = drag
        updateFromX(UserInputService:GetMouseLocation().X)
    end)
    drag.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            SettingsDragging = drag
            if input.Position then updateFromX(input.Position.X) end
        end
    end)
    drag.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if SettingsDragging == drag then SettingsDragging = nil end
        end
    end)
    local handle = {Row=row, Title=title, Value=value, Track=track, Fill=fill, Knob=knob, Set=setValue, Drag=drag}
    table.insert(SettingsSliders, handle)
    return handle
end

function makeToggle(parent, y, labelText, initial, callback)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1,-32,0,34)
    btn.Position = UDim2.new(0,16,0,y)
    btn.BackgroundColor3 = Color3.fromRGB(18,18,18)
    btn.BorderSizePixel = 0
    btn.AutoButtonColor = false
    btn.Font = Enum.Font.SourceSansSemibold
    btn.TextSize = 9
    btn.TextXAlignment = Enum.TextXAlignment.Left
    btn.TextColor3 = Color3.fromRGB(200,200,200)
    btn.ZIndex = 62
    btn.Parent = parent
    local state = initial
    local function render()
        btn.Text = "  " .. labelText .. "    " .. (state and "ON" or "OFF")
        btn.BackgroundColor3 = state and Color3.fromRGB(25,25,25) or Color3.fromRGB(14,14,14)
    end
    btn.Activated:Connect(function()
        state = not state
        callback(state)
        render()
    end)
    render()
    return {
        Button = btn,
        Set = function(v)
            state = v and true or false
            callback(state)
            render()
        end,
        Get = function() return state end,
    }
end

local function isVisualEffect(obj)
    return obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
        or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles")
        or obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight")
        or obj:IsA("Highlight") or obj:IsA("SelectionBox") or obj:IsA("SelectionSphere")
        or obj:IsA("PostEffect") or obj:IsA("Sky") or obj:IsA("Atmosphere")
end

local function isCustomFxPart(obj)
    if not obj:IsA("BasePart") then return false end
    if obj.Name == "FXPart" or obj.Name == "EyesClosedEffectPart" or obj.Name == "PulsingDisk" then return true end
    local parent = obj.Parent
    while parent and parent ~= workspace do
        if parent:IsA("Folder") and tostring(parent.Name):sub(1,8) == "EmoteFX_" then return true end
        parent = parent.Parent
    end
    return false
end

local function restoreEffect(obj)
    local original = EffectOriginals[obj]
    if not original or not obj then
        EffectOriginals[obj] = nil
        return
    end
    pcall(function()
        if original.Parent ~= nil and obj.Parent ~= original.Parent then obj.Parent = original.Parent end
        if original.Enabled ~= nil then obj.Enabled = original.Enabled end
        if original.Rate ~= nil then obj.Rate = original.Rate end
        if original.Lifetime ~= nil then obj.Lifetime = original.Lifetime end
        if original.Brightness ~= nil then obj.Brightness = original.Brightness end
        if original.Range ~= nil then obj.Range = original.Range end
        if original.Density ~= nil then obj.Density = original.Density end
        if original.Haze ~= nil then obj.Haze = original.Haze end
        if original.Glare ~= nil then obj.Glare = original.Glare end
        if original.LocalTransparencyModifier ~= nil then obj.LocalTransparencyModifier = original.LocalTransparencyModifier end
    end)
    EffectOriginals[obj] = nil
end

local function isEmoteOwnedEffect(obj)
    if not obj or not obj.Parent then return false end

    if obj:GetAttribute("EWV5_ClientPostEffect") == true then
        return true
    end

    if isCustomFxPart(obj) then
        return true
    end

    local parent = obj.Parent
    while parent and parent ~= game do
        if parent:IsA("Folder") and tostring(parent.Name):sub(1, 8) == "EmoteFX_" then
            return true
        end
        if isCustomFxPart(parent) then
            return true
        end
        if parent == Lighting then
            return obj:GetAttribute("EWV5_ClientPostEffect") == true
        end
        parent = parent.Parent
    end

    return false
end

local function applyEffectModeTo(obj)
    if not obj or not obj.Parent then return end
    local needs = (isVisualEffect(obj) or isCustomFxPart(obj)) and isEmoteOwnedEffect(obj)
    if not needs then return end
    if not EffectOriginals[obj] then
        EffectOriginals[obj] = {
            Parent = (obj:IsA("Sky") and obj.Parent) or nil,
            Enabled = (
                obj:IsA("ParticleEmitter")
                or obj:IsA("Trail")
                or obj:IsA("Beam")
                or obj:IsA("Smoke")
                or obj:IsA("Fire")
                or obj:IsA("Sparkles")
                or obj:IsA("PointLight")
                or obj:IsA("SpotLight")
                or obj:IsA("SurfaceLight")
                or obj:IsA("Highlight")
                or obj:IsA("SelectionBox")
                or obj:IsA("SelectionSphere")
                or obj:IsA("PostEffect")
            ) and obj.Enabled or nil,
            Rate = obj:IsA("ParticleEmitter") and obj.Rate or nil,
            Lifetime = obj:IsA("ParticleEmitter") and obj.Lifetime or nil,
            Brightness = (obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight")) and obj.Brightness or nil,
            Range = (obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight")) and obj.Range or nil,
            Density = obj:IsA("Atmosphere") and obj.Density or nil,
            Haze = obj:IsA("Atmosphere") and obj.Haze or nil,
            Glare = obj:IsA("Atmosphere") and obj.Glare or nil,
            LocalTransparencyModifier = obj:IsA("BasePart") and obj.LocalTransparencyModifier or nil,
        }
    end
    local hidden = HideEffectsEnabled
    local low = LowEffectsEnabled
    pcall(function()
        if obj:IsA("BasePart") then
            obj.LocalTransparencyModifier = hidden and 1 or EffectOriginals[obj].LocalTransparencyModifier or 0
        elseif obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
            obj.Enabled = not hidden
            if low and not hidden then
                obj.Brightness = math.min((EffectOriginals[obj].Brightness or obj.Brightness) * 0.12, 0.55)
            end
        elseif obj:IsA("ParticleEmitter") then
            obj.Enabled = not hidden
            if hidden then
                pcall(function() obj:Clear() end)
            elseif low then
                obj.Rate = (EffectOriginals[obj].Rate or obj.Rate) * 0.25
            end
        elseif obj:IsA("Trail") or obj:IsA("Beam") or obj:IsA("Smoke") or obj:IsA("Fire")
            or obj:IsA("Sparkles") or obj:IsA("Highlight") or obj:IsA("SelectionBox") or obj:IsA("SelectionSphere")
            or obj:IsA("PostEffect") then
            obj.Enabled = not hidden
        elseif obj:IsA("Sky") then
            if hidden then
                obj.Parent = nil
            elseif EffectOriginals[obj].Parent then
                obj.Parent = EffectOriginals[obj].Parent
            end
        elseif obj:IsA("Atmosphere") then
            if hidden then
                obj.Density = 0
                obj.Haze = 0
                obj.Glare = 0
            elseif low then
                obj.Density = (EffectOriginals[obj].Density or obj.Density) * 0.25
                obj.Haze = (EffectOriginals[obj].Haze or obj.Haze) * 0.25
                obj.Glare = (EffectOriginals[obj].Glare or obj.Glare) * 0.25
            end
        end
    end)
end

local function refreshEffects()
    for obj,_ in pairs(EffectOriginals) do
        if obj and obj.Parent then restoreEffect(obj) else EffectOriginals[obj] = nil end
    end
    if not HideEffectsEnabled and not LowEffectsEnabled then return end
    for _,obj in ipairs(workspace:GetDescendants()) do
        applyEffectModeTo(obj)
    end
    for _,obj in ipairs(Lighting:GetDescendants()) do
        applyEffectModeTo(obj)
    end
end

if EffectConnection then EffectConnection:Disconnect() end
EffectConnection = workspace.DescendantAdded:Connect(function(obj)
    if HideEffectsEnabled or LowEffectsEnabled then
        task.defer(function() applyEffectModeTo(obj) end)
    end
end)

