LightingEffectConnection = Lighting.DescendantAdded:Connect(function(obj)
    if HideEffectsEnabled or LowEffectsEnabled then
        task.defer(function() applyEffectModeTo(obj) end)
    end
end)

local AdvancedFirstPersonEnabled = true
local AdvancedFPOriginals = setmetatable({}, {__mode = "k"})
local AdvancedFPCharacter = nil
local AdvancedFPBound = false

local function isAdvancedFPBodyPart(obj)
    if not obj:IsA("BasePart") then return false end
    if obj.Name == "Head" then return false end
    local character = AdvancedFPCharacter
    if not character or not obj:IsDescendantOf(character) then return false end
    if obj.Parent and obj.Parent:IsA("Accessory") then return false end
    return obj.Name == "Torso"
        or obj.Name == "UpperTorso"
        or obj.Name == "LowerTorso"
        or obj.Name == "Left Arm"
        or obj.Name == "Right Arm"
        or obj.Name == "Left Leg"
        or obj.Name == "Right Leg"
        or obj.Name == "LeftUpperArm"
        or obj.Name == "LeftLowerArm"
        or obj.Name == "LeftHand"
        or obj.Name == "RightUpperArm"
        or obj.Name == "RightLowerArm"
        or obj.Name == "RightHand"
        or obj.Name == "LeftUpperLeg"
        or obj.Name == "LeftLowerLeg"
        or obj.Name == "LeftFoot"
        or obj.Name == "RightUpperLeg"
        or obj.Name == "RightLowerLeg"
        or obj.Name == "RightFoot"
end

local function refreshAdvancedFPCharacter()
    local character = LocalPlayer.Character
    if character ~= AdvancedFPCharacter then
        for obj, original in pairs(AdvancedFPOriginals) do
            if obj and obj.Parent and original ~= nil then
                pcall(function() obj.LocalTransparencyModifier = original end)
            end
        end
        AdvancedFPOriginals = setmetatable({}, {__mode = "k"})
        AdvancedFPCharacter = character
    end
end

local function updateAdvancedFirstPerson()
    if not AdvancedFirstPersonEnabled then return end
    local camera = workspace.CurrentCamera
    if not camera then return end
    refreshAdvancedFPCharacter()
    local character = AdvancedFPCharacter
    if not character then return end

    local head = character:FindFirstChild("Head")
    local inFirstPerson = false
    if head then
        inFirstPerson = (camera.CFrame.Position - head.Position).Magnitude <= 1.35
    end

    for _, obj in ipairs(character:GetDescendants()) do
        if isAdvancedFPBodyPart(obj) then
            if AdvancedFPOriginals[obj] == nil then
                AdvancedFPOriginals[obj] = obj.LocalTransparencyModifier
            end
            pcall(function()
                obj.LocalTransparencyModifier = inFirstPerson and 0 or AdvancedFPOriginals[obj]
            end)
        elseif obj:IsA("BasePart") and obj.Name == "Head" then
            if AdvancedFPOriginals[obj] == nil then
                AdvancedFPOriginals[obj] = obj.LocalTransparencyModifier
            end
            pcall(function()
                obj.LocalTransparencyModifier = inFirstPerson and 1 or AdvancedFPOriginals[obj]
            end)
        elseif obj.Parent and obj.Parent:IsA("Accessory") and obj:IsA("BasePart") then
            if AdvancedFPOriginals[obj] == nil then
                AdvancedFPOriginals[obj] = obj.LocalTransparencyModifier
            end
            pcall(function()
                obj.LocalTransparencyModifier = inFirstPerson and 1 or AdvancedFPOriginals[obj]
            end)
        end
    end
end

pcall(function() RunService:UnbindFromRenderStep("BirdBrainAdvancedFirstPerson") end)
RunService:BindToRenderStep("BirdBrainAdvancedFirstPerson", Enum.RenderPriority.Camera.Value + 1, updateAdvancedFirstPerson)
AdvancedFPBound = true
LocalPlayer.CharacterAdded:Connect(function()
    AdvancedFPCharacter = nil
    AdvancedFPOriginals = setmetatable({}, {__mode = "k"})
end)

local function applyScreenEffects()
    for _,obj in ipairs(Lighting:GetChildren()) do
        if obj:IsA("PostEffect") and obj:GetAttribute("EWV5_ClientPostEffect") == true then
            pcall(function()
                obj.Enabled = ScreenEffectsEnabled and not HideEffectsEnabled
            end)
        end
    end
end

local function setStatsVisible(enabled)
    ShowStatsEnabled = enabled
    if enabled then
        if not StatsLabel then
            StatsLabel = Instance.new("TextLabel")
            StatsLabel.Name = "EmoteWheelStats"
            StatsLabel.Size = UDim2.new(0,130,0,34)
            StatsLabel.AnchorPoint = Vector2.new(1,0)
            StatsLabel.Position = UDim2.new(1,-12,0,12)
            StatsLabel.BackgroundTransparency = 0.25
            StatsLabel.BackgroundColor3 = Color3.fromRGB(8,8,8)
            StatsLabel.BorderSizePixel = 0
            StatsLabel.Font = Enum.Font.Code
            StatsLabel.TextSize = 10
            StatsLabel.TextColor3 = Color3.fromRGB(210,210,210)
            StatsLabel.TextXAlignment = Enum.TextXAlignment.Right
            StatsLabel.TextYAlignment = Enum.TextYAlignment.Center
            StatsLabel.ZIndex = 100
            StatsLabel.Parent = ScreenGui
        end
        StatsLabel.Visible = true
        if StatsConnection then StatsConnection:Disconnect() end
        local last = os.clock()
        local frames = 0
        StatsConnection = RunService.RenderStepped:Connect(function()
            if not ShowStatsEnabled or not StatsLabel then return end
            frames += 1
            local now = os.clock()
            if now-last >= 0.5 then
                local fps = math.floor(frames/(now-last)+0.5)
                frames = 0
                last = now
                local ping = 0
                pcall(function() ping = math.floor(LocalPlayer:GetNetworkPing()*1000+0.5) end)
                StatsLabel.Text = ("FPS  %d\nPING %dms"):format(fps,ping)
            end
        end)
    elseif StatsLabel then
        StatsLabel.Visible = false
        if StatsConnection then StatsConnection:Disconnect(); StatsConnection=nil end
    end
end

