local function connectScrollSFX(scrollFrame, key)
    local lastPosition = scrollFrame.CanvasPosition.Y
    scrollFrame:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
        local currentPosition = scrollFrame.CanvasPosition.Y
        if math.abs(currentPosition - lastPosition) < 0.5 then return end
        lastPosition = currentPosition
        local now = os.clock()
        if now < (UI_SFX_SCROLL_COOLDOWN[key] or 0) then return end
        UI_SFX_SCROLL_COOLDOWN[key] = now + 0.08
        PlayUISound("Scroll")
    end)
end

connectScrollSFX(SettingsScroll, "Settings")
connectScrollSFX(KBScroll, "Keybind")

