function redownloadAllAudio()
    if not (writefile and isfile and getAsset and game.HttpGet) then
        settingStatus("Executor lacks file/download APIs")
        return
    end
    ensureMusicFolder()
    RedownloadBtn.Active = false
    RedownloadBtn.Text = "REFRESHING..."
    settingStatus("Clearing music cache...")
    for _,e in ipairs(EMOTES) do
        if e.AudioUrl and e.AudioName then
            local fn=musicFileName(e.AudioName)
            if isfile(fn) and delfile then pcall(function() delfile(fn) end) end
            e.LocalAudioId=nil
        end
    end
    local total,done=0,0
    for _,e in ipairs(EMOTES) do if e.AudioUrl and e.AudioName then total+=1 end end
    for _,e in ipairs(EMOTES) do
        if e.AudioUrl and e.AudioName then
            done+=1
            SettingsStatusLabel.Text=("Refreshing %d/%d"):format(done,total)
            cacheAudioForEmote(e,true)
            task.wait()
        end
    end
    RedownloadBtn.Text="REFRESH ALL MUSIC"
    RedownloadBtn.Active=true
    settingStatus("Music cache refreshed")
end
RedownloadBtn.Activated:Connect(redownloadAllAudio)

UserInputService.InputEnded:Connect(function(input)
    if commandDragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
        commandDragging = false
        commandDragInput = nil
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if commandDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
        if commandDragStart and commandStartPosition then
            local delta = input.Position - commandDragStart
            command.Position = UDim2.new(
                commandStartPosition.X.Scale, commandStartPosition.X.Offset + delta.X,
                commandStartPosition.Y.Scale, commandStartPosition.Y.Offset + delta.Y
            )
        end
    end
    if not SettingsDragging then return end
    if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
    local row = SettingsDragging.Parent
    local track = row and row:FindFirstChild("Frame")
    if not track or not track:IsA("Frame") then return end
    local left=track.AbsolutePosition.X
    local width=math.max(track.AbsoluteSize.X,1)
    local pct=math.clamp((input.Position.X-left)/width,0,1)
    for _,slider in ipairs(SettingsSliders) do
        if slider.Row==row then
            if slider==VolumeSlider then slider.Set(pct*2)
            elseif slider==EmoteMusicVolumeSlider then slider.Set(pct)
            elseif slider==DimSlider then slider.Set(0.25+pct*0.55)
            elseif slider==ScaleSlider then slider.Set(0.75+pct*0.50)
            else
                local minV,maxV=0,1
                slider.Set(minV+pct*(maxV-minV))
            end
            break
        end
    end
end)

