function selectEmoteAtPosition(position)
    if not WheelIsOpen or PageTransitioning or SettingsOpen or KeybindPanelOpen then return end
    if not position then return end
    local idx = getSliceAtPosition(position)
    if not idx then return end
    local sd = SliceData[idx]
    if not sd or not sd.Emote then return end
    HoveredSlice = idx
    local pageEmotes = getPageEmotes(CurrentPage)
    redrawWheel(idx, pageEmotes)
    local emote = sd.Emote
    PlayUISound("EmoteClick")
    CloseWheel()
    task.delay(0.05, function()
        if WheelIsOpen == false then
            ExecEmote(emote)
        end
    end)
end
