UserInputService.InputBegan:Connect(function(input, gpe)
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    if input.KeyCode == Enum.KeyCode.Escape then
        if ListeningEmote then cancelListening() end
        if ListeningJumpStopKey then
            ListeningJumpStopKey = false
            if JumpStopKeyBtn then
                JumpStopKeyBtn.Text = "  STOP KEY    " .. tostring(ContinueEmoteStopKey):match("%.([^%.]+)$")
                JumpStopKeyBtn.TextColor3 = Color3.fromRGB(255,255,255)
            end
        end
        return
    end
    if ListeningJumpStopKey then
        if SKIP_KEYS[input.KeyCode] then return end
        ContinueEmoteStopKey = input.KeyCode
        for name, kc in pairs(KEYBINDS) do
            if kc == input.KeyCode then
                KEYBINDS[name] = nil
                local row = KeybindRows[name]
                if row and row.KeyBtn then
                    row.KeyBtn.Text = "none"
                    row.KeyBtn.TextColor3 = Color3.fromRGB(255,255,255)
                    Tween(row.KeyBtn, {BackgroundColor3 = Color3.fromRGB(16,16,16)}, 0.12)
                end
            end
        end
        SaveSettings()
        ListeningJumpStopKey = false
        if JumpStopKeyBtn then
            JumpStopKeyBtn.Text = "  STOP KEY    " .. tostring(ContinueEmoteStopKey):match("%.([^%.]+)$")
            JumpStopKeyBtn.TextColor3 = Color3.fromRGB(255,255,255)
        end
        settingStatus("Stop key set to " .. keyCodeName(ContinueEmoteStopKey))
        return
    end
    if ContinueEmoteOnJumpEnabled and IsEmoting and input.KeyCode == ContinueEmoteStopKey then
        CancelActiveEmote()
        return
    end
    if ListeningEmote then
        if SKIP_KEYS[input.KeyCode] then return end
        local emoteName = ListeningEmote
        local btn = ListeningKeyBtn
        for name, kc in pairs(KEYBINDS) do
            if kc == input.KeyCode and name ~= emoteName then
                KEYBINDS[name] = nil
                local row = KeybindRows[name]
                if row and row.KeyBtn then
                    row.KeyBtn.Text = "none"
                    row.KeyBtn.TextColor3 = Color3.fromRGB(255,255,255)
                    Tween(row.KeyBtn, {BackgroundColor3 = Color3.fromRGB(16,16,16)}, 0.12)
                end
            end
        end
        KEYBINDS[emoteName] = input.KeyCode
        SaveSettings()
        cancelListening()
        if btn and btn.Parent then
            btn.Text = "["..keyCodeName(input.KeyCode).."]"
            btn.TextColor3 = Color3.fromRGB(220,220,220)
            Tween(btn, {BackgroundColor3 = Color3.fromRGB(20,20,30)}, 0.12)
        end
        return
    end
    if gpe then return end
    if input.KeyCode == OPEN_KEY then
        if not WheelIsOpen then
            PlayUISound("WheelOpen")
            OpenWheel()
        end
        return
    end
    if not WheelIsOpen then
        for emoteName, kc in pairs(KEYBINDS) do
            if input.KeyCode == kc then
                for _, emote in ipairs(EMOTES) do
                    if emote.Name == emoteName then
                        ExecEmote(emote)
                        break
                    end
                end
                break
            end
        end
    end
end)
