local function formatNotificationEmoteName(name)
    local text = tostring(name or "Emote")
    text = text:gsub("[_%-]+", " ")
    text = text:gsub("(%l)(%u)", "%1 %2")
    text = text:gsub("(%u)(%u%l)", "%1 %2")
    text = text:gsub("%s+", " ")
    text = text:gsub("^%s+", ""):gsub("%s+$", "")
    return text ~= "" and text or "Emote"
end

ShowNotification = function(emoteName, musicOn, customSubText)
    if not NotificationsOn then return end
    PlayUISound("Notification")
    if NotifTask then
        task.cancel(NotifTask)
        NotifTask = nil
    end
    NotifTitle.Text = formatNotificationEmoteName(emoteName)
    NotifSub.Text = customSubText or (musicOn and "Music ON" or "Music OFF")
    NotifIcon.TextColor3 = Color3.fromRGB(220,220,220)
    NotifHolder.Position = NOTIF_HIDE_X
    Tween(NotifHolder, {Position = NOTIF_SHOW_X}, 0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
    NotifBar.Size = UDim2.new(1,-16,0,2)
    Tween(NotifBar, {Size = UDim2.new(0,0,0,2)}, 3, Enum.EasingStyle.Linear)
    NotifTask = task.delay(3, function()
        Tween(NotifHolder, {Position = NOTIF_HIDE_X}, 0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
        NotifTask = nil
    end)
end
