    local function styleButton(btn, compact)
        btn.AutoButtonColor = false
        btn.BackgroundColor3 = V6.Theme.Surface2
        btn.TextColor3 = V6.Theme.Text
        btn.Font = Enum.Font.SourceSansSemibold
        btn.TextSize = compact and 10 or 11
        btn.BorderSizePixel = 0
        makeCorner(btn, compact and 5 or 6)
        v6Connect(btn.MouseEnter, function()
            if btn.Parent then Tween(btn, {BackgroundColor3 = V6.Theme.Hover}, 0.08, Enum.EasingStyle.Quad) end
        end)
        v6Connect(btn.MouseLeave, function()
            if btn.Parent then Tween(btn, {BackgroundColor3 = V6.Theme.Surface2}, 0.08, Enum.EasingStyle.Quad) end
        end)
        v6Connect(btn.MouseButton1Down, function()
            if btn.Parent then Tween(btn, {BackgroundColor3 = V6.Theme.Pressed}, 0.05) end
        end)
        v6Connect(btn.MouseButton1Up, function()
            if btn.Parent then Tween(btn, {BackgroundColor3 = V6.Theme.Hover}, 0.06) end
        end)
    end

