    local function normalizeUiText(obj)
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            obj.TextColor3 = Color3.fromRGB(255,255,255)
            obj.TextStrokeTransparency = 1
            if obj:IsA("TextBox") then
                obj.PlaceholderColor3 = Color3.fromRGB(255,255,255)
            end
        end
    end

    for _, obj in ipairs(ScreenGui:GetDescendants()) do
        normalizeUiText(obj)
    end

    v6Connect(ScreenGui.DescendantAdded, function(obj)
        task.defer(function()
            if obj and obj.Parent then normalizeUiText(obj) end
        end)
    end)

    task.spawn(function()
        while ScreenGui.Parent do
            for _, obj in ipairs(ScreenGui:GetDescendants()) do
                normalizeUiText(obj)
            end
            task.wait(0.25)
        end
    end)

    local function updateScale()
        local camera = workspace.CurrentCamera
        if not camera then return end
        local vp = camera.ViewportSize
        local base = math.min(vp.X / 900, vp.Y / 650)
        local desired = math.clamp(base, 0.72, 1.18)
        if isTouch() then desired = math.min(desired, 0.96) end
        V6.State.UIScale = desired
        rootScale.Scale = desired
    end
    updateScale()
    if workspace.CurrentCamera then
        v6Connect(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"), updateScale)
    end

    local function emoteKey(e)
        return e and tostring(e.Name or "") or ""
    end

    function V6:IsFavorite(e)
        return self.State.FavoriteMap[emoteKey(e)] == true
    end

    function V6:ToggleFavorite(e)
        local key = emoteKey(e)
        if key == "" then return end
        self.State.FavoriteMap[key] = not self.State.FavoriteMap[key]
    end

    function V6:AddRecent(e)
        local key = emoteKey(e)
        if key == "" then return end
        local out = {}
        table.insert(out, e)
        for _, old in ipairs(self.State.Recent) do
            if emoteKey(old) ~= key then table.insert(out, old) end
            if #out >= self.State.MaxRecent then break end
        end
        self.State.Recent = out
    end

    local OriginalExecEmote = ExecEmote

    function V6:Play(e)
        if not e then return end
        self:AddRecent(e)
        OriginalExecEmote(e)
    end

    ExecEmote = function(e)
        V6:Play(e)
    end

