    local function consoleWrite(message, kind)
        local line = Instance.new("TextLabel")
        line.Name = "Line"
        line.Size = UDim2.new(1, -2, 0, 0)
        line.AutomaticSize = Enum.AutomaticSize.Y
        line.BackgroundTransparency = 1
        line.Font = Enum.Font.Code
        line.TextSize = 10
        line.TextColor3 = (kind == "error" and V6.Theme.Danger)
            or (kind == "success" and V6.Theme.Positive)
            or (kind == "hint" and V6.Theme.Muted)
            or V6.Theme.Text
        line.TextXAlignment = Enum.TextXAlignment.Left
        line.TextYAlignment = Enum.TextYAlignment.Top
        line.TextWrapped = true
        line.Text = tostring(message or "")
        line.ZIndex = 702
        line.Parent = consoleOutput

        local children = {}
        for _, child in ipairs(consoleOutput:GetChildren()) do
            if child:IsA("TextLabel") then
                children[#children + 1] = child
            end
        end
        if #children > 180 then
            local oldest = children[1]
            if oldest then safeDestroy(oldest) end
        end
        task.defer(function()
            pcall(function()
                consoleOutput.CanvasPosition = Vector2.new(0, math.max(0, consoleOutput.AbsoluteCanvasSize.Y))
            end)
        end)
    end

    local function updateMusicButtonState()
        if not MusicBtn or not MusicBtn.Parent then return end
        MusicBtn.Text = NoMusicEnabled and "MUSIC OFF" or "MUSIC ON"
    end

    local function normalizeCommandName(name)
        name = tostring(name or "")
        name = name:gsub("^%s+", ""):gsub("%s+$", "")
        if name:sub(1, 1) == ";" then name = name:sub(2) end
        return name
    end

    local function findEmoteByText(query)
        local q = tostring(query or ""):gsub('^%s+', ''):gsub('%s+$', '')
        q = q:gsub('^"(.*)"$', '%1'):gsub("^'(.*)'$", "%1")
        if q == "" then return nil, 0, {} end
        local lower = string.lower(q)
        local exact = nil
        local matches = {}
        for _, e in ipairs(EMOTES) do
            local n = tostring(e.Name or "")
            local ln = string.lower(n)
            if ln == lower then
                exact = e
                break
            elseif string.find(ln, lower, 1, true) then
                matches[#matches + 1] = e
            end
        end
        if exact then return exact, 1, {exact} end
        return matches[1], #matches, matches
    end

    local refreshQuickSuggestions

    local function setQuickBarVisible(open)
        open = open == true
        quickBar.Visible = open
        if open then
            quickInput.Text = ""
            quickBar.Size = UDim2.new(0, 400, 0, 34)
            quickSuggestions.Visible = false
            V6.ConsoleSuggestionIndex = 1
            task.defer(function()
                pcall(function() quickInput:CaptureFocus() end)
                pcall(function() quickInput.CursorPosition = 1 end)
                refreshQuickSuggestions()
            end)
        else
            pcall(function() quickInput:ReleaseFocus() end)
            quickInput.Text = ""
            quickSuggestions.Visible = false
            V6.ConsoleSuggestionItems = {}
            V6.ConsoleSuggestionIndex = 1
        end
    end

    local function getQuickSuggestions(raw)
        local input = normalizeCommandName(raw)
        local lower = string.lower(input)
        local suggestions = {}

        for _, cmd in ipairs(quickCommands) do
            local clean = cmd:gsub('%s+$', '')
            if lower == "" or string.find(string.lower(clean), lower, 1, true) == 1 then
                suggestions[#suggestions + 1] = cmd
            end
        end

        local playPrefix = string.match(input, "^%s*[Pp][Ll][Aa][Yy]%s+(.*)$")
        if playPrefix ~= nil then
            local q = string.lower(playPrefix)
            for _, e in ipairs(EMOTES) do
                local n = tostring(e.Name or "")
                local ln = string.lower(n)
                if q == "" or string.find(ln, q, 1, true) then
                    suggestions[#suggestions + 1] = "play " .. n
                    if #suggestions >= 12 then break end
                end
            end
        elseif lower ~= "" and not string.find(lower, "^play%s+") then
            for _, e in ipairs(EMOTES) do
                local n = tostring(e.Name or "")
                if string.find(string.lower(n), lower, 1, true) then
                    suggestions[#suggestions + 1] = "play " .. n
                    if #suggestions >= 12 then break end
                end
            end
        end
        return suggestions
    end

    refreshQuickSuggestions = function()
        for _, child in ipairs(quickSuggestions:GetChildren()) do
            if child:IsA("TextButton") then safeDestroy(child) end
        end
        local suggestions = getQuickSuggestions(quickInput.Text)
        V6.ConsoleSuggestionItems = suggestions
        V6.ConsoleSuggestionIndex = math.clamp(V6.ConsoleSuggestionIndex or 1, 1, math.max(1, #suggestions))
        quickSuggestions.Visible = #suggestions > 0 and quickInput:IsFocused() and normalizeCommandName(quickInput.Text) ~= ""
        for i, suggestion in ipairs(suggestions) do
            local b = Instance.new("TextButton")
            b.Size = UDim2.new(1, -6, 0, 25)
            b.BackgroundColor3 = i == V6.ConsoleSuggestionIndex and V6.Theme.Pressed or V6.Theme.Surface2
            b.BorderSizePixel = 0
            b.AutoButtonColor = false
            b.Text = suggestion
            b.Font = Enum.Font.Code
            b.TextSize = 9
            b.TextColor3 = V6.Theme.Text
            b.TextXAlignment = Enum.TextXAlignment.Left
            b.ZIndex = 783
            b.Parent = quickSuggestions
            local pad = Instance.new("UIPadding")
            pad.PaddingLeft = UDim.new(0, 8)
            pad.Parent = b
            local acceptSuggestion = false
            local function acceptQuickSuggestion()
                if acceptSuggestion then return end
                acceptSuggestion = true
                local accepted = tostring(suggestion or "")
                if accepted ~= "" and quickInput and quickInput.Parent then
                    quickInput.Text = accepted
                    pcall(function()
                        quickInput.CursorPosition = #accepted + 1
                        quickInput.SelectionStart = #accepted + 1
                    end)
                end
                task.defer(refreshQuickSuggestions)
                task.defer(function()
                    if quickInput and quickInput.Parent and quickBar.Visible then
                        pcall(function() quickInput:CaptureFocus() end)
                    end
                end)
            end
            v6Connect(b.InputBegan, function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                    acceptQuickSuggestion()
                end
            end)
        end
    end

    function V6:OpenConsole(autoFocus)
        if self.State.ConsoleOpen then
            if autoFocus ~= false then task.defer(function() pcall(function() consoleInput:CaptureFocus() end) end) end
            return
        end
        self.State.ConsoleOpen = true
        consoleGui.Visible = true
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local w = math.min(400, math.max(330, math.floor(vp.X * 0.38)))
        local h = math.min(280, math.max(220, math.floor(vp.Y * 0.34)))
        consoleGui.Size = UDim2.new(0, w, 0, h)
        if not consoleOutput:GetAttribute("EWV6_WelcomeShown") then
            consoleOutput:SetAttribute("EWV6_WelcomeShown", true)
            consoleWrite("Emote command console ready.", "success")
            consoleWrite("Type help for commands. Press ; while the console is open to focus its input; otherwise ; opens quick command mode.", "hint")
        end
        if autoFocus ~= false then
            task.defer(function()
                pcall(function() consoleInput:CaptureFocus() end)
            end)
        end
    end

    function V6:CloseConsole()
        self.State.ConsoleOpen = false
        consoleGui.Visible = false
        pcall(function() consoleInput:ReleaseFocus() end)
    end

    function V6:RunCommand(rawCommand, source)
        local raw = normalizeCommandName(rawCommand)
        if raw == "" then return end

        if source ~= "history" then
            local history = self.State.ConsoleHistory
            if history[#history] ~= raw then
                history[#history + 1] = raw
            end
            while #history > 80 do table.remove(history, 1) end
            self.State.ConsoleHistoryIndex = #history + 1
        end

        local verb, args = raw:match("^(%S+)%s*(.*)$")
        verb = string.lower(verb or "")
        args = args or ""

        consoleWrite("> " .. raw)

        if verb == "help" then
            consoleWrite("help                 show this guide", "hint")
            consoleWrite("status               show live emote/music/lyrics state", "hint")
            consoleWrite("play <emote name>    play an emote by name", "hint")
            consoleWrite("stop                 stop the current emote", "hint")
            consoleWrite("reset                reset your character", "hint")
            consoleWrite("default              restore all settings to default", "hint")
            consoleWrite("redownload           redownload all music", "hint")
            consoleWrite("lyrics on|off        toggle emote lyrics", "hint")
            consoleWrite("mute|unmute          toggle emote music", "hint")
            consoleWrite("volume <0-2>        set master volume", "hint")
            consoleWrite("musicvolume <0-1>   set emote music volume", "hint")
            consoleWrite("search <text>        filter the Command Center", "hint")
            consoleWrite("bar on|off|toggle     show/hide the music status bar", "hint")
                consoleWrite("clear                clear console output", "hint")
            consoleWrite("Quick mode: press ; then type a command. Tab/click accepts suggestions.", "success")
            return
        end

        if verb == "clear" then
            for _, child in ipairs(consoleOutput:GetChildren()) do
                if child:IsA("TextLabel") then safeDestroy(child) end
            end
            return
        end

        if verb == "status" then
            local emote = ActiveToken and ActiveToken.emote
            local emoteName = emote and tostring(emote.Name or "unknown") or "none"
            local music = (CurrentSound and CurrentSound.Parent and not NoMusicEnabled) and "playing" or (NoMusicEnabled and "muted" or "off")
            local lyrics = LyricsEnabled and "on" or "off"
            consoleWrite("emote  : " .. emoteName)
            consoleWrite("music  : " .. music)
            consoleWrite("lyrics : " .. lyrics)
            consoleWrite("wheel  : " .. (WheelIsOpen and "open" or "closed"))
            return
        end

        if verb == "reset" then
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hum then
                consoleWrite("Character reset failed: humanoid not found.", "error")
                return
            end
            local ok, err = pcall(function()
                if IsEmoting or ActiveToken then
                    CancelActiveEmote()
                end
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if hrp then pcall(function() hrp.Anchored = false end) end
                hum.Health = 0
            end)
            if ok then
                consoleWrite("Character reset.", "success")
            else
                consoleWrite("Reset failed: " .. tostring(err), "error")
            end
            return
        end

        if verb == "default" then
            local ok, err = pcall(function() resetSettings() end)
            if ok then
                consoleWrite("All settings restored to default.", "success")
            else
                consoleWrite("Default reset failed: " .. tostring(err), "error")
            end
            return
        end

        if verb == "redownload" then
            local ok, err = pcall(function() redownloadAllAudio() end)
            if ok then
                consoleWrite("Music redownload started.", "success")
            else
                consoleWrite("Redownload failed: " .. tostring(err), "error")
            end
            return
        end

        if verb == "play" then
            local e, count, list = findEmoteByText(args)
            if not e then
                consoleWrite("No emote matched: " .. tostring(args), "error")
                return
            end
            if count > 1 and string.lower(tostring(e.Name)) ~= string.lower(tostring(args):gsub('^%s+', ''):gsub('%s+$', '')) then
                consoleWrite("Multiple matches; using: " .. tostring(e.Name), "hint")
            end
            local ok, err = pcall(function()
                V6:Play(e)
            end)
            if ok then
                consoleWrite("Playing: " .. tostring(e.Name), "success")
            else
                consoleWrite("Play failed: " .. tostring(err), "error")
            end
            return
        end

        if verb == "stop" then
            local ok, err = pcall(function() CancelActiveEmote() end)
            if ok then
                consoleWrite("Current emote stopped.", "success")
            else
                consoleWrite("Stop failed: " .. tostring(err), "error")
            end
            return
        end

        local function parseNumberCommand(minV, maxV)
            local value = tonumber(args)
            if value == nil then
                consoleWrite("Invalid value: " .. tostring(args), "error")
                return nil
            end
            if value < minV or value > maxV then
                consoleWrite(("Value must be between %.2f and %.2f"):format(minV, maxV), "error")
                return nil
            end
            return value
        end

        if verb == "volume" then
            local value = parseNumberCommand(0, 2)
            if value ~= nil then
                VolumeSlider.Set(value)
                consoleWrite(("Master volume set to %.2f"):format(value), "success")
            end
            return
        end

        if verb == "musicvolume" then
            local value = parseNumberCommand(0, 1)
            if value ~= nil then
                EmoteMusicVolumeSlider.Set(value)
                consoleWrite(("Emote music volume set to %.2f"):format(value), "success")
            end
            return
        end

        local sliderCommands = {
            hover = HoverSFXSlider,
            buttonclick = ButtonClickSFXSlider,
            emoteclick = EmoteClickSFXSlider,
            wheelopen = WheelOpenSFXSlider,
            wheelclose = WheelCloseSFXSlider,
            scroll = ScrollSFXSlider,
            notificationvolume = NotificationSFXSlider,
            stopvolume = StopSFXSlider,
            dim = DimSlider,
            scale = ScaleSlider,
        }
        local slider = sliderCommands[verb]
        if slider then
            local minV, maxV = 0, 1
            if verb == "dim" then minV, maxV = 0.25, 0.80 end
            if verb == "scale" then minV, maxV = 0.75, 1.25 end
            local value = parseNumberCommand(minV, maxV)
            if value ~= nil then
                slider.Set(value)
                consoleWrite(("%s set to %.2f"):format(verb, value), "success")
            end
            return
        end

        local toggleCommands = {
            notifications = NotificationsToggle,
            autodownload = AutoDownloadToggle,
            stopmovement = StopMovementToggle,
            loop = LoopToggle,
            hideeffects = HideEffectsToggle,
            loweffects = LowEffectsToggle,
            screeneffects = ScreenEffectsToggle,
            performance = PerformanceToggle,
            retro = RetroToggle,
        }
        local toggle = toggleCommands[verb]
        if toggle then
            local mode = string.lower(args:gsub('^%s+', ''):gsub('%s+$', ''))
            if mode ~= "on" and mode ~= "off" then
                consoleWrite("Usage: " .. verb .. " on | " .. verb .. " off", "error")
                return
            end
            toggle.Set(mode == "on")
            consoleWrite(verb .. " " .. mode .. ".", "success")
            return
        end

        if verb == "lyrics" then
            local mode = string.lower(args:gsub('^%s+', ''):gsub('%s+$', ''))
            if mode ~= "on" and mode ~= "off" then
                consoleWrite("Usage: lyrics on | lyrics off", "error")
                return
            end
            LyricsEnabled = mode == "on"
            if not LyricsEnabled and ActiveToken then
                pcall(function() DestroyDanceAloneLyrics(ActiveToken, true) end)
            elseif LyricsEnabled and ActiveToken and ActiveToken.emote and EMOTE_LYRIC_CONFIG[ActiveToken.emote.Name] then
                pcall(function() StartEmoteLyrics(ActiveToken, ActiveToken.emote) end)
            end
            consoleWrite("Lyrics " .. mode .. ".", "success")
            return
        end

        if verb == "mute" or verb == "unmute" then
            local mute = verb == "mute"
            NoMusicEnabled = mute
            if mute then
                if CurrentSound and CurrentSound.Parent then
                    pcall(function() CurrentSound.Volume = 0 end)
                end
            else
                if CurrentSound and CurrentSound.Parent then
                    pcall(function() CurrentSound.Volume = getEmoteMusicVolume() end)
                elseif ActiveToken and ActiveToken.emote then
                    pcall(function() PlaySound(ActiveToken.emote, false) end)
                end
            end
            updateMusicButtonState()
            consoleWrite(mute and "Music muted." or "Music unmuted.", "success")
            return
        end

        if verb == "search" then
            local q = args:gsub('^%s+', ''):gsub('%s+$', '')
            V6.State.Search = q
            search.Text = q
            if not V6.State.CommandOpen then
                V6:OpenCommandCenter()
            else
                rebuildResults()
            end
            consoleWrite("Command Center search = " .. (q ~= "" and q or "<all>"), "success")
            return
        end

        if verb == "bar" or verb == "statusbar" then
            local mode = string.lower(args:gsub('^%s+', ''):gsub('%s+$', ''))
            if mode == "on" then
                CommandStatusBarEnabled = true
            elseif mode == "off" or mode == "hide" then
                CommandStatusBarEnabled = false
            elseif mode == "toggle" or mode == "" then
                CommandStatusBarEnabled = not CommandStatusBarEnabled
            else
                consoleWrite("Usage: bar on | bar off | bar toggle", "error")
                return
            end
            local active = (WheelIsOpen or IsEmoting or V6.State.Debug)
            local bar = ScreenGui:FindFirstChild("V6StatusStrip")
            if bar then bar.Visible = false end
            local now = ScreenGui:FindFirstChild("V6NowPlaying")
            if now then
                now.Visible = CommandStatusBarEnabled and active
            end
            consoleWrite("Status bar " .. (CommandStatusBarEnabled and "enabled." or "hidden."), "success")
            return
        end

        consoleWrite("Unknown command: " .. tostring(verb) .. ". Type help.", "error")
    end

    local function applyConsoleHistory(delta)
        local history = V6.State.ConsoleHistory
        if #history == 0 then return end
        local index = V6.State.ConsoleHistoryIndex or (#history + 1)
        index = math.clamp(index + delta, 1, #history + 1)
        V6.State.ConsoleHistoryIndex = index
        consoleInput.Text = history[index] or ""
        task.defer(function()
            pcall(function() consoleInput.CursorPosition = #consoleInput.Text + 1 end)
        end)
    end

    v6Connect(consoleExecute.Activated, function()
        local cmd = consoleInput.Text
        consoleInput.Text = ""
        V6:RunCommand(cmd, "console")
        task.defer(function() pcall(function() consoleInput:CaptureFocus() end) end)
    end)

    v6Connect(consoleInput.FocusLost, function(enterPressed)
        if enterPressed and V6.State.ConsoleOpen then
            local cmd = consoleInput.Text
            consoleInput.Text = ""
            V6:RunCommand(cmd, "console")
            task.defer(function() pcall(function() consoleInput:CaptureFocus() end) end)
        end
    end)

    v6Connect(consoleClose.Activated, function()
        V6:CloseConsole()
    end)

    do
        local dragging = false
        local dragStart, startPos
        v6Connect(consoleTop.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = consoleGui.Position
            end
        end)
        v6Connect(UserInputService.InputChanged, function(input)
            if not dragging then return end
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                local delta = input.Position - dragStart
                consoleGui.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end)
        v6Connect(UserInputService.InputEnded, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end)
    end

    local function getConsoleSuggestions(raw)
        local input = normalizeCommandName(raw)
        local lower = string.lower(input)
        local out = {}
        for _, cmd in ipairs(quickCommands) do
            local clean = cmd:gsub('%s+$', '')
            if lower == "" or string.find(string.lower(clean), lower, 1, true) == 1 then
                out[#out + 1] = cmd
            end
        end
        local playPrefix = string.match(input, "^[Pp][Ll][Aa][Yy]%s+(.*)$")
        if playPrefix ~= nil then
            local q = string.lower(playPrefix)
            for _, e in ipairs(EMOTES) do
                local n = tostring(e.Name or "")
                if q == "" or string.find(string.lower(n), q, 1, true) then
                    out[#out + 1] = "play " .. n
                    if #out >= 14 then break end
                end
            end
        end
        return out
    end

    local function refreshConsoleSuggestions()
        for _, child in ipairs(consoleSuggestions:GetChildren()) do
            if child:IsA("TextButton") then safeDestroy(child) end
        end
        if not V6.State.ConsoleOpen or not consoleInput:IsFocused() then
            consoleSuggestions.Visible = false
            return
        end
        local suggestions = getConsoleSuggestions(consoleInput.Text)
        V6.ConsoleSuggestionItems = suggestions
        V6.ConsoleSuggestionIndex = math.clamp(V6.ConsoleSuggestionIndex or 1, 1, math.max(1, #suggestions))
        consoleSuggestions.Visible = #suggestions > 0 and normalizeCommandName(consoleInput.Text) ~= ""
        for i, suggestion in ipairs(suggestions) do
            local b = Instance.new("TextButton")
            b.Size = UDim2.new(1, -4, 0, 22)
            b.BackgroundColor3 = i == V6.ConsoleSuggestionIndex and V6.Theme.Pressed or V6.Theme.Surface2
            b.BorderSizePixel = 0
            b.AutoButtonColor = false
            b.Text = suggestion
            b.Font = Enum.Font.Code
            b.TextSize = 9
            b.TextColor3 = V6.Theme.Text
            b.TextXAlignment = Enum.TextXAlignment.Left
            b.ZIndex = 705
            b.Parent = consoleSuggestions
            local pad = Instance.new("UIPadding")
            pad.PaddingLeft = UDim.new(0, 7)
            pad.Parent = b
            local acceptSuggestion = false
            local function acceptConsoleSuggestion()
                if acceptSuggestion then return end
                acceptSuggestion = true
                local accepted = tostring(suggestion or "")
                if accepted ~= "" and consoleInput and consoleInput.Parent then
                    consoleInput.Text = accepted
                    pcall(function()
                        consoleInput.CursorPosition = #accepted + 1
                        consoleInput.SelectionStart = #accepted + 1
                    end)
                end
                task.defer(refreshConsoleSuggestions)
                task.defer(function()
                    if consoleInput and consoleInput.Parent and V6.State.ConsoleOpen then
                        pcall(function() consoleInput:CaptureFocus() end)
                    end
                end)
            end
            v6Connect(b.InputBegan, function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                    acceptConsoleSuggestion()
                end
            end)
        end
    end

    v6Connect(consoleInput:GetPropertyChangedSignal("Text"), function()
        if V6.State.ConsoleOpen then refreshConsoleSuggestions() end
    end)
    v6Connect(consoleInput.Focused, refreshConsoleSuggestions)
    v6Connect(consoleInput.FocusLost, function()
        task.defer(refreshConsoleSuggestions)
    end)

    v6Connect(quickInput:GetPropertyChangedSignal("Text"), function()
        if quickInput.Text:sub(1, 1) == ";" then
            quickInput.Text = quickInput.Text:sub(2)
            quickInput.CursorPosition = #quickInput.Text + 1
        end
        refreshQuickSuggestions()
    end)
    v6Connect(quickInput.Focused, function()
        refreshQuickSuggestions()
    end)
    v6Connect(quickInput.FocusLost, function(enterPressed)
        if enterPressed and quickBar.Visible then
            local cmd = quickInput.Text
            setQuickBarVisible(false)
            if cmd ~= "" then V6:RunCommand(cmd, "quick") end
        end
    end)

    v6Connect(UserInputService.InputBegan, function(input, gpe)
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

        local focusedTextBox = nil
        pcall(function() focusedTextBox = UserInputService:GetFocusedTextBox() end)

        if focusedTextBox and focusedTextBox ~= consoleInput and focusedTextBox ~= quickInput then
            return
        end

        if V6.State.ConsoleOpen then
            if input.KeyCode == Enum.KeyCode.Semicolon and focusedTextBox ~= consoleInput then
                if not gpe then
                    task.defer(function()
                        if V6.State.ConsoleOpen and not UserInputService:GetFocusedTextBox() then
                            pcall(function() consoleInput:CaptureFocus() end)
                            pcall(function() consoleInput.CursorPosition = #consoleInput.Text + 1 end)
                        end
                    end)
                end
                return
            end

            if focusedTextBox == consoleInput and input.KeyCode == Enum.KeyCode.Tab then
                local liveSuggestions = getConsoleSuggestions(consoleInput.Text)
                V6.ConsoleSuggestionItems = liveSuggestions
                local index = math.clamp(V6.ConsoleSuggestionIndex or 1, 1, math.max(1, #liveSuggestions))
                local selected = liveSuggestions[index]
                if selected then
                    local accepted = tostring(selected)
                    consoleInput.Text = accepted
                    task.defer(function()
                        if consoleInput and consoleInput.Parent then
                            pcall(function()
                                consoleInput.CursorPosition = #accepted + 1
                                consoleInput.SelectionStart = #accepted + 1
                            end)
                        end
                    end)
                    task.defer(refreshConsoleSuggestions)
                end
                return
            end

            if gpe then return end

            if input.KeyCode == Enum.KeyCode.Escape then
                V6:CloseConsole()
                return
            end

            if focusedTextBox == consoleInput then
                local suggestions = V6.ConsoleSuggestionItems or {}
                if input.KeyCode == Enum.KeyCode.Up then
                    if #suggestions > 0 then
                        V6.ConsoleSuggestionIndex = math.max(1, (V6.ConsoleSuggestionIndex or 1) - 1)
                        refreshConsoleSuggestions()
                    else
                        applyConsoleHistory(-1)
                    end
                    return
                elseif input.KeyCode == Enum.KeyCode.Down then
                    if #suggestions > 0 then
                        V6.ConsoleSuggestionIndex = math.min(#suggestions, (V6.ConsoleSuggestionIndex or 1) + 1)
                        refreshConsoleSuggestions()
                    else
                        applyConsoleHistory(1)
                    end
                    return
                end
            end
        end

        if quickBar.Visible then
            if input.KeyCode == Enum.KeyCode.Semicolon then
                if focusedTextBox == nil or focusedTextBox == quickInput then
                    setQuickBarVisible(false)
                end
                return
            end

            if focusedTextBox ~= quickInput then return end

            if input.KeyCode == Enum.KeyCode.Tab then
                local liveSuggestions = getQuickSuggestions(quickInput.Text)
                V6.ConsoleSuggestionItems = liveSuggestions
                local index = math.clamp(V6.ConsoleSuggestionIndex or 1, 1, math.max(1, #liveSuggestions))
                local selected = liveSuggestions[index]
                if selected then
                    local accepted = tostring(selected)
                    quickInput.Text = accepted
                    task.defer(function()
                        if quickInput and quickInput.Parent then
                            pcall(function()
                                quickInput.CursorPosition = #accepted + 1
                                quickInput.SelectionStart = #accepted + 1
                            end)
                        end
                    end)
                    task.defer(refreshQuickSuggestions)
                end
                return
            end

            if gpe then return end
            if input.KeyCode == Enum.KeyCode.Escape then
                setQuickBarVisible(false)
                return
            elseif input.KeyCode == Enum.KeyCode.Up then
                local count = #(V6.ConsoleSuggestionItems or {})
                if count > 0 then
                    V6.ConsoleSuggestionIndex = math.max(1, (V6.ConsoleSuggestionIndex or 1) - 1)
                    refreshQuickSuggestions()
                end
                return
            elseif input.KeyCode == Enum.KeyCode.Down then
                local count = #(V6.ConsoleSuggestionItems or {})
                if count > 0 then
                    V6.ConsoleSuggestionIndex = math.min(count, (V6.ConsoleSuggestionIndex or 1) + 1)
                    refreshQuickSuggestions()
                end
                return
            end
        end

        if not gpe and not V6.State.ConsoleOpen and not quickBar.Visible then
            local textboxFocused = focusedTextBox ~= nil
            local ctrl = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
            if input.KeyCode == Enum.KeyCode.C and ctrl and not textboxFocused then
                V6:OpenConsole(true)
                return
            end
            if not textboxFocused and input.KeyCode == Enum.KeyCode.Semicolon then
                setQuickBarVisible(true)
                return
            end
        end
    end)

    v6Connect(consoleBtn.Activated, function()
        if controlsOpen then setControlsOpen(false) end
        V6:OpenConsole(true)
    end)

    local function setMode(mode)
        V6.State.CommandMode = mode
        for name, b in pairs(modeButtons) do
            b.BackgroundColor3 = name == mode and V6.Theme.Pressed or V6.Theme.Surface2
        end
    end

    local function matches(e)
        local q = string.lower(V6.State.Search or "")
        if q == "" then return true end
        local n = string.lower(tostring(e.Name or ""))
        local category = e.DirectAnimation and "reanimation" or "cframe animations"
        return string.find(n, q, 1, true) ~= nil or string.find(category, q, 1, true) ~= nil
    end

    local function resultSource()
        local out = {}
        if V6.State.CommandMode == "FAVORITES" then
            for _, e in ipairs(EMOTES) do if V6:IsFavorite(e) then table.insert(out, e) end end
        elseif V6.State.CommandMode == "RECENT" then
            for _, e in ipairs(V6.State.Recent) do table.insert(out, e) end
        else
            for _, e in ipairs(EMOTES) do table.insert(out, e) end
        end
        return out
    end

    local function rebuildResults()
        V6.CommandSelection = 1
        for _, child in ipairs(list:GetChildren()) do
            if child:IsA("GuiObject") and child ~= layout and child ~= padding then
                safeDestroy(child)
            end
        end

        local shown = 0
        for _, e in ipairs(resultSource()) do
            if matches(e) then
                shown += 1
                if shown > 80 then break end

                local row = Instance.new("Frame")
                row.Size = UDim2.new(1, -4, 0, 42)
                row.BackgroundColor3 = V6.Theme.Surface
                row.BorderSizePixel = 0
                row.Parent = list
                makeCorner(row, 4)

                local name = Instance.new("TextLabel")
                name.Size = UDim2.new(1, -108, 0, 17)
                name.Position = UDim2.new(0, 11, 0, 5)
                name.BackgroundTransparency = 1
                name.Text = tostring(e.Name or "Unnamed") .. " - " .. (e.DirectAnimation and "Reanimation" or "CFrame")
                name.Font = Enum.Font.SourceSansSemibold
                name.TextSize = 11
                name.TextColor3 = V6.Theme.Text
                name.TextXAlignment = Enum.TextXAlignment.Left
                name.TextTruncate = Enum.TextTruncate.AtEnd
                name.Parent = row

                local meta = Instance.new("TextLabel")
                meta.Visible = false
                meta.BackgroundTransparency = 1
                meta.Parent = row

                local fav = Instance.new("TextButton")
                fav.Size = UDim2.new(0, 34, 0, 28)
                fav.Position = UDim2.new(1, -96, 0, 7)
                fav.BackgroundColor3 = V6.Theme.Surface2
                fav.Text = V6:IsFavorite(e) and utf8.char(9733) or utf8.char(9734)
                fav.TextSize = 9
                fav.Font = Enum.Font.SourceSansSemibold
                fav.TextColor3 = V6.Theme.Text
                fav.BorderSizePixel = 0
                fav.AutoButtonColor = false
                fav.Parent = row
                makeCorner(fav, 5)

                local play = Instance.new("TextButton")
                play.Size = UDim2.new(0, 56, 0, 28)
                play.Position = UDim2.new(1, -58, 0, 7)
                play.BackgroundColor3 = V6.Theme.Surface2
                play.Text = "PLAY"
                play.TextSize = 10
                play.Font = Enum.Font.SourceSansSemibold
                play.TextColor3 = V6.Theme.Text
                play.BorderSizePixel = 0
                play.AutoButtonColor = false
                play.Parent = row
                makeCorner(play, 5)

                v6Connect(fav.Activated, function()
                    V6:ToggleFavorite(e)
                    fav.Text = V6:IsFavorite(e) and utf8.char(9733) or utf8.char(9734)
                    status.Text = ""
                end)
                v6Connect(play.Activated, function()
                    V6:Play(e)
                    status.Text = ""
                    V6:CloseCommandCenter()
                    if WheelIsOpen then
                        task.delay(0.05, function()
                            if WheelIsOpen then CloseWheel() end
                        end)
                    end
                end)
            end
        end
        status.Text = ""
    end

    local function IsV6Mobile()
        local cam = workspace.CurrentCamera
        if not cam then return UserInputService.TouchEnabled end
        return UserInputService.TouchEnabled or cam.ViewportSize.X <= 760
    end

    local function GetV6CommandOpenSize()
        local cam = workspace.CurrentCamera
        if IsV6Mobile() and cam then
            local vp = cam.ViewportSize
            local shortSide = math.min(vp.X, vp.Y)
            local longSide = math.max(vp.X, vp.Y)

            local w = math.clamp(math.floor(shortSide * 0.58), 360, 500)
            local h = math.clamp(math.floor(longSide * 0.78), 540, 760)
            w = math.min(w, math.floor(vp.X * 0.68))
            h = math.min(h, math.floor(vp.Y * 0.86))

            return UDim2.new(0, math.max(360, w), 0, math.max(440, h))
        end
        return UDim2.new(0, 430, 0, 500)
    end

    function V6:OpenCommandCenter()
        if self.State.CommandOpen then return end
        self.State.CommandOpen = true
        command.Visible = true
        local target = GetV6CommandOpenSize()
        command.BackgroundTransparency = 1
        if IsV6Mobile() then
            command.Size = UDim2.new(0, math.max(320, math.floor(target.X.Offset * 0.94)), 0, math.max(400, math.floor(target.Y.Offset * 0.94)))
        else
            command.Size = UDim2.new(0, 400, 0, 440)
        end
        Tween(command, {Size = target, BackgroundTransparency = 0.02}, 0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
        rebuildResults()
        if not self.State.ConsoleOpen then
            task.defer(function() pcall(function() search:CaptureFocus() end) end)
        end
    end

    function V6:CloseCommandCenter()
        if not self.State.CommandOpen then return end
        self.State.CommandOpen = false
        if controlsPanel and controlsPanel.Parent then
            controlsPanel.Visible = false
        end
        if KeybindPanelOpen then
            closeKeybindPanel()
        end
        local target = IsV6Mobile() and UDim2.new(0, 300, 0, 360) or UDim2.new(0, 400, 0, 440)
        Tween(command, {Size = target, BackgroundTransparency = 1}, 0.13, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
        task.delay(0.14, function() if not V6.State.CommandOpen then command.Visible = false end end)
    end

    v6Connect(close.Activated, function() V6:CloseCommandCenter() end)
    v6Connect(search:GetPropertyChangedSignal("Text"), function()
        V6.State.Search = search.Text or ""
        rebuildResults()
    end)
    for mode, b in pairs(modeButtons) do
        v6Connect(b.Activated, function()
            setMode(mode)
            rebuildResults()
        end)
    end

    do
        local dragging = false
        local dragStart, startPos
        local function beginDrag(input)
            dragging = true
            dragStart = input.Position
            startPos = command.Position
        end
        local function updateDrag(input)
            if not dragging then return end
            local delta = input.Position - dragStart
            command.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
        v6Connect(top.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                beginDrag(input)
            end
        end)
        v6Connect(UserInputService.InputChanged, function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then updateDrag(input) end
        end)
        v6Connect(UserInputService.InputEnded, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
        end)
    end

    local commandButton = Instance.new("TextButton")
    commandButton.Name = "V6CommandButton"
    commandButton.Size = UDim2.new(0, 116, 0, 24)
    commandButton.Position = UDim2.new(0, 180, 0, 3)
    commandButton.BackgroundColor3 = V6.Theme.Surface2
    commandButton.Text = "COMMAND"
    commandButton.TextColor3 = V6.Theme.Text
    commandButton.Font = Enum.Font.GothamBold
    commandButton.TextSize = 9
    commandButton.BorderSizePixel = 0
    commandButton.AutoButtonColor = false
    commandButton.ZIndex = 12
    commandButton.Parent = TopHolder
    makeCorner(commandButton, 6)
    v6Connect(commandButton.Activated, function()
        if WheelIsOpen then CloseWheel() end
        if SettingsOpen then closeSettingsPanel() end
        if KeybindPanelOpen then closeKeybindPanel() end
        if V6.State.CommandOpen then V6:CloseCommandCenter() else V6:OpenCommandCenter() end
    end)
    v6Connect(commandButton.MouseEnter, function() Tween(commandButton, {BackgroundColor3 = V6.Theme.Hover}, 0.1) end)
    v6Connect(commandButton.MouseLeave, function() Tween(commandButton, {BackgroundColor3 = V6.Theme.Surface2}, 0.1) end)

    local statusStrip = Instance.new("Frame")
    statusStrip.Name = "V6StatusStrip"
    statusStrip.AnchorPoint = Vector2.new(0.5, 1)
    statusStrip.Position = UDim2.new(0.5, 0, 1, -28)
    statusStrip.Size = UDim2.new(0, 330, 0, 24)
    statusStrip.BackgroundColor3 = V6.Theme.Background
    statusStrip.BackgroundTransparency = 0.08
    statusStrip.BorderSizePixel = 0
    statusStrip.ZIndex = 18
    statusStrip.Visible = false
    statusStrip.Parent = ScreenGui
    makeCorner(statusStrip, 5)
    makeStroke(statusStrip, V6.Theme.Accent, 0.84, 1)

    local statusText = Instance.new("TextLabel")
    statusText.Size = UDim2.new(1, -18, 1, 0)
    statusText.Position = UDim2.new(0, 9, 0, 0)
    statusText.BackgroundTransparency = 1
    statusText.Text = "READY"
    statusText.Font = Enum.Font.SourceSansSemibold
    statusText.TextSize = 10
    statusText.TextColor3 = Color3.fromRGB(255,255,255)
    statusText.TextXAlignment = Enum.TextXAlignment.Center
    statusText.Parent = statusStrip

    local function refreshStatus()
        if not statusStrip.Parent then return end
        local parts = {}
        table.insert(parts, V6.State.Device)
        table.insert(parts, WheelIsOpen and "WHEEL OPEN" or "READY")
        if IsEmoting and ActiveToken and ActiveToken.emote then
            table.insert(parts, tostring(ActiveToken.emote.Name))
        end
        if CurrentSound and CurrentSound.Parent and not NoMusicEnabled then
            local pos = math.max(0, CurrentSound.TimePosition or 0)
            local len = math.max(0, CurrentSound.TimeLength or 0)
            if len > 0 then
                table.insert(parts, string.format("%d:%02d / %d:%02d", math.floor(pos / 60), math.floor(pos % 60), math.floor(len / 60), math.floor(len % 60)))
            end
        end
        statusText.Text = table.concat(parts, "    ")
    end

    task.spawn(function()
        while statusStrip.Parent do
            if CommandStatusBarEnabled and (WheelIsOpen or IsEmoting or V6.State.Debug) then
                statusStrip.Visible = true
                refreshStatus()
            else
                statusStrip.Visible = false
            end
            task.wait(0.12)
        end
    end)

    v6Connect(UserInputService.InputBegan, function(input, gpe)
        if gpe then return end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        local ctrlDown = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
        if input.KeyCode == Enum.KeyCode.K and ctrlDown then
            if V6.State.CommandOpen then V6:CloseCommandCenter() else V6:OpenCommandCenter() end
            return
        end
        if input.KeyCode == Enum.KeyCode.F and UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
            if V6.State.CommandOpen then
                setMode("FAVORITES")
                rebuildResults()
            end
        elseif input.KeyCode == Enum.KeyCode.R and UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
            if V6.State.CommandOpen then
                setMode("RECENT")
                rebuildResults()
            end
        elseif input.KeyCode == Enum.KeyCode.Escape and V6.State.CommandOpen and not V6.State.ConsoleOpen then
            V6:CloseCommandCenter()
        end
    end)

    local oldOpenWheel = OpenWheel
    local oldCloseWheel = CloseWheel
    OpenWheel = function(...)
        if V6.State.CommandOpen then V6:CloseCommandCenter() end
        oldOpenWheel(...)
        refreshStatus()
    end
    CloseWheel = function(...)
        oldCloseWheel(...)
        refreshStatus()
    end

    local oldShowNotification = ShowNotification
    ShowNotification = function(emoteName, musicOn, customSubText)
        if oldShowNotification then oldShowNotification(emoteName, musicOn, customSubText) end
        refreshStatus()
    end

    local diag = Instance.new("TextLabel")
    diag.Name = "V6Diagnostics"
    diag.AnchorPoint = Vector2.new(0, 1)
    diag.Position = UDim2.new(0, 12, 1, -12)
    diag.Size = UDim2.new(0, 250, 0, 66)
    diag.BackgroundColor3 = V6.Theme.Background
    diag.BackgroundTransparency = 0.10
    diag.BorderSizePixel = 0
    diag.Visible = false
    diag.ZIndex = 220
    diag.TextXAlignment = Enum.TextXAlignment.Left
    diag.TextYAlignment = Enum.TextYAlignment.Top
    diag.Font = Enum.Font.Code
    diag.TextSize = 9
    diag.TextColor3 = V6.Theme.Muted
    diag.Text = ""
    diag.Parent = ScreenGui
    makeCorner(diag, 10)
    makeStroke(diag, V6.Theme.Accent, 0.85, 1)
    local diagPad = Instance.new("UIPadding")
    diagPad.PaddingTop = UDim.new(0, 8)
    diagPad.PaddingLeft = UDim.new(0, 8)
    diagPad.Parent = diag

    local function refreshDiag()
        local cacheCount = 0
        for _ in pairs(ScriptCache or {}) do cacheCount += 1 end
        local playerCount = #Players:GetPlayers()
        local recentCount = #V6.State.Recent
        diag.Text = table.concat({
            "EW V6  " .. V6.Version,
            "Device: " .. V6.State.Device .. "   Scale: " .. string.format("%.2f", V6.State.UIScale),
            "Players: " .. playerCount .. "   Emotes: " .. tostring(#EMOTES),
            "Cached scripts: " .. cacheCount .. "   Recents: " .. recentCount,
            "Wheel: " .. tostring(WheelIsOpen) .. "   Emoting: " .. tostring(IsEmoting),
        }, "\n")
    end

    v6Connect(UserInputService.InputBegan, function(input, gpe)
        if gpe then return end
        if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.D and UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) and UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
            V6.State.Debug = not V6.State.Debug
            diag.Visible = V6.State.Debug
            if V6.State.Debug then
                refreshDiag()
                statusStrip.Visible = CommandStatusBarEnabled
                statusText.Text = "DEBUG MODE    Ctrl+Shift+D to close"
            end
        end
    end)

    task.spawn(function()
        while diag.Parent do
            if V6.State.Debug then refreshDiag() end
            task.wait(0.8)
        end
    end)

    task.delay(0.1, function()
        statusText.Text = "READY    " .. V6.State.Device .. "    " .. tostring(#EMOTES) .. " EMOTES"
    end)
end

do
    local HttpService = game:GetService("HttpService")
    local V6 = _G.EW_V6
    if not V6 then
        warn("[EW V6.5] Base V6 layer missing; skipping expansion layer.")
    else

    V6.Version = "6.6.0"

    V6.ProfileFile = "ewv6_profile.json"
    V6.Profile = {
        Favorites = {},
        Recents = {},
        Theme = "MONO",
        ScaleOverride = 1,
        ReducedMotion = false,
        Performance = false,
    }

    local function loadProfile()
        if not (readfile and isfile) then return end
        local ok, raw = pcall(function()
            if not isfile(V6.ProfileFile) then return nil end
            return readfile(V6.ProfileFile)
        end)
        if not ok or type(raw) ~= "string" or #raw == 0 then return end
        local okDecode, data = pcall(function() return HttpService:JSONDecode(raw) end)
        if not okDecode or type(data) ~= "table" then return end
        for k, v in pairs(data) do
            if V6.Profile[k] ~= nil then V6.Profile[k] = v end
        end
    end

    local function saveProfile()
        if not writefile then return end
        pcall(function()
            writefile(V6.ProfileFile, HttpService:JSONEncode(V6.Profile))
        end)
    end

    V6._saveProfile = saveProfile

    loadProfile()
    V6.State.FavoriteMap = V6.Profile.Favorites or {}

    do
        local rebuilt = {}
        if type(V6.Profile.Recents) == "table" then
            for _, name in ipairs(V6.Profile.Recents) do
                for _, e in ipairs(EMOTES) do
                    if e.Name == name then table.insert(rebuilt, e); break end
                end
                if #rebuilt >= V6.State.MaxRecent then break end
            end
        end
        V6.State.Recent = rebuilt
    end

    local oldToggleFavorite = V6.ToggleFavorite
    V6.ToggleFavorite = function(self, e)
        oldToggleFavorite(self, e)
        self.Profile.Favorites = self.State.FavoriteMap
        saveProfile()
    end

    local oldAddRecent = V6.AddRecent
    V6.AddRecent = function(self, e)
        oldAddRecent(self, e)
        local names = {}
        for _, item in ipairs(self.State.Recent) do names[#names+1] = item.Name end
        self.Profile.Recents = names
        saveProfile()
    end

    local toastHolder = Instance.new("Frame")
    toastHolder.Name = "V6ToastStack"
    toastHolder.AnchorPoint = Vector2.new(1, 0)
    toastHolder.Position = UDim2.new(1, -18, 0, 58)
    toastHolder.Size = UDim2.new(0, 310, 0, 0)
    toastHolder.AutomaticSize = Enum.AutomaticSize.Y
    toastHolder.BackgroundTransparency = 1
    toastHolder.BorderSizePixel = 0
    toastHolder.ZIndex = 400
    toastHolder.Parent = ScreenGui
    local toastLayout = Instance.new("UIListLayout")
    toastLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
    toastLayout.VerticalAlignment = Enum.VerticalAlignment.Top
    toastLayout.Padding = UDim.new(0, 7)
    toastLayout.Parent = toastHolder

    local function formatToastText(value)
        if value == nil then return "" end
        local text = tostring(value)
        text = text:gsub("([a-z0-9])([A-Z])", "%1 %2")
        text = text:gsub("([A-Z]+)([A-Z][a-z])", "%1 %2")
        text = text:gsub("[_%-]+", " ")
        text = text:gsub("%s+", " ")
        return text
    end

    function V6:Toast(titleText, subText, kind)
        local toast = Instance.new("Frame")
        toast.Size = UDim2.new(1, 0, 0, 62)
        toast.BackgroundColor3 = self.Theme.Surface
        toast.BackgroundTransparency = 1
        toast.BorderSizePixel = 0
        toast.ZIndex = 401
        toast.Parent = toastHolder
        local c = Instance.new("UICorner", toast); c.CornerRadius = UDim.new(0, 12)
        makeStroke(toast, self.Theme.Accent, 0.78, 1)

        local accent = Instance.new("Frame")
        accent.Size = UDim2.new(0, 3, 0.55, 0)
        accent.Position = UDim2.new(0, 0, 0.225, 0)
        accent.BackgroundColor3 = kind == "WARN" and self.Theme.Warning or (kind == "ERROR" and self.Theme.Danger or self.Theme.Accent)
        accent.BorderSizePixel = 0
        accent.ZIndex = 402
        accent.Parent = toast
        Instance.new("UICorner", accent).CornerRadius = UDim.new(1, 0)

        local a = Instance.new("TextLabel")
        a.Size = UDim2.new(1, -44, 0, 22); a.Position = UDim2.new(0, 14, 0, 8)
        a.BackgroundTransparency = 1; a.Text = formatToastText(titleText ~= nil and titleText or "Notification")
        a.Font = Enum.Font.GothamBold; a.TextSize = 10; a.TextColor3 = self.Theme.Text
        a.TextXAlignment = Enum.TextXAlignment.Left; a.ZIndex = 402; a.Parent = toast
        local b = Instance.new("TextLabel")
        b.Size = UDim2.new(1, -44, 0, 18); b.Position = UDim2.new(0, 14, 0, 31)
        b.BackgroundTransparency = 1; b.Text = formatToastText(subText ~= nil and subText or "")
        b.Font = Enum.Font.Gotham; b.TextSize = 8; b.TextColor3 = self.Theme.Muted
        b.TextXAlignment = Enum.TextXAlignment.Left; b.TextTruncate = Enum.TextTruncate.AtEnd; b.ZIndex = 402; b.Parent = toast

        Tween(toast, {BackgroundTransparency = 0.04}, 0.18, Enum.EasingStyle.Quart)
        task.delay(2.6, function()
            if toast.Parent then
                Tween(toast, {BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0)}, 0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
                task.delay(0.2, function() if toast.Parent then toast:Destroy() end end)
            end
        end)
    end

    local oldCommandInput = nil
    V6.CommandSelection = 1
    V6.CommandResults = {}

    local function collectCommandResults()
        local q = string.lower(V6.State.Search or "")
        local source = {}
        if V6.State.CommandMode == "FAVORITES" then
            for _, e in ipairs(EMOTES) do if V6:IsFavorite(e) then source[#source+1] = e end end
        elseif V6.State.CommandMode == "RECENT" then
            for _, e in ipairs(V6.State.Recent) do source[#source+1] = e end
        else
            for _, e in ipairs(EMOTES) do source[#source+1] = e end
        end
        local out = {}
        for _, e in ipairs(source) do
            local n = string.lower(tostring(e.Name or ""))
            if q == "" or string.find(n, q, 1, true) then out[#out+1] = e end
            if #out >= 80 then break end
        end
        return out
    end


    local lyricsCard = Instance.new("Frame")
    lyricsCard.Name = "V6LyricsOverlay"
    lyricsCard.AnchorPoint = Vector2.new(0.5, 1)
    lyricsCard.Position = UDim2.new(0.5, 0, 1, -156)
    lyricsCard.Size = UDim2.new(0, 620, 0, 76)
    lyricsCard.BackgroundTransparency = 1
    lyricsCard.Visible = false
    lyricsCard.ZIndex = 340
    lyricsCard.Parent = ScreenGui

    local lyricCurrent = Instance.new("TextLabel")
    lyricCurrent.Size = UDim2.new(1, -20, 0, 34); lyricCurrent.Position = UDim2.new(0, 10, 0, 4)
    lyricCurrent.BackgroundTransparency = 1; lyricCurrent.Font = Enum.Font.GothamBold; lyricCurrent.TextSize = 20
    lyricCurrent.TextColor3 = V6.Theme.Text; lyricCurrent.TextXAlignment = Enum.TextXAlignment.Center
    lyricCurrent.TextTruncate = Enum.TextTruncate.AtEnd; lyricCurrent.ZIndex = 341; lyricCurrent.Parent = lyricsCard
    local lyricNext = Instance.new("TextLabel")
    lyricNext.Size = UDim2.new(1, -20, 0, 22); lyricNext.Position = UDim2.new(0, 10, 0, 42)
    lyricNext.BackgroundTransparency = 1; lyricNext.Font = Enum.Font.Gotham; lyricNext.TextSize = 10
    lyricNext.TextColor3 = V6.Theme.Muted; lyricNext.TextTransparency = 0.15; lyricNext.TextXAlignment = Enum.TextXAlignment.Center
    lyricNext.TextTruncate = Enum.TextTruncate.AtEnd; lyricNext.ZIndex = 341; lyricNext.Parent = lyricsCard

    task.spawn(function()
        while lyricsCard.Parent do
            local active = IsEmoting and not (V6.Profile and V6.Profile.ReducedMotion)
            lyricsCard.Visible = active and false or false
            task.wait(0.5)
        end
    end)

    local advanced = Instance.new("Frame")
    advanced.Name = "V6AdvancedStrip"
    advanced.Size = UDim2.new(0, 1, 0, 1)
    advanced.Position = UDim2.new(0, 0, 1, 0)
    advanced.BackgroundTransparency = 1
    advanced.Visible = false
    advanced.Parent = command

    local commandScale
    if commandGui and commandGui:IsA("GuiObject") then
        commandScale = commandGui:FindFirstChild("V6MobileScale") or Instance.new("UIScale")
        commandScale.Name = "V6MobileScale"
        commandScale.Parent = commandGui
    else
        commandScale = Instance.new("UIScale")
    end

    local settingsScale
    if SettingsPanel and SettingsPanel:IsA("GuiObject") then
        settingsScale = SettingsPanel:FindFirstChild("V6MobileScale") or Instance.new("UIScale")
        settingsScale.Name = "V6MobileScale"
        settingsScale.Parent = SettingsPanel
    else
        settingsScale = Instance.new("UIScale")
    end

    local function updateCommandResponsive()
        local cam = workspace.CurrentCamera
        if not cam then return end
        local vp = cam.ViewportSize
        local mobile = UserInputService.TouchEnabled or vp.X <= 760

        if mobile then
            local shortSide = math.min(vp.X, vp.Y)
            local longSide = math.max(vp.X, vp.Y)

            local commandW = math.clamp(math.floor(shortSide * 0.64), 430, 590)
            local commandH = math.clamp(math.floor(longSide * 0.78), 540, 760)
            commandW = math.min(commandW, math.floor(vp.X * 0.72))
            commandH = math.min(commandH, math.floor(vp.Y * 0.86))
            if commandGui then commandGui.Size = UDim2.new(0, math.max(360, commandW), 0, math.max(440, commandH)) end
            commandScale.Scale = 1
            if controlsBtn then controlsBtn.Size = UDim2.new(0, 70, 1, 0) end
            if keysBtn then keysBtn.Size = UDim2.new(0, 70, 1, 0) end
            if diagBtn then diagBtn.Size = UDim2.new(0, 80, 1, 0) end
            if consoleBtn then consoleBtn.Size = UDim2.new(0, 58, 1, 0) end
            if CommandSettingsBtn then CommandSettingsBtn.Size = UDim2.new(0, 58, 1, 0) end

            local settingsW = math.clamp(math.floor(shortSide * 0.54), 360, 500)
            local settingsH = math.clamp(math.floor(longSide * 0.70), 500, 680)
            settingsW = math.min(settingsW, math.floor(vp.X * 0.64))
            settingsH = math.min(settingsH, math.floor(vp.Y * 0.80))
            SettingsPanel.Size = UDim2.new(1, -36, 1, -86)
            settingsScale.Scale = 1
            advanced.Visible = false
            toastHolder.Size = UDim2.new(0, 250, 0, 0)
        else
            if commandGui then commandGui.Size = UDim2.new(0, 520, 0, 520) end
            commandScale.Scale = 1
            if controlsBtn then controlsBtn.Size = UDim2.new(0, 94, 1, 0) end
            if keysBtn then keysBtn.Size = UDim2.new(0, 94, 1, 0) end
            if diagBtn then diagBtn.Size = UDim2.new(0, 104, 1, 0) end
            if consoleBtn then consoleBtn.Size = UDim2.new(0, 78, 1, 0) end
            if CommandSettingsBtn then CommandSettingsBtn.Size = UDim2.new(0, 78, 1, 0) end
            settingsScale.Scale = 1
            SettingsPanel.Size = UDim2.new(1, -36, 1, -86)
            advanced.Visible = true
            toastHolder.Size = UDim2.new(0, 310, 0, 0)
        end

        local topHolder = TopHolder
        if topHolder then
            if mobile and vp.X < 400 then
                topHolder.Size = UDim2.new(0, 246, 0, 30)
                local topEmotes = topHolder:FindFirstChild("TopBtn")
                local topCommand = topHolder:FindFirstChild("V6CommandButton")
                if topEmotes then
                    topEmotes.Size = UDim2.new(0, 130, 1, -6)
                    topEmotes.Position = UDim2.new(0, 3, 0, 3)
                end
                if topCommand then
                    topCommand.Size = UDim2.new(0, 104, 0, 24)
                    topCommand.Position = UDim2.new(0, 138, 0, 3)
                    topCommand.TextSize = 8
                end
            elseif mobile then
                topHolder.Size = UDim2.new(0, 270, 0, 30)
                local topEmotes = topHolder:FindFirstChild("TopBtn")
                local topCommand = topHolder:FindFirstChild("V6CommandButton")
                if topEmotes then
                    topEmotes.Size = UDim2.new(0, 150, 1, -6)
                    topEmotes.Position = UDim2.new(0, 3, 0, 3)
                end
                if topCommand then
                    topCommand.Size = UDim2.new(0, 108, 0, 24)
                    topCommand.Position = UDim2.new(0, 158, 0, 3)
                    topCommand.TextSize = 8
                end
            end
        end
    end
    updateCommandResponsive()
    if workspace.CurrentCamera then
        workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(updateCommandResponsive)
    end

    if redrawWheel and not _G.EWV6_RedrawWrapped then
        local oldRedrawWheel = redrawWheel
        local pending = false
        local lastHov, lastPage
        redrawWheel = function(hov, page)
            lastHov, lastPage = hov, page
            if pending then return end
            pending = true
            task.defer(function()
                pending = false
                oldRedrawWheel(lastHov, lastPage)
            end)
        end
        _G.EWV6_RedrawWrapped = true
    end

    local oldExec = V6.Play
    function V6:Play(e)
        local result = oldExec(self, e)
        return result
    end

    v6Connect(UserInputService.InputBegan, function(input, gpe)
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

        if gpe then return end
        if V6.State.CommandOpen and (input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.Up) then
            local results = collectCommandResults()
            if #results > 0 then
                if input.KeyCode == Enum.KeyCode.Down then V6.CommandSelection = math.min(#results, V6.CommandSelection + 1)
                else V6.CommandSelection = math.max(1, V6.CommandSelection - 1) end
                local selected = results[V6.CommandSelection]
                V6:Toast("Selected", tostring(selected.Name or "Emote") .. "   -   Enter to play")
            end
        elseif V6.State.CommandOpen and input.KeyCode == Enum.KeyCode.Return then
            local results = collectCommandResults()
            local selected = results[V6.CommandSelection]
            if selected then V6:Play(selected) end
        end
    end)

    v6Connect(ScreenGui.AncestryChanged, function(_, parent)
        if not parent then saveProfile() end
    end)

    task.delay(0.8, function()
        if ScreenGui.Parent then
            V6:Toast("EMOTE WHEEL V6.5", "Professional command center online.")
        end
    end)
    end
end
